typedef struct FileDetails {
    FILE *file;
    char *output_file;
} FileDetails;

void printUsage() {
    printf("Usage: ./program [-d delimiter] [-o output_files] [input_file]\n");
    exit(0);
}

int main(int argc, char **argv) {
    if (argc == 1 || strncmp(argv[1], "--help", 6) == 0) printUsage();

    int n_outputs = 0;
    FileDetails outputFiles[10]; // maximum of 10 output files for now
    char *delimiter = NULL;

    int argIndex = 1;
    while (argIndex < argc && argv[argIndex][0] == '-') {
        if (strncmp(argv[argIndex], "-d", 2) == 0) delimiter = argv[++argIndex];
        else if (strncmp(argv[argIndex], "-o", 2) == 0) outputFiles[n_outputs].output_file = argv[++argIndex];
        ++argIndex;
    }

    FILE *inputFile;
    char buffer[4096]; // buffer size
    if (argIndex == argc) inputFile = stdin; 
    else {
        inputFile = fopen(argv[argIndex], "r");
        if (!inputFile) {
            printf("Error opening file '%s'.\n", argv[1]);
            exit(EXIT_FAILURE);
        }
    }

    int lines = 0, tokens = 0;
    while (fgets(buffer, sizeof(buffer), inputFile)) {
        if (buffer[0] != '#') { // skip comment line 
            ++lines;
            char *token = strtok(buffer, delimiter);
            while (token) {
                ++tokens;
                token = strtok(NULL, delimiter);
            }
        }
    }

    printf("Total lines: %d\n", lines);
    if (delimiter != NULL) printf("Total tokens: %d\n", tokens);

    for (int i = 0; i < n_outputs; ++i) {
        FILE *f = fopen(outputFiles[i].output_file, "w");
        if (!f) {
            printf("Error opening output file '%s'.\n", outputFiles[i].output_file);
            exit(EXIT_FAILURE);
        }

        fprintf(f, "Total lines: %d\n", lines);
        if (delimiter != NULL) fprintf(f, "Total tokens: %d\n", tokens);

        fclose(f);
    }

    if (inputFile != stdin) fclose(inputFile);

    return 0;
}
```
