import java.util.*;

public class Pokemon {
    private String name;
    private List<String> types;

    public Pokemon(String name, List<String> types) {
        this.name = name;
        this.types = types;
    }

    public String getName() {
        return this.name;
    }

    public List<String> getTypes() {
        return this.types;
    }
}

public class WeaknessResolver {

    private static final Map<String, List<String>> weaknesses = new HashMap<>();

    static {
        weaknesses.put("Fire", Arrays.asList("Water"));
        weaknesses.put("Water", Arrays.asList("Grass", "Electric"));
        // Add other types and their weaknesses here...
    }

    public static String getWeaknesses(Pokemon pokemon) {

        if (pokemon == null || pokemon.getTypes() == null || pokemon.getTypes().isEmpty()) {
            return "No weaknesses known.";
        }

        Set<String> result = new HashSet<>();
        for (String type : pokemon.getTypes()) {
            List<String> typeWeaknesses = weaknesses.get(type);
            if (typeWeaknesses != null) {
                result.addAll(typeWeaknesses);
            }
        }

        if (result.isEmpty()) {
            return "No weaknesses known.";
        } else {
            return String.join(", ", result);
        }
    }
}
```
In this code, we use a static block to initialize the weaknesses map with hardcoded data. The getWeaknesses function iterates over each type of the Pokemon and adds its corresponding weaknesses (if they exist) to a Set. This ensures that duplicate weaknesses are not included in the final result. If no weaknesses are found, it returns "No weaknesses known." Otherwise, it joins all weaknesses into a single comma-separated string.
