  // get resource from cache or database
  let cachedResource = await cache.get(req.params.id);
  if (cachedResource) {
    // apply updates to cached data (could also update db here with db.query())
    Object.assign(cachedResource, req.body);
    // store updated resource in cache for subsequent requests
    await cache.set(req.params.id, cachedResource);
  } else {
    let result = await pool.query('SELECT * FROM resources WHERE id = $1', [req.params.id]);
    if (result.rowCount === 0) {
      return res.status(404).json({ error: 'Resource not found' });
    } 

    // apply updates to db data and store in cache for subsequent requests
    Object.assign(result.rows[0], req.body);
    await cache.set(req.params.id, result.rows[0]);
    cachedResource = result.rows[0];
  }

  // log update operation
  logger.log('update', `User ${req.user.username} updated resource ${req.params.id}`);

  return res.json(cachedResource);
});
