['Here is a simplified example of how you might approach this task using ASP.NET Core MVC, C#, Entity Framework and a microservice architecture. 

```csharp
using Microsoft.AspNetCore.Mvc;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;
using System;
using System.Collections.Generic;
using Microsoft.Extensions.Logging;

public class UpdateController : Controller
{
    private readonly ILogger<UpdateController> _logger;
    private readonly IAuthService _authService;
    private readonly IPageSectionService _pageSectionService;
    private readonly IAnalyticsService _analyticsService;
    private static SemaphoreSlim semaphore = new SemaphoreSlim(1, 1); // for handling concurrency.

    public UpdateController(ILogger<UpdateController> logger, IAuthService authService, IPageSectionService pageSectionService, IAnalyticsService analyticsService)
    {
        _logger = logger;
        _authService = authService;
        _pageSectionService = pageSectionService;
        _analyticsService = analyticsService;
    }

    [HttpPost]
    public async Task<IActionResult> UpdatePage([FromBody] UpdateModel model) 
    {
        try
        {
            await semaphore.WaitAsync(); // wait to get access for the critical section (DB write operation).

            // Fetch user authentication details and analytics tracking.
            var user = await _authService.GetUser(model.UserId); 
            await _analyticsService.TrackEvent("Update Started");

            // Update element's HTML content using service class.
            await _pageSectionService.UpdateElementContentAsync(model.PageSectionId, model.ElementId, model.HtmlContent);

            _logger.LogInformation($"Update of Element {model.ElementId} on Page Section {model.PageSectionId} done by User {user.UserName} at {DateTime.Now}. New Content: {model.HtmlContent}");

            // Return a response indicating that the page should be refreshed.
            return Json(new { Result = "Refresh" });
        } 
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Update of PageSectionID:{model.PageSectionId}, ElementID:{model.ElementId} failed.");
            return BadRequest();
        }
        finally
        {
            semaphore.Release(); // release the critical section for other threads to use.
        }
    }
}
```
In this example, `UpdateModel` represents data transfer object that includes user id, page section id, element id and HTML content. The dependencies (services) are injected via constructor injection. A semaphore is used for managing concurrent updates ensuring data integrity and preventing race conditions.
