async function extractProductNames(text, categories){
    // Fetching the external data asynchronously
    const regexPatterns = await fetchRegexPatterns(); 

    let productCounts = {};

    for (let category of categories) {
        if (!regexPatterns[category]) continue;

        const regexes = Object.values(regexPatterns[category]);

        for (const regex of regexes) {
            const matches = text.match(new RegExp(`\\b${regex}\\b`, 'gi')); 

            if (!matches) continue;

            matches.forEach((productName) => {
                productName = productName.toLowerCase();

                if (productCounts[productName]) {
                    productCounts[productName]++;
                } else {
                    productCounts[productName] = 1;
                }
            });
        }
    }

    return productCounts;
}
