#include <forward_list>
#include <string>

void insertURL(std::forward_list<std::string>& flist, const std::string& resID, const std::string& url) {
    auto prev = flist.before_begin();
    for (auto it = flist.begin(); it != flist.end(); ++it) {
        if (*it == resID) {
            flist.insert_after(it, url);
            return;
        }
        prev = it;
    }
    flist.insert_after(prev, url);
}
```
This function iterates through the forward list using a forward iterator and checks if each string matches the resource ID. If a match is found, the URL is inserted after the current position of the iterator. If no match is found in the entire list, the URL is appended at the end of the list.

JavaScript Function:
