function refreshFields($scope, $window, fieldNames) {
    angular.forEach(fieldNames, function (name) {
        if ($scope[name]) {
            $window.postMessage({ 'type': 'refresh', 'data': name }, '*');
            // Here we are assuming that when the parent window receives the message and processes it successfully, 
            // it sends back a result through $window.onmessage event
            // If successful, we update the scope property to reflect the new value
            $window.onmessage = function (event) {
                if (event.data.type === 'result' && event.data.data.name === name) {
