```java
import java.util.concurrent.*;
import java.util.Properties;
import java.io.FileInputStream;
import java.io.IOException;
import java.time.Instant;
import com.example.messagingSystemAPI.*;
import com.example.healthCheckUtilities.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class ServiceManager {
    private static final Logger logger = LoggerFactory.getLogger(ServiceManager.class);
    private ExecutorService executorService;
    private Properties properties;

    public ServiceManager() {
        this.executorService = new ThreadPoolExecutor(0, 20, 60L, TimeUnit.SECONDS, new SynchronousQueue<Runnable>());
        this.properties = new Properties();

        try (FileInputStream fis = new FileInputStream("config.properties")) {
            properties.load(fis);
        } catch (IOException e) {
            logger.error("Failed to load config file", e);
        }
    }

    public void startService(final Service service) {
        executorService.submit(() -> {
            if (!service.start()) {
                scheduleRestart(service, Instant.now().plusSeconds(10));
            } else {
                logger.info("Service {} started successfully", service.getName());
            }
        });
    }

    private void scheduleRestart(final Service service, final Instant restartTime) {
        executorService.submit(() -> {
            try {
                Thread.sleep(Duration.between(Instant.now(), restartTime).toMillis());
            } catch (InterruptedException e) {
                logger.error("Restart of service {} was interrupted", service.getName(), e);
                return;
            }

            if (!service.start()) {
                scheduleRestart(service, Instant.now().plusSeconds(10));
            } else {
                logger.info("Service {} restarted successfully", service.getName());
            }
        });
    }

    public void stopService(final Service service) {
        service.stop();
        logger.info("Service {} stopped successfully", service.getName());
    }
}
```
This code provides a basic structure for managing services with health checks and restarts. The `startService` method starts the service and schedules a restart if it fails to start within 10 seconds. This is done by submitting a new task to the executor service that waits for 10 seconds before trying to start the service again.

Please note, this code doesn't contain all necessary classes/interfaces like `Service`, `MessagingSystemAPI`, `HealthCheckUtilities` and configuration file handling. The actual implementation will depend on your specific requirements and environment. It is also important to handle exceptions correctly in production-level code.
