```rust
use std::collections::HashMap;
use reqwest::header::{HeaderValue, Headers};
use std::thread;
use std::time::Duration;

pub fn create_client(url: &str, disable_cert_verification: bool) -> Result<reqwest::RequestBuilder, Box<dyn std::error::Error>> {
    let client = reqwest::Client::builder()
        .danger_accept_invalid_certs(disable_cert_verification) // Optional certificate validation
        .build()?;

    Ok(client.get(url))
}

pub fn set_headers(request: reqwest::RequestBuilder, headers: HashMap<&str, &str>) -> reqwest::RequestBuilder {
    let mut request = request;
    for (key, value) in headers {
        request = request.header(key, HeaderValue::from_static(value));
    }

    request
}

pub fn handle_retries(request: reqwest::RequestBuilder, retries: u32) -> Result<reqwest::Response, Box<dyn std::error::Error>> {
    let mut response = None;
    for retry in 0..retries {
        if retry > 0 {
            thread::sleep(Duration::from_secs((2u64.pow(retry)))); // Exponential backoff
        }

        response = match request.send() {
            Ok(res) => Some(res),
            Err(_) if retry < retries - 1 => None,
            Err(e) => return Err(Box::new(e)),
        };
    }

    Ok(response.unwrap()) // Unwrap is safe here as the error propagation handles a failed final attempt
}
```
This code does not include rate limiting, which would require more complex logic and likely to be managed at a higher level (i.e., in a larger system or framework). 

Also note that this is a simple example. In a real-world application, you'd want to use something like `rate_limiter` crate for managing rate limits. Also it would handle errors more gracefully and provide meaningful error messages.
"]

