        unsafe {
            let mut buf = Vec::new();
            write![&mut buf, fmt];
            let elapsed_time = start.elapsed();

            println![format![fmt, args], "Time taken: {} secs", elapsed_time.as_secs()];

            let before_size = std::process::id().map(|p| p.get_resident_set_size()).unwrap();
            EARLY_ERROR(&*format![fmt, args]); // Call early error function here
            let after_size = std::process::id().map(|p| p.get_resident_set_size()).unwrap();

