```php
<?php 
use Predis\Client as Redis;
use GuzzleHttp\Client;

class UserDao {
    private $pdo;
    private $redis;
    private $httpClient;

    public function __construct() {
        $this->pdo = new PDO('DSN', 'USERNAME', 'PASSWORD'); //Replace DSN, USERNAME, PASSWORD with your values
        $this->redis = new Redis(); 
        $this->httpClient = new Client(['base_uri' => 'https://example.com']); //replace with your API endpoint
    }

    public function updatePassword($userId, $newPassword) {
        if (!$this->validatePasswordStrength($newPassword)) {
            $this->logFailedAttempt('Invalid password strength', $userId);
            throw new Exception("New Password does not meet strength requirements.");
        } 

        $email = $this->getEmailForUser($userId); // assuming the database has an email field associated with each user.

        if (!$this->isValidEmail($email)) {
            $this->logFailedAttempt('Invalid email', $userId);
            throw new Exception("Associated email is not valid.");
        } 

        if ($this->exceedsRateLimit($userId)) {
            $this->logFailedAttempt('Exceeded rate limit', $userId);
            throw new Exception("Rate limit exceeded. Please try again later.");
        }

        $hashedPassword = password_hash($newPassword, PASSWORD_DEFAULT); // use PHP's inbuilt function to hash the password

        $stmt = $this->pdo->prepare('UPDATE users SET password=? WHERE id=?');
        if ($stmt->execute([$hashedPassword, $userId])) {
            $this->redis->del($this->getRateLimitKey($userId)); // clear rate limit cache after successful update.
            return true;
        } else {
            throw new Exception("Error occurred while updating password.");
        }
    }

    private function validatePasswordStrength($password) {
        $uppercase = preg_match('@[A-Z]@', $password);
        $lowercase = preg_match('@[a-z]@', $password);
        $number    = preg_match('@[0-9]@', $password);
        $specialChars = preg_match('@[^\w]@', $password);

        return strlen($password) >= 12 && $uppercase && $lowercase && $number && $specialChars;
    }

    private function exceedsRateLimit($userId) {
        $key = $this->getRateLimitKey($userId);

        if (!$this->redis->exists($key)) {
            $this->redis->setex($key, 60, 1); // set a new rate limit key with expiry of 60 seconds (for 1 minute)
            return false;
        }

        $attempts = $this->redis->incr($key);
        return $attempts > 3;
    }

    private function getRateLimitKey($userId) {
        return 'rate_limit:' . $userId;
    }

    private function logFailedAttempt($reason, $userId) {
        $stmt = $this->pdo->prepare('INSERT INTO failed_login_attempts (timestamp, user_id, reason) VALUES (?, ?, ?)');
        $stmt->execute([time(), $userId, $reason]); 
    }

    private function getEmailForUser($userId){
        // Assume this method retrieves the email from DB for a given userID.
    }

    private function isValidEmail($email) {
        $response = $this->httpClient->request('GET', 'validate_email', ['query' => ['email' => $email]]);  // Assuming API endpoint is '/validate_email?email=<email>'
        return json_decode($response->getBody(), true)['valid'];   // assuming API returns a JSON response like {"valid": true/false}
    }
}
```
