    State *stateList;
    int numStates;
} FSA;

State* createAndAppendNewState(FSA* fsa, int newId) {
    State* newState = (State*)malloc(sizeof(State));

    if(!newState) return NULL; // Check for insufficient memory.

    newState->id = newId;
