['```csharp
using System;
using System.Threading;
using System.IO;
using System.Net;

public class DataGenerator {
    private int seed;
    private float minRange, maxRange;
    private static readonly object locker = new object();

    public DataGenerator(int seed) {
        this.seed = seed;
        Random rand = new Random(this.seed);
        this.minRange = 0f;
        this.maxRange = 1f;
    }

    public void UpdateRange(float min, float max) {
        lock (locker) {
            if (min >= max) throw new ArgumentException("Minimum range should be less than maximum");
            this.minRange = min;
            this.maxRange = max;
        }
    }

    public int GenerateRandomInt() {
        lock (locker) {
            Random rand = new Random(Interlocked.Increment(ref seed));
            return rand.Next((int)minRange, (int)maxRange + 1);
        }
    }

    public float GenerateRandomFloat() {
        lock (locker) {
            Random rand = new Random(Interlocked.Increment(ref seed));
            return minRange + (float)rand.NextDouble() * (maxRange - minRange);
        }
    }

    public string GenerateRandomString(int length) {
        lock (locker) {
            Random rand = new Random(Interlocked.Increment(ref seed));
            const string chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
            return new string(Enumerable.Repeat(chars, length)
              .Select(s => s[rand.Next(s.Length)]).ToArray());
        }
    }

    public void SetSeedFromExternalSource(string sourceType){
         if (sourceType == "http"){
             HttpWebRequest request = WebRequest.CreateHttp("http://example.com/seed");
             using (HttpWebResponse response = (HttpWebResponse)request.GetResponse()) {
                 if (response.StatusCode != HttpStatusCode.OK) return;
                 using (Stream receiveStream = response.GetResponseStream()){
                     seed = BitConverter.ToInt32(ReadFully(receiveStream), 0);
                 }
             }
         } else if (sourceType == "file"){
            try {
                byte[] data = File.ReadAllBytes("path_to_seed_file");
                seed = BitConverter.ToInt32(data, 0);
            } catch {}
        }
    }

    private static byte[] ReadFully(Stream input) {
        using (MemoryStream ms = new MemoryStream()) {
            input.CopyTo(ms);
            return ms.ToArray();
        }
    }
}
```  
