#include <sys/types.h>
#include <sys/wait.h>

int cmd_exec(const char *cmd) {
    pid_t pid = fork();

    if (pid == 0) { // Child process
        execl("/bin/sh", "sh", "-c", cmd, NULL);
        return -1;
    } else if (pid < 0) {
        perror("fork failed");
        return -1;
    } else {
        int status;
        waitpid(pid, &status, 0); // Parent process waits for child to terminate
        if (WIFEXITED(status))
            return WEXITSTATUS(status);
        else
            return -1;
    }
}
