['```csharp
using System;
using System.Text;
using System.Security.Cryptography;

public class DecryptionException : Exception {
    public DecryptionException(string message) : base(message) {}
}

public static string TripleDESDecryptor(string encryptedMessage, byte[] key, byte[] iv) {
    if (encryptedMessage == null || encryptedMessage.Length == 0) {
        return String.Empty;
    } 

    if (key.Length != 16 && key.Length != 24 && key.Length != 32) {
        throw new DecryptionException("Invalid key length");
    }

    if (iv.Length != 8) {
        throw new DecryptionException("Invalid IV length");
    }

    try {
        using (TripleDES des = TripleDES.Create()) { 
            byte[] encryptedBytes = Convert.FromBase64String(encryptedMessage); 

            des.Mode = CipherMode.CBC;
            des.Key = key;
            des.IV = iv;

            using (ICryptoTransform decryptor = des.CreateDecryptor()) {
                byte[] resultBytes = decryptor.TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);  
                return Encoding.UTF8.GetString(resultBytes);
            }
        }
    } catch (CryptographicException e) {
        throw new DecryptionException("Decryption failed: " + e.Message);
    }
}
```
