using System;
using System.IO;
using System.Text;
using System.Security.Cryptography;

public static class AESDecryptionService
{
    private static readonly object Lock = new object();

    public enum PaddingSchemes { PKCS7, ANSIX923, ISO10126 };

    public static byte[] Decrypt(byte[] ciphertext, byte[] key, byte[] iv, PaddingSchemes paddingScheme, byte[] hmacKey)
    {
        try
        {
            // Validate inputs
            if (key == null || key.Length != 32) throw new ArgumentException("Invalid key");
            if (iv == null || iv.Length != 16) throw new ArgumentException("Invalid IV");
            if (!Enum.IsDefined(typeof(PaddingSchemes), paddingScheme)) throw new ArgumentException("Invalid padding scheme");
            if (hmacKey == null || hmacKey.Length == 0) throw new ArgumentException("Invalid HMAC key");

            byte[] decryptedData;
            // Lock to prevent data corruption when accessed concurrently by multiple threads
            lock (Lock)
            {
                using (var aes = Aes.Create())
                {
                    if (aes == null) throw new Exception("Unable to create AES provider");

                    aes.Key = key;
                    aes.IV = iv;
                    aes.Padding = paddingScheme switch
                    {
                        PaddingSchemes.PKCS7 => PaddingMode.PKCS7,
                        PaddingSchemes.ANSIX923 => PaddingMode.ANSIX923,
                        PaddingSchemes.ISO10126 => PaddingMode.ISO10126,
                        _ => throw new ArgumentException("Invalid padding scheme")
                    };

                    using (var decryptor = aes.CreateDecryptor(aes.Key, aes.IV))
                    {
                        decryptedData = DecryptWithHMACVerification(ciphertext, hmacKey, decryptor);
                    }
                }
            }

            return decryptedData;
        }
        catch (Exception ex)
        {
            // Log exception here
            Console.WriteLine("Decryption failed: " + ex.Message);
            throw;
        }
    }

    private static byte[] DecryptWithHMACVerification(byte[] ciphertext, byte[] hmacKey, ICryptoTransform decryptor)
    {
        // Verify HMAC first
        using (var hmac = new HMACSHA256(hmacKey))
        {
            var hashLength = hmac.HashSize / 8;
            if (ciphertext.Length < hashLength) throw new Exception("Ciphertext is too short for HMAC");

            var expectedHMAC = ciphertext[..hashLength];
            var actualHMAC = ComputeHMAC(hmac, ciphertext[hashLength..]);

            if (!actualHMAC.SequenceEqual(expectedHMAC)) throw new Exception("HMAC verification failed");
        }

        // If HMAC is validated, proceed with decryption
        using (var ms = new MemoryStream(ciphertext))
        {
            using var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read);
            using var sr = new StreamReader(cs, Encoding.UTF8);
            return Encoding.ASCII.GetBytes(sr.ReadToEnd());
        }
    }

    private static byte[] ComputeHMAC(HashAlgorithm hmac, byte[] data)
    {
        var hash = hmac.ComputeHash(data);
        Array.Resize(ref hash, hmac.HashSize / 8); // Truncate the hash to match the expected length
        return hash;
    }
}
```
This code uses AES in CBC mode with the provided padding scheme for decryption and also includes a HMAC verification step to ensure data integrity during decryption. The function is thread-safe due to the lock mechanism used. The code logs any exceptions that occur, but does not handle them beyond logging. It will return a byte array of the decrypted plaintext if successful, or throw an exception with a descriptive message otherwise.
