```javascript
const axios = require('axios');
const NodeCache = require("node-cache");
const { get } = require('lodash/fp');

// Create an instance of node cache with ttl set to 10 minutes (600 seconds)
const cache = new NodeCache({ stdTTL: 600, checkperiod: 120 });

async function fetchUserData(userId) {
    const cachedResponse = cache.get(userId);

    if (cachedResponse) {
        // If we have a cached response, return it
        return cachedResponse;
    } else {
        try {
            // Fetch the user data from the remote API
            const response = await axios.get(`https://api.yourwebsite.com/users/${userId}`);

            // Store the response in cache with a ttl of 600 seconds
            cache.set(userId, response.data, 600);

            return response.data;
        } catch (error) {
            console.error('An error occurred while fetching user data:', error);
            throw error;
        }
    }
}

// If you want to fetch multiple users in parallel, use Promise.all
async function fetchMultipleUsers(userIds) {
    return await Promise.all(userIds.map(fetchUserData));
}
```

This code uses a Node.js-based in-memory caching system (node-cache). This has the benefit of being fast, but it also consumes memory proportional to the number and size of your cached items. For high load conditions, you might want to consider using an external cache like Redis or Memcached which will be more efficient at handling large amounts of data in memory.

The function `fetchUserData` first checks if there's a cached response for the user ID; if not, it makes a request to the API and stores the result in the cache. The function is designed with error handling in mind: If an error occurs during the API request, it gets logged, but the error isn't thrown or returned unless you want to handle it at a higher level (like in your main application logic).
