```rust
extern crate futures;
extern crate reqwest;
extern crate tokio;

use std::env;
use futures::future::{Future, IntoFuture};
use reqwest::header::HeaderMap;
use tokio::runtime::Runtime;

const API_URL: &str = "YOUR_API_URL";
const API_KEY: &str = "YOUR_API_KEY";

struct LoggingService {
    client: reqwest::Client,
}

impl LoggingService {
    fn new() -> Self {
        let client = reqwest::Client::builder().build().unwrap();
        Self { client }
    }

    async fn log(&self, message: &str) -> Result<(), Box<dyn std::error::Error>> {
        let mut headers = HeaderMap::new();
        headers.insert("Authorization", API_KEY.parse().unwrap());

        self.client.post(API_URL).headers(headers).body(message).send().await?;

        Ok(())
    }
}

fn main() {
    let mut runtime = Runtime::new().unwrap();
    let args: Vec<String> = env::args().collect();
    let command = &args[1];
    let logging_service = LoggingService::new();

    match command.as_str() {
        "log" => runtime.spawn(logging_service.log("Logging a message...")),
        _ => printlnhim/spawn(logging_service.log("Unknown command...")),
    };
}
```
In this code, we create a `LoggingService` struct that has a `reqwest::Client` as its field to interact with the external logging API. The `log` method sends a POST request to the API with an Authorization header using your API key and a body containing your message.

