['```rust
use std::sync::Mutex;
use std::env;
use std::fs::{self, DirEntry};
use std::thread;
use std::time::Duration;

pub struct DirectoryManager {
    mutex: Mutex<()>,
}

impl DirectoryManager {
    pub fn new() -> Self {
        Self { mutex: Mutex::new(()) }
    }

    // Function to create a directory if it doesn't exist and set the environment variable.
    pub fn get_directory(&self, unique_id: &str) -> Result<(), String> {
        let lock = self.mutex.lock().unwrap();

        match env::var(format![TEMP_DIR_{}", unique_id]) {
            Ok(_) => {},
            Err(_) => {
                let dir = fs::create_dir(format![temp_dir_{}", unique_id]).map_err(|e| format![Failed to create directory: {}", e])?;
                env::set_var(format![TEMP_DIR_{}", unique_id], dir.path().to_str().unwrap());
            }
        };

        Ok(())
    }

    // Function for cleaning up directories if they're empty after a certain period of inactivity (10 minutes) asynchronously.
    pub fn cleanup(&self, unique_id: &str) {
        let lock = self.mutex.lock().unwrap();

        thread::spawn(move || {
            loop {
                thread::sleep(Duration::from_secs(10 * 60)); // Sleep for 10 minutes.

                match env::var(format![TEMP_DIR_{}", unique_id]) {
                    Ok(path) => {
                        let entries = fs::read_dir(&path).unwrap();

                        if entries.count() == 0 {
                            fs::remove_dir_all(&path).map_err(|e| println![Error cleaning up directory: {}", e]); // Log any errors encountered during cleanup.
                        }
                    },
                    Err(_) => {},
                }
            }
        });
    }
}
```
