        self._providers = []

    def add_provider(self, provider):
        # Adding a new provider has O(1) complexity.
        self._providers.append(provider)

    def remove_provider(self, provider):
        # Removing a provider is also O(1).
        self._providers.remove(provider)

    def get_value(self, key):
        for provider in self._providers:
            try:
                return provider.get_value(key)
            except KeyError:
                pass
        # If no providers have the key, try the default values.
        return self._default_values.get(key)


class ConfigManager:
    def __init__(self):
        self._contexts = {}

    def add_context(self, name, context):
        # Adding a new context has O(1) complexity.
        self._contexts[name] = context

    def remove_context(self, name):
        # Removing a context is also O(1).
        del self._contexts[name]

    def get_value(self, context_name, key):
        return self._contexts[context_name].get_value(key)
