    }
}

int find_max(const int* array, size_t n) {
    if (n == 0) return -1; // error: no elements in the array

    int max = array[0];

    for (size_t i = 1; i < n; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }

    return max;
}

int main() {
    const int MAX_SIZE = 1000;

    NFAPI_CRC_INDICATION_PDU_T* structures = malloc(MAX_SIZE * sizeof(*structures));
    if (structures == NULL) {
        printf("Memory allocation failed\n");
        return 1; // error: memory allocation failure
    }

    populate_structures(structures, MAX_SIZE);

    int array[MAX_SIZE];
    for (int i = 0; i < MAX_SIZE; ++i) {
        if (scanf("%d", &array[i]) != 1) { // error: invalid input
            printf("Invalid input\n");
            free(structures);
            return 1;
        }
    }

    int max = find_max(array, MAX_SIZE);
    printf("Max value in array is %d\n", max);

    free(structures); // don't forget to free the memory
    return 0;
}
