typedef struct {
    int value;
} record_t;

void handle_error(const char *msg) {
    ERR_print_errors_fp(stderr);
    fprintf(stderr, "%s\n", msg);
    exit(EXIT_FAILURE);
}

void initialize_records(int num_records, int min_val, int max_val) {
    long *offsets;
    int *keys;
    record_t *records;
    OPENSSL_init();

    offsets = malloc(num_records * sizeof(long));
    keys = calloc(num_records, sizeof(int));
    records = malloc(num_records * sizeof(record_t));

    if (offsets == NULL || keys == NULL || records == NULL) {
        handle_error("Memory allocation failed.");
    }

    for (int i = 0; i < num_records; ++i) {
        unsigned char random_bytes[sizeof(int)];
        if (!RAND_bytes(random_bytes, sizeof(random_bytes))) {
            handle_error("Failed to generate random bytes.");
        }

        int value = min_val + (((unsigned int) *random_bytes) % (max_val - min_val + 1));
        records[i].value = value;
    }

    // use the allocated memory here...

    free(offsets);
    free(keys);
    free(records);
}
