// For simplicity, let's assume union-find data structure is represented as an array.
typedef struct UnionFind {
    int size;
    int *parent;
    int *rank;
} UnionFind;

UnionFind* createUnionFind(int n) {
    UnionFind *uf = malloc(sizeof(UnionFind));

    if (uf == NULL) return NULL;

    uf->size = n;
    uf->parent = calloc(n, sizeof(int));
    uf->rank = calloc(n, sizeof(int));

    if (uf->parent == NULL || uf->rank == NULL) {
        free(uf->parent);
        free(uf->rank);
        free(uf);
        return NULL;
    }

    for (int i = 0; i < n; ++i)
        uf->parent[i] = i;

    return uf;
}

void destroyUnionFind(UnionFind *uf) {
    free(uf->parent);
    free(uf->rank);
    free(uf);
}

// A simple implementation, for performance optimization, consider path compression and union by rank.
int findParent(UnionFind *uf, int i) {
    if (uf->parent[i] != i)
        uf->parent[i] = findParent(uf, uf->parent[i]);

    return uf->parent[i];
}

void unionElements(UnionFind *uf, int x, int y) {
    int xroot = findParent(uf, x);
    int yroot = findParent(uf, y);

    if (uf->rank[xroot] < uf->rank[yroot])
        uf->parent[xroot] = yroot;
    else if (uf->rank[xroot] > uf->rank[yroot])
        uf->parent[yroot] = xroot;
    else {
        uf->parent[yroot] = xroot;
        ++uf->rank[xroot];
    }
}

UEContext* createContext(int UE_ID, char *measurementReport) {
    UEContext *context = malloc(sizeof(UEContext));

    if (context == NULL) return NULL;

    context->UE_ID = UE_ID;
    context->measurementReport = strdup(measurementReport);

