    context->reportConfig = createReportConfig(reportingInterval);

    return context;
}

void destroyContext(UEContext *context) {
    free(context->measurementReport);
    // Assume that we have a function to destroy the Reporting Configuration.
    destroyReportConfig(context->reportConfig);
    free(context);
}
