// Function to validate UE IDs and ensure uniqueness. Returns 1 if unique, else returns 0.
int isValidAndUnique(char* id) {
    pthread_mutex_lock(&listLock);
    for (int i = 0; i < numOfUEs; ++i) {
        if (!strcmp(contextList[i].UEID, id)) {
            pthread_mutex_unlock(&listLock);
            return 0;
        }
    }
    pthread_mutex_unlock(&listLock);
    return 1;
}

// Function to create UE Contexts dynamically. Returns a pointer to the created context if successful, else returns NULL.
UEContext* createUEContext(char* id) {
  if (!isValidAndUnique(id)) {
