  pthread_mutex_lock(&listLock);
  contextList = (UEContext*)realloc(contextList, sizeof(UEContext) * ++numOfUEs);
  if (contextList == NULL) {
    printf("Error: Memory reallocation failed.\n");
    return NULL;
  }

  contextList[numOfUEs - 1] = *newContext;
  pthread_mutex_unlock(&listLock);

  free(newContext);
  return &contextList[numOfUEs - 1];
}
