// Structure to hold the connection info
typedef struct {
    int client_sock;
    int server_sock;
    unsigned long timeout;
} Connection;

// Global array of connections and lock for thread safety
Connection* connections[1000];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void establishConnection(int client, int server, unsigned long timeout) {
    // Create connection structure
    Connection* conn = malloc(sizeof(Connection));
    if (conn == NULL) {
        perror("Memory allocation failed");
        return;
    }

    conn->client_sock = client;
    conn->server_sock = server;
    conn->timeout = timeout;

    // Lock the mutex to protect access to connections array
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < 1000; ++i) {
        if (connections[i] == NULL) {  // If slot is empty, insert connection
            connections[i] = conn;
            break;
        }
    }

    pthread_mutex_unlock(&mutex);  // Release lock
}

void terminateConnection(int sockfd) {
    // Lock the mutex to protect access to connections array
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < 1000; ++i) {
        if (connections[i] != NULL && 
            (connections[i]->client_sock == sockfd || 
             connections[i]->server_sock == sockfd)) {  // If connection matches socket descriptor, delete it

            free(connections[i]);  // Free memory for the connection structure
            connections[i] = NULL;  // Remove reference from array
        }
    }

    pthread_mutex_unlock(&mutex);  // Release lock
}
```
This code only manages a list of TCP socket file descriptors, it does not include handling these sockets or timeouts. The real implementation would require further work with system and network programming concepts.
