int findLargest(const int *arr, const size_t arrSize) {
    if (arr == NULL || arrSize == 0) return INT_MIN; 
    int max = arr[0];
    for (size_t i = 1; i < arrSize; ++i) {
        if(max<arr[i]) max=arr[i];
    }
    return max;
}

void createPDUListAndFindLargest(int initVal, size_t nPDUs, size_t listSize){
    sem_t semaphore;
    if (sem_init(&semaphore, 0, initVal) != 0) {
        perror("Semaphore initialization failed");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T *pduList = malloc(nPDUs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pduList == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    int *arr = malloc(listSize * sizeof(int));
    if (arr == NULL) {
        perror("Memory allocation failed");
        free(pduList);  // Free previously allocated memory to avoid leaks.
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < nPDUs; ++i) {
        pduList[i].info.RNTI = rand() % 65535 + 1;  // RNTI is between 1 and 65535
        pduList[i].info.CRCFLAG = rand() % 2;  // CRCFLAG is either 0 or 1
    }

    for (size_t i = 0; i < listSize; ++i) {
        scanf("%d", &arr[i]);  
    }

    printf("Largest number: %d\n", findLargest(arr, listSize));

    free(pduList);
    free(arr);

    if (sem_destroy(&semaphore) != 0) {
        perror("Semaphore deletion failed");
        exit(EXIT_FAILURE);
    }
}
