    *offsetArrayPtr = malloc(recordsNumber * sizeof(long));
    if (*offsetArrayPtr == NULL) {
        printf("Memory allocation failed for 'offset' array.\n");
        return;
    }

    *keyArrayPtr = malloc(recordsNumber * sizeof(int));
    if (*keyArrayPtr == NULL) {
        printf("Memory allocation failed for 'key' array.\n");
        free(*offsetArrayPtr); // Free already allocated memory
        return;
    }

    *valueArrayPtr = malloc(recordsNumber * sizeof(float));
    if (*valueArrayPtr == NULL) {
        printf("Memory allocation failed for 'value' array.\n");
        free(*offsetArrayPtr); // Free already allocated memory
        free(*keyArrayPtr);
        return;
    }

    *dataRecordsPtr = malloc(recordsNumber * sizeof(dataRecord));
    if (*dataRecordsPtr == NULL) {
        printf("Memory allocation failed for 'dataRecord' array.\n");
        free(*offsetArrayPtr); // Free already allocated memory
        free(*keyArrayPtr);
        free(*valueArrayPtr);
        return;
    }

    for (size_t i = 0; i < recordsNumber; ++i) {
        (*offsetArrayPtr)[i] = rand() % 1000; // random value from 0 to 999
        (*keyArrayPtr)[i] = rand() % 500 + 500; // random value from 500 to 1000
