void logError(char* msg) {
    pthread_mutex_lock(&mutex);
    if (logFile != NULL) {
        time_t t = time(NULL);
        struct tm *tmp = localtime(&t);
        fprintf(logFile, "%d-%02d-%02d %02d:%02d:%02d - %s\n", tmp->tm_year + 1900, tmp->tm_mon + 1, 
