    if (numRecords < 1 || numRecords > INT_MAX) return -1;  // Check for valid number of records

    srand((unsigned) time(NULL));
    int i;
    record_t* rec = malloc(sizeof(record_t)*numRecords);

    if (rec == NULL) {   // Allocate memory and check if successful
