void allocate_and_initialize(long **offsets, int **keys, float **values, data_point **data_points, 
                              size_t num_elements, long offset[], int keys[]) {

    srand((unsigned int)time(NULL));

    // Allocate and initialize arrays
    *offsets = malloc(num_elements * sizeof(long));
