['Here is an example of how you might implement this in C using the libzip library for compressing files, the cJSON library for parsing JSON, and the open source randutils library to generate random numbers. Note that this is a high-level design and does not include error handling or optimization. Actual implementation would require more detailed requirements.

```c
#include <stdlib.h>
#include <string.h>
#include <zip.h>
#include <math.h>
#include <randutils/randutils.hpp>
#include "cJSON.h"

typedef struct data_entry {
    double value;
    int count;
    char* message;
} data_entry;

int compressFiles(const char* dirPath, const char* outFile) {
    zip *z = zip_open(outFile, ZIP_CREATE, NULL);
    if (z == NULL) {
        // handle error
        return 1;
    }

    DIR *dir;
    struct dirent *ent;
    if ((dir = opendir (dirPath)) != NULL) {
      while ((ent = readdir (dir)) != NULL) {
          char* fileName = ent->d_name;
          zip_source_t *s = zip_source_file(z, fileName, 0, 0);
          if (zip_add(z, fileName, s) < 0) {
              // handle error
              return 1;
          }
      }
      closedir (dir);
    } else {
        /* could not open directory */
        // handle error
        return 1;
    }

    zip_close(z);
    return 0;
}

int main() {
    cJSON *json = cJSON_Parse("your-json-string");
    const double minVal = cJSON_GetObjectItem(json, "minValue")->valuedouble;
    const double maxVal = cJSON_GetObjectItem(json, "maxValue")->valuedouble;
    const int minCount = cJSON_GetObjectItem(json, "minCount")->valueint;
    const int maxCount = cJSON_GetObjectItem(json, "maxCount")->valueint;

    randutils::default_engine re{};
    randutils::uniform_distribution<double> distVal{ minVal, maxVal };
    randutils::uniform_distribution<int> distCount{ minCount, maxCount };

    const int n = cJSON_GetArraySize(cJSON_GetObjectItem(json, "messages"));
    double *values = malloc(n * sizeof(double));
    int *counts = malloc(n * sizeof(int));
    char **messages = malloc(n * sizeof(char*));

    for (int i = 0; i < n; ++i) {
        values[i] = distVal(re);
        counts[i] = distCount(re);

        const cJSON* jsonMessage = cJSON_GetArrayItem(cJSON_GetObjectItem(json, "messages"), i);
        size_t messageLength = strlen(jsonMessage->valuestring) + 1;
        messages[i] = malloc(messageLength);
        strncpy(messages[i], jsonMessage->valuestring, messageLength);
    }

    data_entry *entries = malloc(n * sizeof(data_entry));
    for (int i = 0; i < n; ++i) {
        entries[i].value = values[i];
        entries[i].count = counts[i];
        entries[i].message = messages[i];
    }

    compressFiles("your-directory", "your-output.zip");

    for (int i = 0; i < n; ++i) {
        free(messages[i]);
    }
    free(values);
    free(counts);
    free(messages);
    free(entries);
    return 0;
}
```
This code is a starting point and you need to adjust according to your needs. It's important to note that error handling in the real world code would be much more comprehensive than this. Be sure to check all `malloc` calls, `cJSON_Parse` call and others for errors. You also should close the files, free memory and handle other resources properly.
']

