#include <random>
#include <iostream>
#include <unordered_map>

namespace MyNamespace {
    class RandomNumberGenerator {
        static std::mt19937 gen;
    public:
        RandomNumberGenerator() {}
        ~RandomNumberGenerator() = default;

        int generate(int min, int max) {
            std::uniform_int_distribution<> dis(min, max);
            return dis(gen);
        }
    };
    std::mt19937 RandomNumberGenerator::gen((std::random_device())());
}

extern "C" struct record{ int value; };

void allocateAndInitialize(int numRecords) {
    if (numRecords < 1 || numRecords > 1000) {
        std::cerr << "Invalid number of records. It must be between 1 and 1000." << std::endl;
        return;
    }

    MyNamespace::RandomNumberGenerator rng;
    long* offsets = new long[numRecords]; // Statically allocated, assuming size known at compile time
    int* keys = new int[numRecords]; // Dynamically allocated if size not known at compile time
    record* records = new record[numRecords];

    std::unordered_map<int, bool> keyMap;

    for (int i = 0; i < numRecords; ++i) {
        offsets[i] = i * sizeof(record); // For simplicity of the example, assuming offset is increment by record size

        int key;
        do{
            key = rng.generate(1, INT_MAX);
        } while (keyMap.find(key) != keyMap.end());
        keys[i] = key;
        keyMap[key] = true;

        records[i].value = key; // For simplicity of the example, assuming record value is same as its key
    }

    std::cout << "Total memory allocated: " << 2*numRecords*sizeof(int) + numRecords*sizeof(record) + 2*sizeof(long*) << " bytes" << std::endl;

    // Clean up dynamically allocated memory 
    delete[] offsets;
    delete[] keys;
    delete[] records;
}
```
