void* sendHeartbeat(void *arg) {
    int id = *((int*) arg);
    Connection* conn = connections[id];

    pthread_mutex_lock(&conn->mutex);
    // Send heartbeat message and handle response here.
    printf("Sending heartbeat for connection %d\n", id);
    pthread_mutex_unlock(&conn->mutex);

    return NULL;
}

void addConnection(int client, int server, int timeout) {
    Connection* conn = malloc(sizeof(Connection));
    if (conn == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    conn->client_socket = client;
    conn->server_socket = server;
    conn->timeout_interval = timeout;
    pthread_mutex_init(&conn->mutex, NULL);

    pthread_mutex_lock(&countMutex);
    if (connectionCount < 500) {
        connections[connectionCount++] = conn;

        // Create thread for sending heartbeat every 5 seconds.
        int id = connectionCount - 1;
        pthread_t thread;
        pthread_create(&thread, NULL, sendHeartbeat, &id);
    } else {
        printf("Maximum connections reached.\n");
        free(conn);
    }
    pthread_mutex_unlock(&countMutex);
}
