    srand((unsigned) time(NULL));
    int min = *(int*)arg;
    int max = *((int*)arg + 1);

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    for (int i = 0; i < num_records; i++) {
        pthread_mutex_lock(&mutex);

        while (keys[i]) { // Check if key already exists
            keys[i] = rand() % (max - min + 1) + min; // Generate new key
        }

        records[i].offset = 0;
        records[i].key = keys[i];
        records[i].value = rand() % (max_value - min_value + 1) + min_value;

        pthread_mutex_unlock(&mutex);
    }

    return NULL;
}

void initializeRecords(int num_records, int min_value, int max_value) {
