["```c
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <errno.h>
#include <assert.h>

typedef struct {
    int value;
} Record;

struct Context {
    pthread_mutex_t mutex;
    long *offsets;
    int *keys;
    Record *records;
    size_t numRecords;
};

int createArrays(size_t numRecords, struct Context **contextPtr) {
    if (numRecords <= 0 || contextPtr == NULL) return EINVAL;

    struct Context *context = calloc(1, sizeof(struct Context));
    if (context == NULL) return errno;

    int ret = 0;
    pthread_mutex_init(&context->mutex, NULL);

    context->offsets = malloc(numRecords * sizeof(*context->offsets));
    if (context->offsets == NULL) ret = errno;

    context->keys = malloc(numRecords * sizeof(*context->keys));
    if (ret == 0 && context->keys == NULL) ret = errno;

    context->records = calloc(numRecords, sizeof(*context->records));
    if (ret == 0 && context->records == NULL) ret = errno;

    if (ret != 0) {  // free allocated memory in case of error
        pthread_mutex_destroy(&context->mutex);
        free(context->offsets);
        free(context->keys);
        free(context->records);
        free(context);
    } else {  // save the number of records
        context->numRecords = numRecords;
        *contextPtr = context;
    }

    return ret;
}
```
To run it in a multi-threaded environment, you could create multiple threads that each call `createArrays`:

```c
#define NUM_THREADS 10

void *worker(void *arg) {
    struct Context *context = NULL;
    int ret = createArrays((size_t) arg, &context);

    if (ret == 0) {
        // access and use the created arrays

        pthread_mutex_destroy(&context->mutex);
        free(context->offsets);
        free(context->keys);
        free(context->records);
        free(context);
    } else {
        // handle error here, e.g., by printing to stderr
    }

    return NULL;  // always return from thread function
}

int main() {
    pthread_t threads[NUM_THREADS];
    size_t numRecords = 1024;

    for (size_t i = 0; i < NUM_THREADS; ++i) {
        int ret = pthread_create(&threads[i], NULL, worker, (void *)numRecords);

        if (ret != 0) exit(EXIT_FAILURE);  // thread creation failed
    }

    for (size_t i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
```
Note: The example above does not include any logging functionality. It also doesn't provide any protection for concurrent access from multiple threads, which would need to be added if this function is used in a multi-threaded environment and the calling code ensures that each thread uses its own Context instance.
