#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <sys/stat.h>

typedef struct {
    int ue_id;
    char *measurement_report;
    int reporting_interval;
} UEContext;

UEContext* createUEContext(int id, const char* report) {
    UEContext* context = malloc(sizeof(UEContext));
    if (context == NULL) goto error1;

    context->ue_id = id;
    context->measurement_report = strdup(report);  // assuming report is null-terminated string
    if (context->measurement_report == NULL) goto error2;

    context->reporting_interval = 10 + rand() % 90;  // random interval between 10 and 100
    return context;

error2:
    free(context);
error1:
    return NULL;
}

int setEnvAndDir(const char* dir_name) {
    if (getenv("EXAMPLE") != NULL) return 0;  // don't overwrite existing value

    if (mkdir(dir_name, 0755) == -1 && errno != EEXIST) goto error;

    char* new_path = malloc(strlen(getenv("PWD")) + strlen(dir_name) + 2);  // PWD is the current directory
    if (new_path == NULL) goto error;

    sprintf(new_path, "%s/%s", getenv("PWD"), dir_name);
    setenv("EXAMPLE", new_path, 1);
    free(new_path);
    return 0;

error:
    perror("Failed to create directory or set environment variable");
    return -1;
}
```
This code creates a UEContext structure with an ID and a randomly generated reporting interval. It also handles setting the EXAMPLE environment variable to the current working directory plus the provided name, creating the specified directory if necessary. If any part of this process fails, the function will print an error message and return -1.
