['```cpp
#include <chrono>
#include <iostream>
#include <mutex>
#include <random>
#include <thread>
#include <unordered_set>
#include <vector>

std::mt19937 gen(std::chrono::system_clock::now().time_since_epoch().count());
std::uniform_int_distribution<> dis(0, 1);
std::uniform_int_distribution<> keyDis(0, INT_MAX);
std::uniform_int_distribution<> valDis(-500000, 500000);
std::mutex mtx;

struct record {
    int value;
};

class GraphDatabase {
public:
    std::vector<long> offsetValues;
    std::vector<int> keys;
    std::vector<record*> records;
    size_t memoryUsed = 0;
    std::unordered_set<int> keySet;

    void initializeRecords(const int numOfRecords) {
        if (numOfRecords < 100 || numOfRecords > 10000) {
            throw std::out_of_range("Number of records must be between 100 and 10000");
        }

        offsetValues.reserve(numOfRecords);
        keys.reserve(numOfRecords);
        records.reserve(numOfRecords);

        for (int i = 0; i < numOfRecords; ++i) {
            std::lock_guard<std::mutex> lock(mtx);

            int key = -1;
            while (keySet.count(key)) {
                key = keyDis(gen);
            }
            keys.push_back(key);
            keySet.insert(key);

            record* rec = new record{valDis(gen)};
            records.push_back(rec);
            memoryUsed += sizeof(*rec);
        }
    }

    ~GraphDatabase() {
        for (record* r : records) {
            delete r;
        }
    }
};

void attackWithCooldown() {
    std::this_thread::sleep_for(std::chrono::seconds(9));
    int selectedAttack = dis(gen);
    std::cout << "Selected Attack: " << selectedAttack << "\n";
}

int main() {
    GraphDatabase gdb;

    try {
        const int numOfRecords = 1000;
        gdb.initializeRecords(numOfRecords);

        std::cout << "Memory Used: " << gdb.memoryUsed << "\n";
        attackWithCooldown();
    } catch (const std::exception& e) {
        std::cerr << "Exception: " << e.what() << "\n";
        return 1;
    }

    return 0;
}
```
