const fs = require('fs');
const path = require('path');
const childProcess = require('child_process');
let blueslip = require('blueslip'); // Mocking library

function runTestsInParallel(modulesPath, testsCallback) {
    const modules = fs.readdirSync(modulesPath).filter(file => file.endsWith('.js'));
    let processes = [];

    for (let module of modules) {
        const modulePath = path.join(modulesPath, module);
        console.log(`Testing module ${module}`);

        // Fork a child process to run tests in parallel
        const testProcess = childProcess.fork(modulePath, [], {execPath: 'node'});
        processes.push(testProcess);

        testProcess.on('message', ({event, data}) => {
            if (event === 'start-tests') {
                testsCallback(); // Execute the callback for starting tests
            } else if (event === 'end-tests') {
                console.log(`Finished testing module ${module}`);
                blueslip.reset(); // Reset mocking library after each test
                testProcess.kill(); // Kill child process when done with it
            }
        });
    }

    return Promise.allSettled(processes);
}
