import java.util.*;
class Main {
  public static void main(String[] args) {
    int[] arr = {1,2,3,4}; // Sample input array
    System.out.println("Disjoint Pairs: " + countPairs(arr));
  }

  private static int countPairs(int[] nums) {
      Arrays.sort(nums); // Sort the array

      int count = 0, i = 0;
      while (i < nums.length) {
          int j = i + 1;

          while (j < nums.length && nums[j] == nums[i])
              j++;

          count += (j - i - 1);
          i = j;
      }

      return count;
  }
}
