        return NULL;  // Return error code here.
    }

    void *addr;
    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    addr = &(ipv4->sin_addr);
    inet_ntop(res->ai_family, addr, ipstr, sizeof ipstr);

    freeaddrinfo(res);

    return ipstr;
}

