    UEContext* ctx = malloc(sizeof(*ctx));
    if (!ctx) return NULL;  // Memory allocation failed.

    ctx->id = id;
    ctx->report = report;
    ctx->config = config;
    ctx->refCount = 0;

    return ctx;
}

// Function to initialize a UE List structure with a specified initial capacity.
UEList* initUEList(size_t initialCapacity) {
    UEList* list = malloc(sizeof(*list));
    if (!list) return NULL;  // Memory allocation failed.

    list->contexts = calloc(initialCapacity, sizeof(*list->contexts));
    if (!list->contexts) {
        free(list);
        return NULL;  // Memory allocation failed.
    }

    list->capacity = initialCapacity;
    list->count = 0;

    return list;
}

// Function to add a UE Context to the UE List, resizing if necessary.
int addUEContext(UEList* list, int id, void* report, void* config) {
    // Check if we need to resize the list.
    if (list->count == list->capacity) {
        size_t newCapacity = list->capacity ? list->capacity * 2 : 1;
        UEContext** newContexts = realloc(list->contexts, newCapacity * sizeof(*newContexts));
        if (!newContexts) return -ENOMEM;  // Memory allocation failed.

        list->contexts = newContexts;
        list->capacity = newCapacity;
    }

    UEContext* ctx = initUEContext(id, report, config);
    if (!ctx) return -ENOMEM;  // Memory allocation failed.

    list->contexts[list->count++] = ctx;

    return 0;  // Success.
}
