#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <pthread.h>

// Define the structure for record
typedef struct {
    int value;
    char str[20];
} Record;

// Define the metadata structure
typedef struct {
    size_t offsetSize;
    size_t keySize;
} Metadata;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* allocateMemory(size_t size) {
    void* mem = malloc(size);

    // Check if memory allocation was successful
    if (mem == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    // Zero out the allocated memory for safety reasons. 
    memset(mem, 0, size);

    return mem;
}

void* reallocateMemory(void* ptr, size_t oldSize, size_t newSize) {
    assert(ptr != NULL);

    // Try to reallocate memory
    void* newPtr = realloc(ptr, newSize);

    if (newPtr == NULL) {
        fprintf(stderr, "Memory reallocation failed.\n");

        // Free the original pointer if reallocation fails. 
        free(ptr);
        return NULL;
    }

    // Check if we need to zero out additional memory
    if (newSize > oldSize) {
        memset((char*)newPtr + oldSize, 0, newSize - oldSize);
    }

    return newPtr;
}

void* allocateArrays(size_t offsetSize, size_t keySize, Metadata** metadataOut) {
    pthread_mutex_lock(&lock);

    // Allocate memory for the offset array
    long* offsetArray = allocateMemory(offsetSize * sizeof(long));
    if (offsetArray == NULL) return NULL;

    // Allocate memory for the key array
    int* keyArray = allocateMemory(keySize * sizeof(int));
    if (keyArray == NULL) {
        free(offsetArray);
        return NULL;
    }

    // Allocate memory for record structures
    Record* records = allocateMemory(keySize * sizeof(Record));
    if (records == NULL) {
        free(offsetArray);
        free(keyArray);
        return NULL;
    }

    // Populate the char arrays with random strings
    for (size_t i = 0; i < keySize; ++i) {
        for (size_t j = 0; j < 19; ++j) {
            records[i].str[j] = 'a' + rand() % 26;
        }
        records[i].str[19] = '\0';
    }

    // Allocate memory for the metadata structures
    Metadata* metadata = allocateMemory(sizeof(Metadata));
    if (metadata == NULL) {
        free(offsetArray);
        free(keyArray);
        free(records);
        return NULL;
    }

    // Set values in the metadata structures
    metadata->offsetSize = offsetSize;
    metadata->keySize = keySize;

    *metadataOut = metadata;

    pthread_mutex_unlock(&lock);

    return records;
}
```

This function will create the necessary arrays and structures as specified in the problem statement. It locks a mutex before allocating memory to ensure thread safety, and it includes error checking for all memory allocation operations. The string size is hardcoded to 20 for simplicity, but you could easily make this a parameter if necessary.
