void allocate_and_init(size_t num_elements, size_t max_total_size, int use_random, 
                       int special_flag, int specific_value) {
    srand((unsigned) time(NULL)); // seed the random number generator

    if (num_elements * sizeof(long) + num_elements * sizeof(int) + 
