["Here is an example of how you might implement this task in C. This solution uses a hash table data structure that has constant time complexity for insertions, deletions, and lookups which makes it ideal for high concurrency scenarios:

```C
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct NFAPI_CRC_INDICATION_PDU {
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct table_entry {
    int key;
    NFAPI_CRC_INDICATION_PDU_T *pdu;
};

typedef struct {
    pthread_mutex_t lock;
    size_t capacity, count;
    struct table_entry **entries;
} hashmap_t;

static int hash(hashmap_t *hm, int key)
{
    return key % hm->capacity;
}

int hm_create(hashmap_t *hm, size_t capacity) 
{
    if (pthread_mutex_init(&hm->lock, NULL)) {
        return -1;
    }

    hm->capacity = capacity;
    hm->count = 0;
    hm->entries = calloc(hm->capacity, sizeof(struct table_entry *));
    if (!hm->entries) {
        return -1;
    }

    return 0;
}

void hm_destroy(hashmap_t *hm)
{
    for (size_t i = 0; i < hm->capacity; ++i) {
        struct table_entry *entry = hm->entries[i];

        if (entry != NULL && entry->pdu != NULL) {
            free(entry->pdu);
            free(entry);
        }
    }

    free(hm->entries);
}

int hm_put(hashmap_t *hm, int key, NFAPI_CRC_INDICATION_PDU_T *value) 
{
    pthread_mutex_lock(&hm->lock);

    if (hm->count == hm->capacity) {
        pthread_mutex_unlock(&hm->lock);
        return -1;
    }

    struct table_entry *new_entry = malloc(sizeof(*new_entry));
    if (new_entry == NULL) {
        pthread_mutex_unlock(&hm->lock);
        return -1;
    }

    new_entry->key = key;
    new_entry->pdu = malloc(sizeof(*value));
    if (new_entry->pdu == NULL) {
        free(new_entry);
        pthread_mutex_unlock(&hm->lock);
        return -1;
    }

    memcpy(new_entry->pdu, value, sizeof(*value));
    int index = hash(hm, key);

    while (hm->entries[index] != NULL && hm->entries[index]->key != -1) {
        index = (index + 1) % hm->capacity;
    }

    hm->entries[index] = new_entry;
    hm->count++;

    pthread_mutex_unlock(&hm->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T *hm_get(hashmap_t *hm, int key) 
{
    pthread_mutex_lock(&hm->lock);

    int index = hash(hm, key);

    while (hm->entries[index] != NULL) {
        if (hm->entries[index]->key == key) {
            NFAPI_CRC_INDICATION_PDU_T *result = malloc(sizeof(*result));
            memcpy(result, hm->entries[index]->pdu, sizeof(*result));

            pthread_mutex_unlock(&hm->lock);
            return result;
        }

        index = (index + 1) % hm->capacity;
    }

    pthread_mutex_unlock(&hm->lock);
    return NULL;
}

int hm_remove(hashmap_t *hm, int key) 
{
    pthread_mutex_lock(&hm->lock);

    int index = hash(hm, key);

    while (hm->entries[index] != NULL) {
        if (hm->entries[index]->key == key) {
            free(hm->entries[index]->pdu);
            free(hm->entries[index]);

            hm->entries[index] = NULL;
            hm->count--;
            pthread_mutex_unlock(&hm->lock);
            return 0;
        }

        index = (index + 1) % hm->capacity;
    }

    pthread_mutex_unlock(&hm->lock);
    return -1;
}
```

You can then use the hashmap functions as follows:

```C
NFAPI_CRC_INDICATION_PDU_T pdu = {.RNTI = 1, .CRCFLAG = 2};
hashmap_t hm;
hm_create(&hm, 10);
hm_put(&hm, 1, &pdu);
NFAPI_CRC_INDICATION_PDU_T *result = hm_get(&hm, 1);
// Do something with the result
free(result);
hm_remove(&hm, 1);
hm_destroy(&hm);
```
This solution meets all requirements mentioned in the problem. It is thread-safe and handles memory efficiently by using a hash table to store data. The memory management for each PDU object is done individually, so there will be no fragmentation issues as long as you free all memory when it's no longer needed. However, please note that this solution only provides very basic error handling — you might want to improve upon it depending on your specific requirements and how much you can rely on the inputs.
"]

