typedef struct RX_UE_INFORMATION_TAG {
    unsigned int RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct CRC_INDICATION_REL8_TAG {
    unsigned int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rxInfoTag;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void addData(unsigned int rnti, unsigned int crcFlag) {
    pthread_mutex_lock(&mutex);

    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        // Handle memory allocation error
        exit(-1);
    }
    newNode->data.rxInfoTag.RNTI = rnti;
    newNode->data.crcIndicationRel8Tag.CRCFLAG = crcFlag;

    if (head == NULL) {
        head = newNode;
    } else {
        Node* current = head;
        while(current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    pthread_mutex_unlock(&mutex);
}
