response:
['Here is a sample C program that satisfies all the requirements. It uses POSIX threads for thread safety and `mmap` to track memory usage. Note that this example does not actually use the offsets or keys, but it could be easily extended to do so if needed.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/mman.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    int value;
} Record;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static size_t total_memory = 0;

Record* allocateRecords(int num_records, long offset_range, int key_range) {
    if (num_records < 1 || num_records > 1000) {
        fprintf(stderr, "Invalid number of records.\n");
        return NULL;
    }

    srand(time(NULL));  // Seed the random number generator

    int* keys = calloc(key_range, sizeof(int));  // Use a bit array for faster lookup of duplicate keys
    if (keys == NULL) {
        fprintf(stderr, "Failed to allocate memory.\n");
        return NULL;
    }

    Record* records = malloc(num_records * sizeof(Record));
    if (records == NULL) {
        free(keys);
        fprintf(stderr, "Failed to allocate memory.\n");
        return NULL;
    }

    for (int i = 0; i < num_records; ++i) {
        pthread_mutex_lock(&lock);  // Lock for thread safety

        int key;
        do {
            key = rand() % key_range;
        } while (keys[key] != 0);

        keys[key] = 1;
        records[i].offset = rand() % offset_range;
        records[i].key = key;
        records[i].value = rand() % 100;

        pthread_mutex_unlock(&lock);  // Unlock after the critical section
    }

    free(keys);

    size_t memory_size = num_records * sizeof(Record);
    total_memory += memory_size;
    mmap((void*)&total_memory, memory_size, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0); // Track total allocated memory

    return records;
}
```
You can use this function in a thread-safe way as follows:

```c
void* threadFunction(void* arg) {
    int num_records = *((int*)arg);
    Record* records = allocateRecords(num_records, 100, 500);
    if (records != NULL) {
        // Use the records...
        free(records);
    }
    return NULL;
}
```
Please note that due to the randomness of key generation, and the need for thread safety with respect to the `keys` bit array, this implementation is not completely deterministic. Also, it doesn't cover all possible error conditions, and could be extended with additional checks or handling based on specific use cases.
']

