typedef int (*validation_callback)(int);

void initialize(size_t num_records, int range, validation_callback callback) {
    assert(num_records > 0 && "Number of records must be greater than zero");
    assert(range > 1 && "Range must be greater than one for unique random values");
    assert(callback != NULL && "Callback function is required to validate record's int value");

    srand((unsigned int)time(NULL));  // Seed the random number generator.

    long *offset_array = malloc(num_records * sizeof(long));
    assert(offset_array != NULL && "Failed to allocate memory for offset array");

    int *key_array = malloc(num_records * sizeof(int));
    assert(key_array != NULL && "Failed to allocate memory for key array");

    record *record_array = malloc(num_records * sizeof(record));
    assert(record_array != NULL && "Failed to allocate memory for record array");

    // Initialize offset and key arrays.
    for (size_t i = 0; i < num_records; ++i) {
        offset_array[i] = (long)i;  // Unique long value.
        key_array[i] = (int)i;  // Unique integer value.
    }

    // Initialize record array with random int values within the specified range.
    for (size_t i = 0; i < num_records; ++i) {
        int rand_val = rand() % range + 1;  // Random value between 1 and range.

        if (!callback(rand_val)) {
            free(offset_array);
            free(key_array);
            free(record_array);

            assert("Failed to validate record's int value");
        }

        record_array[i].value = rand_val;
    }

    // Free allocated memory when no longer needed.
    free(offset_array);
    free(key_array);
    free(record_array);
}
