    ReportingConfiguration* reportingConfig;
} UEContext;

void adjustReportingInterval(UEContext *ue, int newInterval) {
    if (newInterval < 0) return;
    if (NULL != ue->reportingConfig && NULL != ue->measurementReport) {
        ue->reportingConfig->reportingInterval = newInterval;
    }
}

UEContext* createAndInitializeUEContext(unsigned long id, int reportingInterval, MeasurementReport *mr) {
    UEContext *ctx = (UEContext*) malloc(sizeof(UEContext));
    if (NULL == ctx) return NULL;  // error handling for memory allocation failure
    ctx->ueId = id;

    ReportingConfiguration* rc = (ReportingConfiguration*) malloc(sizeof(ReportingConfiguration));
    if (NULL == rc) {  // free already allocated resources in case of allocation failure
        free(ctx);
        return NULL;
    }
    ctx->reportingConfig = rc;
    adjustReportingInterval(ctx, reportingInterval);

    MeasurementReport* mrCopy = (MeasurementReport*)malloc(sizeof(MeasurementReport));
    if (NULL == mrCopy) {  // free already allocated resources in case of allocation failure
        free(rc);
        free(ctx);
        return NULL;
    }
    memcpy(mrCopy, mr, sizeof(MeasurementReport));  // deep copy measurement report
    ctx->measurementReport = mrCopy;

    return ctx;
}

void saveUEContextListToFile(char *filename, UEContext **list, int count) {
    FILE *file = fopen(filename, "wb");  // open file in binary write mode
    if (NULL == file) return;  // error handling for file opening failure

    for (int i = 0; i < count; ++i) {
        UEContext* ctx = list[i];
        fwrite(ctx, sizeof(UEContext), 1, file);  // write UE Context to file
    }

    fclose(file);  // close the file after writing is complete
}

UEContext** loadUEContextListFromFile(char *filename, int count) {
    FILE *file = fopen(filename, "rb");  // open file in binary read mode
    if (NULL == file) return NULL;  // error handling for file opening failure

    UEContext **list = malloc(count * sizeof(UEContext*));  // allocate memory for list of UE Contexts
    if (NULL == list) {
        fclose(file);
        return NULL;
    }

    for (int i = 0; i < count; ++i) {
        UEContext* ctx = malloc(sizeof(UEContext));  // allocate memory for each UE Context
        if (NULL == ctx) break;

        fread(ctx, sizeof(UEContext), 1, file);  // read UE Context from file
        list[i] = ctx;  // add to the list of UE Contexts
    }

    fclose(file);  // close the file after reading is complete

    return list;
}
```
