typedef struct User {
    char* username;
    time_t lastUpdateTime;  // for rate limiting
    pthread_mutex_t mutex;
} User;

User* createUser(const char* user) {
    User* newUser = malloc(sizeof(User));
    if (newUser == NULL) {
        return NULL;
    }

    newUser->username = strdup(user);
    if (newUser->username == NULL) {
        free(newUser);
        return NULL;
    }

    // initialize last update time to 0
    newUser->lastUpdateTime = 0;  
    pthread_mutex_init(&(newUser->mutex), NULL);
    return newUser;
}

void destroyUser(User* user) {
    if (user != NULL) {
        free(user->username);
        pthread_mutex_destroy(&(user->mutex));
        free(user);
    }
}

void updatePasswordSafe(const char* username, const char* password, const char* token) {
    static User* users = NULL;
    static size_t userCount = 0;

    pthread_mutex_t globalMutex = PTHREAD_MUTEX_INITIALIZER;  // protects 'users' and 'userCount'

    /* Lock the global mutex to avoid race conditions on accesses/updates to users array */
    pthread_mutex_lock(&globalMutex);

    User* user = NULL;
    for (size_t i = 0; i < userCount; ++i) {  // look up existing user
        if (strcmp(users[i].username, username) == 0) {
            user = &users[i];
            break;
        }
    }

    /* Unlock global mutex */
    pthread_mutex_unlock(&globalMutex);  

    if (user == NULL) {  // create a new User if it doesn't exist
        user = createUser(username);
        if (user == NULL) {
            return;
        }

        /* Lock the global mutex to update 'users' and 'userCount' */
        pthread_mutex_lock(&globalMutex);  

        users = realloc(users, (userCount + 1) * sizeof(User));  // allocate space for new User struct
        if (users == NULL) {
            destroyUser(user);
            return;
        }

        users[userCount++] = *user;   // add the new user to 'users' array

        /* Unlock global mutex */
        pthread_mutex_unlock(&globalMutex); 
    }

    /* Lock the user-specific mutex for thread safety */
    pthread_mutex_lock(&(user->mutex));  

    if (difftime(time(NULL), user->lastUpdateTime) < 300) {  // 5 minutes = 60 seconds * 5
        /* Unlock the mutex and return without updating password */
        pthread_mutex_unlock(&(user->mutex));  

        printf("Error: Password update rate limit exceeded for user %s.\n", username);
        return;
    }

    /* Validate the token with an external authentication service before updating the password */
    authenticateUser(username, token);

    if (validatePasswordStrength(password) != 0) {  // validate password strength

        pthread_mutex_unlock(&(user->mutex));  // Unlock mutex even if there's an error in updating the password to allow other threads to proceed with their operations

        printf("Error: Password does not meet the required strength.\n");
        return;
    }

    updatePasswordInDB(username, password);  // update password in database

    /* Update lastUpdateTime for rate limiting */
    user->lastUpdateTime = time(NULL);

    printf("Success: Password updated successfully.\n");

    pthread_mutex_unlock(&(user->mutex));  // Unlock the mutex at the end
}
