void *allocAndInit(size_t size, int rangeStart, int rangeEnd) {
    void *mem = malloc(size);
    if (mem == NULL) {
        fprintf(stderr, "Out of memory\n");
        exit(1);
    }

    for (int i = 0; i < size / sizeof(int); i++) {
        ((int *) mem)[i] = rand() % (rangeEnd - rangeStart + 1) + rangeStart;
    }

    return mem;
}

char *genRandomString() {
    char *str = malloc(MAX_STR_LEN+1);

    for (int i = 0; i < MAX_STR_LEN; i++) {
        str[i] = 'a' + rand() % 26; // Generate random alphanumeric string of length MAX_STR_LEN
    }

    str[MAX_STR_LEN] = '\0';
    return str;
}

void *recordInit(size_t size, int rangeStart, int rangeEnd) {
    Record *records = malloc(size);
    if (records == NULL) {
