    }

    return records;
}

void initArrays(size_t size, int keyRangeStart, int keyRangeEnd, int recordRangeStart, int recordRangeEnd, unsigned seed, int limit) {
    assert(limit > 0 && "Max memory limit must be positive");

    srand(seed);
    pthread_mutex_lock(&mutex);
    if (totalAllocated + size > maxMemLimit) {
        fprintf(stderr, "Memory limit exceeded\n");
        exit(1);
    }

    totalAllocated += size;
    void *offsets = allocAndInit(sizeof(long) * 5, 0, INT_MAX); // Allocate and initialize offset values
    void *keys = allocAndInit(sizeof(int) * size, keyRangeStart, keyRangeEnd); // Allocate and initialize keys with random integers in specified range
    void *records = recordInit(sizeof(Record) * size, recordRangeStart, recordRangeEnd); // Allocate and initialize records structures with random values

    if (loggingLevel > 0) {
        printf("Arrays initialized successfully\n");
    }

    free(offsets);
    free(keys);
    for (int i = 0; i < size / sizeof(Record); i++) {
        free(((Record *) records)[i].str); // Free dynamically allocated strings
    }
    free(records);

    pthread_mutex_unlock(&mutex);
}
