#include <pthread.h>

typedef struct {
    char timestamp[30];  // Assuming max length of the timestamp is 30. Adjust as needed
    int level;          // Log levels (e.g., DEBUG, INFO, ERROR)
    char message[1024]; // Message string (adjust to your needs)
} log_entry;

// Global variables for tracking memory allocation and threadsafety 
long totalMemoryAllocated = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* generateLogEntry(void *args) {
    log_entry* entry = malloc(sizeof(log_entry));

    if (!entry) {
        fprintf(stderr, "Memory allocation failed for a log entry.\n");
        return NULL;
    }

    // Assuming args is an array with the first two elements as timestamp and message. 
    char* timestamp = (char*)args[0];
    strcpy(entry->timestamp, timestamp);

    int level = *((int*)args[1]);
    entry->level = level;

    char* message = (char*)args[2];
    strcpy(entry->message, message);

    pthread_mutex_lock(&lock);
    totalMemoryAllocated += sizeof(log_entry);  // Update the memory counter atomically
    pthread_mutex_unlock(&lock);

    return entry;
}

void cleanupLogEntry(log_entry* entry) {
    if (entry == NULL) {
        return;
    }

    free(entry);  // Freeing the log_entry structure

    pthread_mutex_lock(&lock);
    totalMemoryAllocated -= sizeof(log_entry);  // Update the memory counter atomically
    pthread_mutex_unlock(&lock);
