typedef struct {
    int value;
    char* str;
} Record;

// Global variables and mutex for thread safety
int *keys, num_records, min_val, max_val, offsets_size, keys_size, records_size;
Record *records;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* update_state(void *arg) {
    while (1) {
        pthread_mutex_lock(&lock);  // Ensure thread safety before updating state

        // Fetch new data from API call
        int new_data = fetch_data();  

        // Update global variables here based on new data
        for(int i=0; i<num_records; i++) {
            records[i].value = new_data + offsets[i];  // Assuming 'offsets' is an array of long int
        }

        pthread_mutex_unlock(&lock);  // Release the lock

        sleep(5);  // Sleep for 5 seconds to avoid blocking other operations
    }
    return NULL;
}

void generate_arrays() {
    parse_config();  // Assume this function parses config file and assigns values to num_records, min_val, max_val etc.

    keys = malloc(keys_size * sizeof(*keys));
    records = calloc(num_records, sizeof(*records));  // Initialize memory for records with zeroes

    if (keys == NULL || records == NULL) {
        log_error("Memory allocation failed");
        exit(1);  // Exit the program with an error code
    }

    srand((unsigned int) time(NULL));  // Seed random number generator

    for (int i = 0; i < num_records; i++) {
