```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
    char* str;
} record;

int initArraysAndLoadBundle(long* offsetValues, int* keys, record** records, int size1, int size2, 
                            const char* configFilePath, const char* resourceFilePath) {
    FILE *configFile, *resourceFile;
    int minRange = 0, maxRange = 0;

    srand(time(NULL)); // Seed the random number generator

    if ((configFile = fopen(configFilePath, "r")) == NULL) {
        perror("Error opening config file");
        return -1;
    }

    /* Read from configuration file */
    fscanf(configFile, "%d %d", &size1, &size2); // Assuming the first two values are sizes
    fscanf(configFile, "%d %d", &minRange, &maxRange); // Range for random numbers

    /* Dynamically allocate arrays */
    offsetValues = (long*) malloc(size1 * sizeof(long));
    keys = (int*) malloc(size2 * sizeof(int));

    if ((resourceFile = fopen(resourceFilePath, "r")) == NULL) {
        perror("Error opening resource file");
        return -1;
    }

    /* Read from resource file */
    int bundleSize = 0;
    while (!feof(resourceFile)) { // Count lines in the file
        char identifier[256];
        fscanf(resourceFile, "%s", identifier);
        bundleSize++;
    }

    /* Dynamically allocate bundle */
    *records = (record*) malloc(bundleSize * sizeof(record));

    rewind(resourceFile); // Reset file pointer to the beginning
    char identifier[256];
    for (int i = 0; i < bundleSize; i++) { 
        fscanf(resourceFile, "%s", identifier);

        /* Allocate memory for string and initialize it */
        (*records)[i].str = malloc((strlen(identifier) + 1) * sizeof(char));
        strcpy((*records)[i].str, identifier);

        /* Initialize the int value with a random number in the specified range */
        (*records)[i].value = rand() % (maxRange - minRange + 1) + minRange; 
    }

    fclose(configFile);
    fclose(resourceFile);

    return bundleSize; // Return the number of items in the bundle
}
```

**Note: This code does not handle concurrent calls to `initArraysAndLoadBundle()`. If this function is called concurrently, it could potentially cause issues with memory allocation and file access. To prevent this, you could use a mutex or other thread synchronization mechanism to ensure only one thread can call the function at a time.**
']

