#include <stdlib.h>

static std::mutex mtx;  // mutex for thread-safety

void initializeArrays(int num_records, long* offset_array, int** keys, record*** records) {
    static constexpr int MAX_RECORDS = 1000;

    if (num_records <= 0 || num_records > MAX_RECORDS)
        throw std::invalid_argument("Number of records must be between 1 and " + std::to_string(MAX_RECORDS));

    *offset_array = static_cast<long*>(malloc(num_records * sizeof(**keys)));
    if (*offset_array == nullptr) throw std::bad_alloc();

    std::lock_guard<std::mutex> lock(mtx);  // for thread-safety
    static long offset = 0;
    for (int i = 0; i < num_records; ++i, ++offset) {
        (*offset_array)[i] = offset;
    }

    *keys = static_cast<int*>(malloc(num_records * sizeof(**keys)));
    if (*keys == nullptr) throw std::bad_alloc();

    std::unordered_set<int> key_set;  // to ensure unique keys
    while (key_set.size() < static_cast<std::size_t>(num_records)) {
        MyNamespace::RandomGenerator::gen.seed(MyNamespace::RandomGenerator::gen());
        int key = MyNamespace::RandomGenerator::gen();  // generating unique keys
        key_set.insert(key);
    }

    std::copy(key_set.begin(), key_set.end(), *keys);

    *records = static_cast<record**>(malloc(num_records * sizeof(**records)));
    if (*records == nullptr) throw std::bad_alloc();

    for (int i = 0; i < num_records; ++i) {
        (*records)[i] = static_cast<record*>(malloc(sizeof(**records)));
        if ((*records)[i] == nullptr) throw std::bad_alloc();

        (*records)[i]->value = (*keys)[i];  // initializing records with keys
    }
}

void sortRecords(record** records, int num_records) {
    if (num_records == 0 || records == nullptr) return;  // handling edge cases

    std::sort(records, records + num_records, [](const record* a, const record* b){
        return a->value < b->value;  // sorting based on key values in ascending order
    });
}
}
