["This task involves writing a complex function in C. Here's an example of how you could implement this function, including thread safety and error handling mechanisms, among other things:

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record* records;
    size_t totalMemory;
    pthread_mutex_t mutex;
} RecordData;

int validateAndAllocate(RecordData *data, int numRecords) {
    if (numRecords <= 0) return -1;  // Invalid input

    data->offsets = malloc(numRecords * sizeof(long));
    data->keys = malloc(numRecords * sizeof(int));
    data->records = malloc(numRecords * sizeof(record));

    if (data->offsets == NULL || data->keys == NULL || data->records == NULL) {
        free(data->offsets);
        free(data->keys);
        free(data->records);
        return -1;  // Memory allocation failed
    }

    pthread_mutex_init(&data->mutex, NULL);  // Initialize mutex for thread safety
    data->totalMemory = numRecords * (sizeof(long) + sizeof(int) + sizeof(record));  // Calculate total memory allocated
    return 0;  // Successful allocation
}

void deallocateData(RecordData *data) {
    free(data->offsets);
    free(data->keys);
    free(data->records);
    pthread_mutex_destroy(&data->mutex);  // Destroy mutex to free associated resources
}

int initializeRecords(RecordData *data, int numRecords) {
    if (pthread_mutex_lock(&data->mutex) != 0) return -1;  // Lock the mutex before accessing shared data

    srand((unsigned) time(NULL));  // Seed the random number generator

    for (int i = 0; i < numRecords; i++) {
        data->offsets[i] = rand();

        int key;
        do {
            key = rand();
        } while (contains(data->keys, key, i));  // Ensure unique keys

        data->keys[i] = key;
        data->records[i].value = rand();
    }

    if (pthread_mutex_unlock(&data->mutex) != 0) return -1;  // Unlock the mutex after accessing shared data
    return 0;  // Successful initialization
}
```

This code provides a foundation for your required function. However, there's still work to be done on error handling and duplicate key checking mechanism as per new functional requirements. Also note that this is a basic implementation and may require further enhancements based on specific use cases and performance requirements. This example doesn't include a full solution due to its complexity, but it should provide a good starting point for your task.
