    static void initMemoryManager(size_t nodeCount, size_t logSize) {
        // Ensure parameters are within acceptable ranges
        if (nodeCount < 1 || nodeCount > 1000 || logSize > INT32_MAX - currentIdentifier) {
            throw std::invalid_argument("Invalid parameter value");
