void SafeListInit(SafeList* sl) {
    pthread_mutex_init(&sl->lock, NULL);
    sl->count = 0;
}

int SafeListAppend(SafeList* sl, NFAPI_CRC_INDICATION_PDU* item) {
    pthread_mutex_lock(&sl->lock);
    sl->list = realloc(sl->list, sizeof(NFAPI_CRC_INDICATION_PDU*) * (sl->count + 1));
    if (!sl->list) return -1; // Allocation error
    sl->list[sl->count++] = item;
    pthread_mutex_unlock(&sl->lock);
    return 0;
}

void SafeListFree(SafeList* sl) {
    for (size_t i = 0; i < sl->count; ++i) free(sl->list[i]);
    free(sl->list);
    pthread_mutex_destroy(&sl->lock);
}

