int create_phy_info_list(size_t initial_capacity, PHY_INFO_LIST **list) {
    if (initial_capacity <= 0) {
        fprintf(stderr, "Invalid initial capacity\n");
        return -1;
    }

    *list = malloc(sizeof(PHY_INFO_LIST));
    if (*list == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
