    (*list)->capacity = initial_capacity;
    (*list)->size = 0;
    pthread_mutex_init(&(*list)->lock, NULL);

    (*list)->list = malloc(initial_capacity * sizeof(LTE_PHY_INFO_T));
    if ((*list)->list == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_destroy(&(*list)->lock);
        free(*list);
        *list = NULL;
        return -1;
