    for (size_t i = 0; i < initial_capacity; ++i) {
        (*list)->list[i].ue_id = i + 1;
        (*list)->list[i].tb_size = rand() % 1024; // Random TB size between 0 and 1023
        (*list)->list[i].cqi = rand() % 3;
    }

    return 0;
}

int resize_phy_info_list(PHY_INFO_LIST *list, size_t new_capacity) {
