#include <unistd.h>

typedef struct record {
    int value;
} Record;

u_char* performDNSResolution(const char *hostname) {
    static u_char ip[4];
    struct __res_state state;
    int result = res_ninit(&state);

    if (result != 0) {
        printf("Failed to initialize resolver: %d\n", h_errno);
        return NULL;
    }

    unsigned char answer[NS_PTR];
    result = res_nquery(&state, hostname, C_INET, T_A, answer, sizeof(answer));

    if (result < 0) {
        printf("Failed to resolve host: %d\n", h_errno);
        return NULL;
    }

    inet_pton(AF_INET, (char*)answer, &ip);

    res_nclose(&state);
    return ip;
}

int main() {
