['Here is a basic implementation of the function that satisfies your requirements. This is a simplified version and does not cover all points such as thread safety or efficient duplicate checking but serves as an example:

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct node {
    int value;
    struct node *next;
} node_t;

// global variable to track total allocated memory
size_t allocated_mem = 0;

// mutex for thread safety 
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

node_t* createNode(int value) {
    node_t *newNode = malloc(sizeof(node_t));

    if (newNode == NULL) 
        return NULL;

    newNode->value = value;
    newNode->next = NULL;

    // update total allocated memory
    pthread_mutex_lock(&lock);
    allocated_mem += sizeof(node_t);
    pthread_mutex_unlock(&lock);

    return newNode;
}

void addNodeToList(int value, node_t **head) {
    if (*head == NULL || (*head)->value > value) {
        // insert at head of list or in the middle
        node_t *newNode = createNode(value);

        if (newNode != NULL) {
            newNode->next = *head;
            *head = newNode;
        }
    } else if ((*head)->value < value && (*head)->next == NULL) {
        // insert at end of list
        (*head)->next = createNode(value);
    } else if ((*head)->value != value && (*head)->next != NULL){
        addNodeToList(value, &(*head)->next);
    } 
}

void printLinkedList(node_t *head) {
    node_t *current = head;

    while (current != NULL) {
        printf("%d ", current->value);
        current = current->next;
    }

    printf("\n");
}
```
For the full implementation, you should use `pthread_mutex_lock(&lock)` before each modification of the linked list and `pthread_mutex_unlock(&lock)` after it. This would ensure that only one thread can modify the list at a time and avoid race conditions. 

