#define HEARTBEAT_INTERVAL 5
#define RESPONSE_TIMEOUT 2

typedef struct {
    int clientSocket;
    int serverSocket;
    pthread_t thread;
    time_t timeoutInterval;
} ConnectionInfo;

pthread_mutex_t connectionListLock = PTHREAD_MUTEX_INITIALIZER;
ConnectionInfo* connections[MAX_CONNECTIONS];
int numConnections = 0;
char* configFilePath = "/path/to/config.json";
struct json_object* configObject;

void sendHeartbeat(ConnectionInfo *connection) {
    // Implementation of sending heartbeats here
}

void checkTimeout(ConnectionInfo *connection) {
    if (difftime(time(NULL), connection->timeoutInterval) > RESPONSE_TIMEOUT) {
        // Connection marked as inactive
    }
}

void* handleHeartbeat(void *arg) {
    ConnectionInfo *connection = (ConnectionInfo *)arg;

    while (1) {
        sleep(HEARTBEAT_INTERVAL);
        sendHeartbeat(connection);
        checkTimeout(connection);
    }
}

int createConnection() {
    pthread_mutex_lock(&connectionListLock);

    if (numConnections >= MAX_CONNECTIONS) {
        printf("Maximum number of connections reached.\n");
        return -1;
    }

    ConnectionInfo *newConnection = malloc(sizeof(ConnectionInfo));
    if (!newConnection) {
        perror("Memory allocation failed.");
        return -1;
    }

    newConnection->clientSocket = socket(AF_INET, SOCK_STREAM, 0); // Creating client socket
    newConnection->serverSocket = socket(AF_INET, SOCK_STREAM, 0); // Creating server socket

    if (newConnection->clientSocket == -1 || newConnection->serverSocket == -1) {
        perror("Socket creation failed.");
        free(newConnection);
        return -1;
    }

    srand(time(NULL));
    newConnection->timeoutInterval = rand() % 5 + 1; // Random timeout interval
    if (pthread_create(&newConnection->thread, NULL, handleHeartbeat, newConnection) != 0) {
        perror("Thread creation failed.");
        close(newConnection->clientSocket);
        close(newConnection->serverSocket);
        free(newConnection);
        return -1;
    }

    connections[numConnections++] = newConnection;
    pthread_mutex_unlock(&connectionListLock);

    printf("Connection created.\n");
    return numConnections - 1; // Return connection ID
}

int removeConnection(int id) {
    if (id < 0 || id >= MAX_CONNECTIONS) {
        printf("Invalid connection ID.\n");
        return -1;
    }

    pthread_mutex_lock(&connectionListLock);

    ConnectionInfo *removedConnection = connections[id];
    close(removedConnection->clientSocket);
    close(removedConnection->serverSocket);

    numConnections--;
    connections[id] = connections[numConnections]; // Fill the gap in array
    free(removedConnection);

    pthread_mutex_unlock(&connectionListLock);

    printf("Connection removed.\n");
    return 0;
}

void loadConfig() {
    FILE *configFile = fopen(configFilePath, "r");
    if (!configFile) {
        perror("Failed to open configuration file.");
        exit(-1);
    }

    char buffer[512];
    fread(buffer, sizeof(char), sizeof(buffer), configFile);
    fclose(configFile);

    json_tokener_error jerr;
    configObject = json_tokener_parse_verbose(buffer, &jerr);
}
``` 
