void* allocate(size_t size) {
    void* ptr = NULL;
    pthread_mutex_lock(&lock);
    if (total_memory + size > MAXIMUM_MEMORY || concurrent_threads >= MAX_THREADS) {
        printf("Out of memory or thread limit exceeded\n");
        exit(1); // Or throw an error based on requirements.
    } else {
        ptr = malloc(size);
        total_memory += size;
        ++concurrent_threads;
    }
    pthread_mutex_unlock(&lock);
    return ptr;
}

void deallocate(void* ptr, size_t size) {
    free(ptr);
    pthread_mutex_lock(&lock);
    total_memory -= size;
    --concurrent_threads;
    pthread_mutex_unlock(&lock);
}

