["Here's an example of how you might implement such a function in C using locks for thread safety. Note that for simplicity and efficiency I am assuming that sensor data size will not be a problem here (not a lot of sensors). However, if it could become a problem, we would need to reallocate the entire array and copy old elements into new one which is very costly operation.

```C
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    long timestamp;
    double sensor_reading;
    int quality_flag;
} sensorData;

typedef struct {
    sensorData* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

void init_array(DynamicArray* arr) {
    arr->data = NULL;
    arr->capacity = 0;
    arr->size = 0;
    pthread_mutex_init(&arr->lock, NULL);
}

int resize_array(DynamicArray* arr, size_t newCapacity) {
    sensorData* newData = realloc(arr->data, newCapacity * sizeof(sensorData));
    if (newData == NULL && newCapacity != 0) {
        return -1;  // failed to allocate memory
    }
    arr->data = newData;
    arr->capacity = newCapacity;
    return 0;  // success
}

int add_element(DynamicArray* arr, sensorData elem) {
    pthread_mutex_lock(&arr->lock);

    if (arr->size >= arr->capacity && resize_array(arr, arr->capacity * 2 + 1) < 0) {
        pthread_mutex_unlock(&arr->lock);
        return -1;  // failed to allocate memory
    }

    arr->data[arr->size++] = elem;

    pthread_mutex_unlock(&arr->lock);
    return 0;  // success
}

int remove_element(DynamicArray* arr, size_t index) {
    pthread_mutex_lock(&arr->lock);

    if (index >= arr->size) {
        pthread_mutex_unlock(&arr->lock);
        return -1;  // invalid index access
    }

    for(size_t i = index; i < arr->size - 1; ++i) {
        arr->data[i] = arr->data[i + 1];
    }

    if (--arr->size * 4 <= arr->capacity && resize_array(arr, arr->capacity / 2) < 0) {
        pthread_mutex_unlock(&arr->lock);
        return -1; // failed to allocate memory
    }

    pthread_mutex_unlock(&arr->lock);
    return 0; // success
}
```
This is a basic implementation. For real-world applications, you'd likely want more sophisticated error handling and more efficient resize operations. Also, the way in which the array resizes can be adjusted to better suit your needs or constraints (for instance, by incrementing/decrementing by a larger value instead of always doubling).
"]

