    if (file == NULL) {
        printf("Failed to open the file\n"); 
        return -1; // or any error code
    }

    json_t* root = json_object();
    json_t* dataPointsArr = json_array();

    for (int i = 0; i < size; ++i) {
        json_t *dataPointObj = json_pack("{s:f, s:i, s:f}", "doubleVal", arr[i].dVal, "integerKey", arr[i].iKey, "floatVal", arr[i].fVal);
        json_array_append(dataPointsArr, dataPointObj);
    }

    json_object_set(root, "dataPoints", dataPointsArr);
    fputs(json_dumps(root, 0), file);
    fclose(file);
    json_decref(root);
    return 0; // or success code
}
