['Here is an example of how you might implement this function in C. This code uses the OpenSSL library for a cryptographically secure pseudo-random number generator (CSPRNG), and pthreads for thread safety. It also dynamically resizes arrays if necessary, handles memory allocation failures, and ensures all allocated memory is freed when the function completes execution:

```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include <openssl/rand.h>

typedef struct record {
    int value;
} record;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void init_records(int num_records) {
    pthread_mutex_lock(&lock); // Lock mutex before modifying data structures

    int *keys, oldKeySize = 0;
    long *offsets, oldOffsetSize = 0;
    record *records, oldRecordSize = 0;

    while (1) {
        if (oldKeySize < num_records) {
            keys = realloc(keys, num_records * sizeof(int)); // Resize array to desired size
            if (!keys) { 
                printf("Failed to allocate memory for keys\n");
                pthread_mutex_unlock(&lock);
                return;
            }
        }

        if (oldOffsetSize < num_records) {
            offsets = realloc(offsets, num_records * sizeof(long)); // Resize array to desired size
            if (!offsets) { 
                printf("Failed to allocate memory for offsets\n");
                pthread_mutex_unlock(&lock);
                return;
            }
        }

        if (oldRecordSize < num_records) {
            records = realloc(records, num_records * sizeof(record)); // Resize array to desired size
            if (!records) { 
                printf("Failed to allocate memory for records\n");
                pthread_mutex_unlock(&lock);
                return;
            }
        }

        oldKeySize = num_records;
        oldOffsetSize = num_records;
        oldRecordSize = num_records;

        // Generate random values using CSPRNG
        for (int i = 0; i < num_records; i++) {
            unsigned int value;
            if(RAND_bytes((unsigned char*)&value, sizeof(unsigned int)) != 1) { 
                printf("Failed to generate random number\n");
                pthread_mutex_unlock(&lock);
                return;
            }

            keys[i] = value % 2147483647; // Convert generated unsigned int into a signed int for key
        }

        break;
    }

    // Initialize records with random values from 0 to 1000 (inclusive)
    for(int i = 0; i < num_records; i++){
        unsigned int value;
        if(RAND_bytes((unsigned char*)&value, sizeof(unsigned int)) != 1) { 
            printf("Failed to generate random number\n");
            pthread_mutex_unlock(&lock);
            return;
        }

        records[i].value = value % 1001; // Convert generated unsigned int into a signed int for record
    }

    pthread_mutex_unlock(&lock); // Unlock mutex after modifying data structures

    free(keys); // Free allocated memory when done
    free(offsets); 
    free(records);
}
```
This code first acquires a lock before modifying the data structures. It then dynamically resizes arrays as necessary, using `realloc` to avoid unnecessary reallocations and copy operations. It generates random values using the OpenSSL CSPRNG (`RAND_bytes`). If memory allocation or CSPRNG generation fails, it logs an error message and gracefully exits. Finally, it releases the lock and frees all allocated memory when done.
']

