            exit(EXIT_FAILURE);
        }
    }

    // Find and print the largest integer in the array
    int max = INT_MIN;
    for (int i = 0; i < count; i++) {
        if (numbers[i] > max) {
            max = numbers[i];
        }
    }
    printf("Maximum value: %d\n", max);

    // Delete the semaphore
    if (sem_destroy(&semaphore) == -1) {
