['This problem involves several advanced concepts like dynamic memory allocation, error handling, file I/O operations, JSON parsing, and periodic updates. Here's a possible solution in C, using the cJSON library for JSON parsing and libcurl to check for updates periodically:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>
#include <unistd.h>
#include "cJSON.h"
#include <curl/curl.h>

typedef struct NetworkInterfaceContext {
    char* interface_id;
    int link_metrics;  // Assuming this is an integer for simplicity, but could be complex type in real-world scenario
    float upload_limit;
    float download_limit;
} NetworkInterfaceContext;

CURLcode get_latest_config(char* url) {
    CURL *curl = curl_easy_init();

    if (curl) {
        FILE *fp;

        curl_easy_setopt(curl, CURLOPT_URL, url);
        fp = fopen("/tmp/config.json", "wb");

        if (!fp) {
            return 1;
        }

        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, fp);
        curl_easy_perform(curl);
        fclose(fp);
    }

    return 0;
}

NetworkInterfaceContext* parse_config() {
    FILE *file = fopen("/tmp/config.json", "rb");

    if (!file) {
        printf("Could not open config file\n");
        exit(1);
    }

    fseek(file, 0, SEEK_END);
    long length = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *data = malloc(length + 1);

    if (!data) {
        printf("Could not allocate memory for file data\n");
        exit(2);
    }

    fread(data, 1, length, file);
    data[length] = 0;

    cJSON *config = cJSON_Parse(data);
    free(data);

    if (!config) {
        printf("Could not parse config file\n");
        exit(3);
    }

    NetworkInterfaceContext *list[1000];  // Assuming max of 1000 interfaces
    int i = 0;

    for (cJSON *interface = config->child; interface != NULL; interface = interface->next) {
        list[i] = malloc(sizeof(NetworkInterfaceContext));

        if (!list[i]) {
            printf("Could not allocate memory for NetworkInterfaceContext\n");
            exit(4);
        }

        cJSON *interface_id = cJSON_GetObjectItemCaseSensitive(interface, "interface_id");
        cJSON *link_metrics = cJSON_GetObjectItemCaseSensitive(interface, "link_metrics");
        cJSON *upload_limit = cJSON_GetObjectItemCaseSensitive(interface, "upload_limit");
        cJSON *download_limit = cJSON_GetObjectItemCaseSensitive(interface, "download_limit");

        if (!cJSON_IsString(interface_id) || !cJSON_IsNumber(link_metrics) ||
            !cJSON_IsNumber(upload_limit) || !cJSON_IsNumber(download_limit)) {
            printf("Invalid config file\n");
            exit(5);
        }

        list[i]->interface_id = strdup(interface_id->valuestring);
        list[i]->link_metrics = link_metrics->valueint;
        list[i]->upload_limit = (float) upload_limit->valuedouble;
        list[i]->download_limit = (float) download_limit->valuedouble;

        i++;
    }

    cJSON_Delete(config);

    return list;
}

int main() {
    get_latest_config("http://example.com/config.json");  // Replace with real URL

    NetworkInterfaceContext *list = parse_config();

    // Use the list as needed...

    for (int i = 0; i < 1000; i++) {
        if (list[i]) {
            free(list[i]->interface_id);
            free(list[i]);
        } else {
            break;
        }
    }

    return 0;
}
```

