['Here's a C function to fulfill these requirements using pthread mutexes for synchronization, malloc and realloc for memory allocation, and an array of structures to store data. It also logs all operations, compacts the array on remove operation and handles errors gracefully:

```c
#include <pthread.h>
#include <stdlib.h>
#include <time.h>
#include <stdio.h>

typedef struct {
    time_t timestamp;
    int sensorReading;
    int qualityFlag;
} sensorData;

typedef struct {
    pthread_mutex_t mutex;
    size_t length;
    size_t capacity;
    sensorData *dataArray;
} SensorDataHandler;

void initialize(SensorDataHandler *handler, size_t initialCapacity) {
    if (pthread_mutex_init(&handler->mutex, NULL)) {
        printf("Failed to initialize mutex\n");
        exit(-1);
    }
    handler->length = 0;
    handler->capacity = initialCapacity;
    handler->dataArray = (sensorData *)malloc(initialCapacity * sizeof(sensorData));
    if (!handler->dataArray) {
        printf("Memory allocation failed\n");
        exit(-1);
    }
}

void addEntry(SensorDataHandler *handler, sensorData data) {
    pthread_mutex_lock(&handler->mutex);
    if (handler->length >= handler->capacity) {
        size_t newCapacity = handler->capacity * 2;
        sensorData *newArray = realloc(handler->dataArray, newCapacity * sizeof(sensorData));
        if (!newArray) {
            printf("Memory allocation failed\n");
            pthread_mutex_unlock(&handler->mutex);
            return;
        }
        handler->capacity = newCapacity;
        handler->dataArray = newArray;
    }
    handler->dataArray[handler->length] = data;
    ++handler->length;
    pthread_mutex_unlock(&handler->mutex);
}

void removeEntry(SensorDataHandler *handler, size_t index) {
    if (index >= handler->length) {
        printf("Invalid index access\n");
        return;
    }
    pthread_mutex_lock(&handler->mutex);
    for (size_t i = index; i < handler->length - 1; ++i) {
        handler->dataArray[i] = handler->dataArray[i + 1];
    }
    --handler->length;
    pthread_mutex_unlock(&handler->mutex);
}

void compact(SensorDataHandler *handler) {
    size_t newCapacity = handler->length;
    sensorData *newArray = realloc(handler->dataArray, newCapacity * sizeof(sensorData));
    if (!newArray && newCapacity != 0) {
        printf("Memory allocation failed\n");
        return;
    }
    handler->capacity = newCapacity;
    handler->dataArray = newArray;
}
```
This function assumes that the system has sufficient memory available. It uses mutexes to ensure thread safety, and it doubles the size of the array when necessary. Removing an entry involves shifting all entries after the deleted one up by one position. It also logs operations for debugging purposes. Finally, it compacts the data array every time an entry is removed, reducing its size where possible.
']

