['This is quite a complex task that involves multiple facets of computer programming. It's not possible to provide the complete code here due to its complexity, but I can certainly give you a skeleton structure for your function in C:

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} Record;

typedef struct {
    Record* records;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    FILE* logFile;
} DynamicArray;

DynamicArray* createArray() {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (array == NULL) return NULL;

    array->records = malloc(sizeof(Record)*2); //start with a capacity of 2
    if (array->records == NULL) {
        free(array);
        return NULL;
    }

    array->capacity = 2;
    array->size = 0;
    pthread_mutex_init(&(array->lock), NULL);
    array->logFile = fopen("log.txt", "w"); //opens log file for writing
    if (array->logFile == NULL) {
        free(array->records);
        free(array);
        return NULL;
    }

    return array;
}

void addRecord(DynamicArray* array, int value) {
    pthread_mutex_lock(&(array->lock)); //ensure thread safety

    if (array->size >= array->capacity) {
        size_t newCapacity = array->capacity * 2;
        Record* temp = realloc(array->records, sizeof(Record)*newCapacity);
        //handle memory allocation failure

        if (temp == NULL) {
            pthread_mutex_unlock(&(array->lock));
            return;
        }

        array->records = temp;
        array->capacity = newCapacity;
    }

    array->records[array->size].value = value;
    array->size++;

    //log operation
    fprintf(array->logFile, "Record added: %d\n", value);

    pthread_mutex_unlock(&(array->lock)); //release lock
}

void removeRecord(DynamicArray* array, size_t index) {
    if (index >= array->size) return; //handle invalid index access

    pthread_mutex_lock(&(array->lock)); //ensure thread safety

    for (size_t i = index; i < array->size - 1; ++i) {
        array->records[i] = array->records[i+1];
    }

    array->size--;

    //log operation
    fprintf(array->logFile, "Record removed: %d\n", index);

    pthread_mutex_unlock(&(array->lock)); //release lock
}

void destroyArray(DynamicArray* array) {
    fclose(array->logFile);
    free(array->records);
    free(array);
}
```
Note that this is a simple implementation for demonstration purpose. Real world usage will require more complex solutions and additional details such as handling different update frequencies of sensors, integrating with real time data feeds, etc. Also, the resizing mechanism in `addRecord` function can be optimized by using exponential growth or some other strategy to prevent frequent reallocations when adding small amounts of data. Compaction for removal of records can be implemented based on your requirements.
']

