    for (int i = 0; i < connCount; ++i) {
        if (connections[i]->connectionId == connId) return 0;
    }
    return 1;
}

// Add a new connection with unique id.
void addConnection(TCPConnection* conn) {
    pthread_mutex_lock(&lock);

    if (connCount < maxConns && isUniqueId(nextConnId)) {
        connections[connCount] = conn;
        conn->connectionId = nextConnId++;
        ++connCount;
    } else {
