typedef struct Data {
    int int_field;
    double double_field;
} Data;

void* checkedMalloc(size_t size) {
    void *p = malloc(size);
    if (p == NULL) {
        fprintf(stderr, "Failed to allocate memory.\n");
        exit(EXIT_FAILURE);
    }
    return p;
}

void* checkedRealloc(void* ptr, size_t size) {
    void *p = realloc(ptr, size);
    if (p == NULL) {
        fprintf(stderr, "Failed to reallocate memory.\n");
        free(ptr); // ensure previously allocated memory is freed
        exit(EXIT_FAILURE);
    }
    return p;
}

void allocArrays(double **doubles, char **chars, Data **datas, int n, int minInt, int maxInt, double minDouble, double maxDouble) {
    *doubles = checkedMalloc(n * sizeof(**doubles));
    *chars = checkedMalloc(n * sizeof(**chars));
    *datas = checkedMalloc(n * sizeof(**datas));

    for (int i = 0; i < n; ++i) {
        (*doubles)[i] = minDouble + ((double)rand() / RAND_MAX) * (maxDouble - minDouble);
        (*chars)[i] = 'A' + rand() % 26; // generate random alphabet character
        (*datas)[i].int_field = minInt + rand() % (maxInt - minInt + 1);
        (*datas)[i].double_field = minDouble + ((double)rand() / RAND_MAX) * (maxDouble - minDouble);
    }
}

void processFile(const char* filename, size_t *totalSize) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    double *doubles = NULL;
    char *chars = NULL;
    Data *datas = NULL;
    int records = 0;

    while (1) {
        double dbl;
        char key[256];
        Data data;

        if (fscanf(file, "%lf,%[^,],%d,%lf", &dbl, key, &data.int_field, &data.double_field) != 4) {
            break; // end of file or error reading line
        }

        doubles = checkedRealloc(doubles, (records + 1) * sizeof(*doubles));
        chars = checkedRealloc(chars, (records + 1) * sizeof(*chars));
        datas = checkedRealloc(datas, (records + 1) * sizeof(*datas));

        doubles[records] = dbl;
        strncpy(chars + records, key, sizeof(char[256]) - 1);
        chars[records][sizeof(char[256]) - 1] = '\0'; // ensure null termination for safety

        datas[records] = data;
        ++records;
    }

    *totalSize += records * sizeof(*doubles) + records * sizeof(*chars) + records * sizeof(*datas);

    fclose(file);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s <input file>\n", argv[0]);
        return 1;
    }

    size_t totalSize = 0;
    processFile(argv[1], &totalSize);

    printf("Total memory allocated: %zu bytes\n", totalSize);

    return 0;
}
```
