['Here's a simplified version of the code you asked for. It includes a namespace and a class with constructor, destructor and static member variable for random number generator. Also, it defines a C function that allocates memory for and initializes two arrays, an array of records structures and uses a hash table to track keys.

```cpp
#include <random>
#include <vector>
#include <unordered_map>
#include <mutex>

namespace MyRandom {
    std::mt19937 generator;
}

class RandomNumberGenerator {
public:
    RandomNumberGenerator() = default;
    ~RandomNumberGenerator() = default;

    static int generate(int min, int max) {
        std::uniform_int_distribution<> distribution(min,max);
        return distribution(MyRandom::generator);
    }
};

struct record {
    int value;
};

extern "C" void initializeRecords(long nrecords) {
    static std::mutex mtx; // Static mutex for thread safety.

    if (nrecords > 1000 || nrecords <= 0) {
        printf("Invalid number of records.\n");
        return;
    }

    const std::lock_guard<std::mutex> lock(mtx); // Locks the mutex.

    static long offsets[10]; // Static array for small allocation.

    auto *keys = new (std::nothrow) int[nrecords]; // Dynamic allocation for large data.
    if (!keys) {
        printf("Failed to allocate memory.\n");
        return;
    }

    std::unordered_map<int, bool> keyTracker;

    for (long i = 0; i < nrecords; ++i) {
        int newKey = RandomNumberGenerator::generate(1, 100); // Generating random unique keys.

        while (keyTracker[newKey]) {
            newKey = RandomNumberGenerator::generate(1, 100);
        }

        keyTracker[newKey] = true;
        keys[i] = newKey;
    }

    auto *records = new (std::nothrow) record[nrecords]; // Creating records.
    if (!records) {
        printf("Failed to allocate memory.\n");
        delete[] keys; // Deallocating in case of error.
        return;
    }

    printf("Memory allocation completed successfully.\n");

    for (long i = 0; i < nrecords; ++i) {
        records[i].value = RandomNumberGenerator::generate(1, 100); // Filling record values.
    }
}
```

For the task of loading external data from a file containing offset and key values, it is not directly provided here due to it's complexity which depends on the specific format of the file, handling edge cases etc. You may use libraries like CSV Parser or JSON for C++ for parsing files in various formats. Also remember to handle errors related to reading files as well.
']

