namespace beast = boost::beast;     // from <boost/beast.hpp>
namespace http = beast::http;       // from <boost/beast/http.hpp>
namespace net = boost::asio;        // from <boost/asio.hpp>
using tcp = net::ip::tcp;           // from <boost/asio/ip/tcp.hpp>

// Sends a HTTP request to the server
void SendRequest(const std::string& host, const std::string& port, 
                 const http::request<http::string_body>& req) {
    net::io_context ioc;
    tcp::resolver resolver(ioc);
    beast::tcp_stream stream(ioc);

    auto const results = resolver.resolve(host, port);
    stream.connect(results);

    http::write(stream, req);
    beast::flat_buffer buffer;
    http::response<http::dynamic_body> res;

    http::read(stream, buffer, res);
    std::cout << res << std::endl;
}

int main() {
  // Create JSON object and serialize it into a string.
  nlohmann::json jsonData = {{"DeviceID", "123"}, {"DeviceType", "Test Device"}};

  http::request<http::string_body> req{http::verb::post, "/path/to/your/resource", 11};
  req.set(http::field::host, "localhost");
  req.set(http::field::user_agent, BOOST_BEAST_VERSION_STRING);
  req.set(http::field::content_type, "application/json");
  req.body() = jsonData.dump();
  req.prepare_payload();

  // Send POST request to server
  SendRequest("localhost", "8080", req);

  return 0;
}
```

