Also, this solution assumes that RNTI is an integer and CRCFLAG can be represented as a boolean. If these assumptions are not correct or you need to handle more complex data types or structures, you may need to adjust the code accordingly.

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Node *head = NULL;

void add(int RNTI) {
    Node *newNode = (Node*) malloc(sizeof(Node));
    if(newNode == NULL) return; // Allocation failure

    newNode->pdu.RNTI = RNTI;
    newNode->next = NULL;

    pthread_mutex_lock(&lock);
    Node **pp = &head;
    while(*pp != NULL && (*pp)->pdu.RNTI < RNTI) {
        pp = &((*pp)->next);
    }

    newNode->next = *pp;
    *pp = newNode;
    pthread_mutex_unlock(&lock);
}

void remove(int RNTI) {
    pthread_mutex_lock(&lock);
    Node **pp = &head;

    while(*pp != NULL && (*pp)->pdu.RNTI != RNTI) {
        pp = &((*pp)->next);
    }

    if(*pp != NULL) {
        Node *toFree = *pp;
        *pp = (*pp)->next;
        free(toFree);
    }

    pthread_mutex_unlock(&lock);
}

Node* find(int RNTI) {
    pthread_mutex_lock(&lock);
    Node *p = head;

    while(p != NULL && p->pdu.RNTI < RNTI) {
        p = p->next;
    }

    if(p == NULL || p->pdu.RNTI > RNTI) {
        p = NULL; // Not found
    }
    pthread_mutex_unlock(&lock);

    return p;
}
``` 

