typedef struct node {
    int value;
    struct node* next;
    struct node* prev;
} Node;

void generate_arrays(int size, double** doubleArray, char*** stringArray, Node*** listHead) {
    srand((unsigned int)time(NULL)); // seed the random number generator with current time

    *doubleArray = (double*) malloc(size * sizeof(double));
    if (*doubleArray == NULL) exit(-1);

    *stringArray = (char**) malloc(size * sizeof(char*));
    if (*stringArray == NULL) exit(-1);

    // Allocate space for nodes.
    Node** nodeArray = (Node**) malloc(size * sizeof(Node*));
    if (nodeArray == NULL) exit(-1);

    // Initialize the nodes.
    for (int i = 0; i < size; ++i) {
        nodeArray[i] = (Node*) malloc(sizeof(Node));
        if (nodeArray[i] == NULL) exit(-1);

        (*doubleArray)[i] = rand(); // set double value to a random number

        Node* new_node = nodeArray[i];
        new_node->value = rand(); 
        if (i == 0) {
            new_node->prev = NULL; // first element has no previous
        } else {
            new_node->prev = nodeArray[i - 1];
            nodeArray[i - 1]->next = new_node;
        }

        if (i == size - 1) {
            new_node->next = NULL; // last element has no next
        } else {
            new_node->next = nodeArray[i + 1];
        }
    }

    *listHead = &(nodeArray[0]); // set head of list to first node
}
```
This program creates three types of dynamically allocated arrays (double, char string and linked list nodes). Memory allocation errors are handled by exiting the program when NULL is returned from malloc(). We seed the random number generator with current time. In terms of efficiency vs usability and maintainability trade-offs, this program prioritizes efficiency for allocating memory dynamically and handling large inputs due to its use of dynamic memory allocation. The lack of error checking on user input (e.g., ensuring that size is within the desired range) was deliberately omitted in order to keep the implementation simple.

