    req.body() = "userId=" + user.userId;
    http::write(socket, req);

    boost::beast::flat_buffer buffer;
    http::response<http::dynamic_body> res;
    http::read(socket, buffer, res);

    if (res.result() == http::status::ok) {
      std::cout << "Successful update for user: " << user.userId << std::endl;
    } else if (res.result() == http::status::not_found) {
      std::cout << "Failed update for user: " << user.userId << std::endl;
    } else {
      std::cout << "Internal error updating user: " << user.userId << std::endl;
    }
  }

  boost::system::error_code ec;
  socket.shutdown(tcp::socket::shutdown_both, ec);

  return 0;
}
