    d = opendir("."); // Open current directory

    if (d) {
        char **filenames = NULL;
        int num_files = 0;

        while ((dir = readdir(d)) != NULL) {
            // Filter out non-text files and files not starting with 'data'
            if (!strcmp(&dir->d_name[strlen(dir->d_name)-4], ".txt") && strncmp(dir->d_name, "data", 4) == 0) {
                num_files++;
                filenames = realloc(filenames, sizeof(char *) * num_files); // Dynamically allocate memory for filenames
                filenames[num_files-1] = strdup(dir->d_name);
            }
        }

        qsort(filenames, num_files, sizeof(char *), compare_strs); // Sort file names alphabetically
        for (int i = 0; i < num_files; ++i) {
            process_file(filenames[i]);
            free(filenames[i]);
        }

        free(filenames);
        closedir(d); // Close the directory
    } else {
        fprintf(stderr, "Could not open directory: %s\n", strerror(errno));
        return 1;
    }

    return 0;
}

// Function to process a file and calculate average of numbers in each line
void process_file(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Could not open file %s: %s\n", filename, strerror(errno));
        return;
    }

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), fp) != NULL) {
        double sum = 0.0;
        int count = 0;

        // Tokenize the line using whitespace as delimiter
        const char s[2] = " ";
        char *token;
        token = strtok(buffer, s);

        while (token != NULL) {
            if (isdigit(*token)) {
                double num = atof(token); // Convert string to float
                sum += num;
                ++count;
            }

            token = strtok(NULL, s);
        }

        if (count >= 2) {
            double avg = sum / count;
            printf("%s,%.*f\n", buffer, 2, avg); // Print line followed by average rounded to two decimal places
        } else {
            printf("%s,\n", buffer); // If less than two numbers in the line, print only original values and a newline character
        }
    }

    fclose(fp);
}

// Function for alphabetical sorting of file names
int compare_strs(const void *a, const void *b) {
    return strcmp(*(char *const *)a, *(char *const *)b);
}
```
This code reads files from the current directory and sorts them alphabetically. It then processes each file, calculating the average of numerical values in each line and appending it to a new line. The processed lines are printed to standard output. 

