#define AES_256_GCM "aes-256-gcm"
#define PBKDF2 "pbkdf2"
#define HMAC "hmac"
#define SHA384 "sha384"
#define IV_LENGTH 12
#define SALT_LEN 8
#define KEY_LEN 32
#define TAG_LEN 16

EVP_CIPHER_CTX *aes_gcm_init(const char *pass, size_t passlen) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char key[KEY_LEN], iv[IV_LENGTH];
    unsigned char salt[SALT_LEN];

    // Generate random IV and salt. It is important to generate them from high-entropy source for security reasons.
    RAND_bytes(iv, sizeof(iv));
    RAND_bytes(salt, sizeof(salt));

    // Derive key using PBKDF2 algorithm with HMAC SHA384 as pseudorandom function and OpenSSL library.
    PKCS5_PBKDF2_HMAC((const char*)pass, passlen, salt, SALT_LEN, 1000, EVP_sha384(), KEY_LEN, key);

    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv)) {
        // Clean up on error.
        OPENSSL_free(ctx);
        return NULL;
    }
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, IV_LENGTH, NULL);

    // Clean the sensitive data.
    OPENSSL_cleanse(key, sizeof(key));
    return ctx;
}

void aes_gcm_cleanup(EVP_CIPHER_CTX *ctx) {
    if (ctx != NULL) {
        EVP_CIPHER_CTX_free(ctx);
    }
}
