    int log_level;
} LogEntry;

void loggingModule(int size) {
    if (size < 100 || size > 1000) {
        printf("Invalid input: Size must be between 100 and 1000.\n");
        return;
    }

    // Allocate memory for timestamp, log level arrays
    long* timestamps = (long*)malloc(size * sizeof(long));
    int* log_levels = (int*)malloc(size * sizeof(int));
    if (timestamps == NULL || log_levels == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    // Allocate memory for LogEntry array
    LogEntry* entries = (LogEntry*)malloc(size * sizeof(LogEntry));
    if (entries == NULL) {
        printf("Memory allocation failed.\n");
        free(timestamps);
        free(log_levels);
        return;
    }

    // Seed random number generator
    srand((unsigned int)time(NULL));

    for (int i = 0; i < size; i++) {
        timestamps[i] = time(NULL);  // Current system time

        do {
            log_levels[i] = rand() % 10 + 1;  // Random number between 1 and 10
        } while (i > 0 && log_levels[i] == log_levels[i-1]);  // Ensure no consecutive same log levels

        entries[i].timestamp = timestamps[i];
        entries[i].log_level = log_levels[i];
    }

    // Free memory
    free(timestamps);
    free(log_levels);
    free(entries);
}
