    for (int i = 0; i < size; ++i) {
        points[i].x = ((float)rand() / RAND_MAX * 2 - 1) * 5;  // Random float within [-5, 5).
        points[i].y = ((float)rand() / RAND_MAX * 2 - 1) * 5;  // Random float within [-5, 5).
