    float* distances = calculate_distance(points, size);
    if (distances != NULL) {
        for (int i = 0; i < size; ++i) {
            for (int j = i + 1; j < size; ++j) {
                printf("Distance between points %d and %d: %.2f\n", 
                       i, j, distances[(size * i) + j]);
            }
        }

