#include <string.h>

typedef struct UEContext {
    int ueID;
    char* measurementReport;
    int reportingConfiguration;
    time_t lastUpdateTime;
} UEContext;

typedef struct LTEUEContextManager {
    UEContext** contexts;
    int contextCount;
} LTEUEContextManager;

LTEUEContextManager* createContextManager() {
    LTEUEContextManager* manager = (LTEUEContextManager*)malloc(sizeof(LTEUEContextManager));
    manager->contexts = NULL;
    manager->contextCount = 0;
    return manager;
}

void addUEContext(LTEUEContextManager* manager, int ueID) {
    UEContext* context = (UEContext*)malloc(sizeof(UEContext));
    context->ueID = ueID;
    // Retrieve the measurement report and configuration from an external data source
    // If it fails, handle that here

    manager->contexts = (UEContext**)realloc(manager->contexts, sizeof(UEContext*) * (manager->contextCount + 1));
    manager->contexts[manager->contextCount] = context;
    manager->contextCount++;

    printf("Added UE Context with ID %d\n", ueID);
}

void removeUEContext(LTEUEContextManager* manager, int ueID) {
    for (int i = 0; i < manager->contextCount; ++i) {
        if (manager->contexts[i]->ueID == ueID) {
            free(manager->contexts[i]->measurementReport);
            free(manager->contexts[i]);

            // Shift remaining contexts to fill the gap
            for (int j = i; j < manager->contextCount - 1; ++j) {
                manager->contexts[j] = manager->contexts[j + 1];
            }
            manager->contextCount--;

            printf("Removed UE Context with ID %d\n", ueID);
            return;
        }
    }

    printf("UE Context with ID %d not found. Not removed.\n", ueID);
}

void updateReportingConfiguration(LTEUEContextManager* manager, int ueID, int newConfig) {
    for (int i = 0; i < manager->contextCount; ++i) {
        if (manager->contexts[i]->ueID == ueID) {
            manager->contexts[i]->reportingConfiguration = newConfig;

            printf("Updated Reporting Configuration for UE Context with ID %d\n", ueID);
            return;
        }
    }

    printf("UE Context with ID %d not found. Not updated.\n", ueID);
}
```

