typedef struct {
  unsigned int RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct {
  unsigned int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
  RX_UE_INFORMATION_TAG RX_UE_INFO_Tag;
  CRC_INDICATION_REL8_TAG CrcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t dbMutex = PTHREAD_MUTEX_INITIALIZER; // Mutex for database access control
sqlite3* db; // Database handle
int rc; // return code from SQL functions
char *zErrMsg = 0; 

void populateStructure(NFAPI_CRC_INDICATION_PDU_T* pdu, unsigned int RNTI) {
  srand(time(NULL)); // seeding the random number generator

  pdu->RX_UE_INFO_Tag.RNTI = RNTI;
  pdu->CrcIndicationRel8Tag.CRCFLAG = rand() % (2 << 31); // Generate a random CRCFLAG
}

int logData(NFAPI_CRC_INDICATION_PDU_T* pdu) {
  char *sql;

  // Log the creation of each structure with relevant metadata
  asprintf(&sql, "INSERT INTO log (timestamp, RNTI, CRCFLAG) VALUES (%ld, %u, %u);", time(NULL), pdu->RX_UE_INFO_Tag.RNTI, pdu->CrcIndicationRel8Tag.CRCFLAG);

  // Thread safe database access with mutex locking
  pthread_mutex_lock(&dbMutex);
  rc = sqlite3_exec(db, sql, NULL, 0, &zErrMsg);
  pthread_mutex_unlock(&dbMutex);

  if(rc != SQLITE_OK){
    fprintf(stderr, "SQL error: %s\n", zErrMsg);
    sqlite3_free(zErrMsg);
    return -1; // Error code for database operation failure
  } else {
    return 0; // Successful database operation
  }
}
```
