['This problem requires a deep understanding of C programming, memory management, file I/O operations, error handling mechanisms, logging utilities, and random number generation algorithms. Here is an example solution in the C language:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int value;
} Record;

void handleError(const char* message) {
    fprintf(stderr, "%s\n", message);
    exit(1);
}

void populateFromFile(int *keys, double *values, size_t count, const char* filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) handleError("Failed to open file");

    for(size_t i = 0; i < count; ++i){
        int result = fscanf(file, "%d %lf", &keys[i], &values[i]);
        if (result != 2) handleError("Incorrect data format in file");
    }

    fclose(file);
}

void initializeArrays(long **offsets, int **keys, double **values, Record **records, size_t count, const char* filename){
    *offsets = malloc(count * 2 * sizeof(long));
    if (*offsets == NULL) handleError("Failed to allocate memory for offsets");

    *keys = malloc(count * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        handleError("Failed to allocate memory for keys");
    }

    *values = malloc(count * sizeof(double));
    if (*values == NULL) {
        free(*offsets);
        free(*keys);
        handleError("Failed to allocate memory for values");
    }

    populateFromFile(*keys, *values, count, filename);

    srand(12345); // Seed the random number generator with a constant value for reproducibility.
    *records = malloc(count * sizeof(Record));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        free(*values);
        handleError("Failed to allocate memory for records");
    }

    // Initialize the 'record' structures with random integers in range [1, 100].
    for(size_t i = 0; i < count; ++i){
        (*records)[i].value = rand() % 100 + 1;
    }
}

void cleanupArrays(long *offsets, int *keys, double *values, Record *records) {
    free(offsets);
    free(keys);
    free(values);
    free(records);
}
```

