void allocate_and_initialize(size_t size) {
    // Allocating memory for offset values, keys, and floating-point numbers
    long *offsets = malloc(sizeof(long) * size);
    int *keys = malloc(sizeof(int) * size);
    double *precision = malloc(sizeof(double) * size);

    // Allocating memory for data_record structures
    data_record *records = malloc(sizeof(data_record) * size);

    if (offsets == NULL || keys == NULL || precision == NULL || records == NULL) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }

    // Initializing offset values, keys, and floating-point numbers with some arbitrary values
    for (size_t i = 0; i < size; ++i) {
        offsets[i] = i * 10;

        srand((unsigned int) time(NULL));
        keys[i] = rand() % 100 + 1; // Random number between 1 and 100
        precision[i] = ((double)rand() / (double)(RAND_MAX)) * 100.0; // Random floating-point value between 0.0 and 100.0

        records[i].key = keys[i];
        records[i].value = precision[i];
        asprintf(&records[i].id, "ID_%zu", i); // Allocating memory for and initializing the string field with a unique identifier based on the record index
