```c
#include <stdlib.h>
#include <stdatomic.h>
#include <pthread.h>

typedef struct {
    atomic_uint counter;
    pthread_mutex_t lock;
} MemoryPool;

void* initialize(MemoryPool *pool, size_t recordCount) {
    void *block = NULL;

    pthread_mutex_lock(&pool->lock);

    if (atomic_fetch_add(&pool->counter, 1) == 0) {
        block = malloc(recordCount * sizeof(Record));
    }

    pthread_mutex_unlock(&pool->lock);

    return block;
}
```

The `initialize` function is responsible for allocating memory in a thread-safe manner. It uses an atomic counter to track the number of times it's been called, which allows us to only allocate memory the first time we call the function. Subsequent calls will return the previously allocated block without reallocating memory.

