```c
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Record {
    int key;
    long offset;
} Record;

// Quicksort
void sort(Record arr[], int low, int high) {
  if (low < high) {
    int pivot = arr[high].key;
    int i = (low - 1);

    for (int j = low; j <= high- 1; j++){
        if (arr[j].key < pivot){
            i++;
            Record temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
    }

    Record temp = arr[i + 1];
    arr[i+1] = arr[high];
    arr[high] = temp;

    int pi = i + 1;
    sort(arr, low, pi - 1);
    sort(arr, pi + 1, high);
  }
}

int init_data(long* offsets, int* keys, Record** records, unsigned int seed) {
    if (!seed){
        time_t t;
        srand((unsigned) time(&t));
    } else {
        srand(seed);
    }

    *offsets = (long*)malloc(100 * sizeof(long));
    *keys = (int*)malloc(50 * sizeof(int));
    *records = (Record*)malloc(200 * sizeof(Record));

    if (!*offsets || !*keys || !*records) {
