['Here is a C code that fulfills the requirements mentioned. Note, however, that this code does not handle errors in multi-threaded environments and duplicate key checks are performed using brute force which can impact performance. For production use, it's recommended to add error checking mechanisms and replace brute force method of unique key generation with a more efficient one:
```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <assert.h>
#include <unistd.h>

typedef struct {
    int value;
} record;

long total_memory = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void *safeFunction(void *args) {
    srand((int)time(NULL)); // initialize random seed

    int num_records = ((int*) args)[0];
    int min_value = ((int*) args)[1];
    int max_value = ((int*) args)[2];

    if (num_records <= 0 || min_value < 0 || max_value < min_value) {
        return NULL; // Invalid arguments
    }

    long *offsets = malloc(num_records * sizeof(long));
    int *keys = calloc(max_value-min_value+1, sizeof(int));
    record *records = malloc(num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        // Handle allocation failure
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    pthread_mutex_lock(&lock);
    total_memory += num_records * (sizeof(long) + sizeof(int) + sizeof(record));
    printf("Total Memory Allocated: %ld\n", total_memory);
    pthread_mutex_unlock(&lock);

    for (int i = 0; i < num_records; i++) {
        offsets[i] = 0; // no offset for simplicity

        int key;
        do {
            key = rand() % (max_value - min_value + 1) + min_value; 
        } while(keys[key-min_value]);

        keys[key-min_value] = 1; // mark the assigned key as taken
        records[i].value = key;
    }

    free(offsets);
    free(keys);
    free(records);

    pthread_mutex_lock(&lock);
    total_memory -= num_records * (sizeof(long) + sizeof(int) + sizeof(record));
    printf("Total Memory Freed: %ld\n", total_memory);
    pthread_mutex_unlock(&lock);

    return NULL; // Indicate successful execution
}
```
