#include <stdlib.h>
#include <string.h>

typedef struct {
    int cellIdentity;
    char serviceProfile[20];
} Cell;

typedef struct {
    int neIdentity;
    Cell *cell;
} NetworkElement;

NetworkElement *createNetworkElements(int num_elements) 
{
    // Allocate memory for the network elements array
    NetworkElement *elements = malloc(num_elements * sizeof(NetworkElement));

    if (!elements) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    // Allocate memory for each cell in the network elements array
    for (int i = 0; i < num_elements; i++) 
    {
        elements[i].cell = malloc(sizeof(Cell));

        if (!elements[i].cell) {
            fprintf(stderr, "Memory allocation failed.\n");

            // Free any previously allocated memory and return NULL if an allocation fails
            for (int j = 0; j < i; j++) 
                free(elements[j].cell);

            free(elements);
            return NULL;
