} PDU_Array;

void populate_pdu_list(PDU_Array *array) {
    if (array->count >= array->capacity) {  // if the list is full, reallocate memory
        size_t newCapacity = array->capacity ? array->capacity*2 : 1;
        LTE_MAC_PDU *newElements = realloc(array->elements, sizeof(LTE_MAC_PDU) * newCapacity);
        if (newElements == NULL) {
