typedef struct Connection {
    int id;
    int socket_fd;
    pthread_mutex_t lock;
    time_t last_heartbeat;
} Connection;

Connection connections[MAX_CONNECTIONS];
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;
int config_interval = 5; // Default value
FILE *logfile;

void sendHeartbeat(int connId, int socket_fd) {
    pthread_mutex_lock(&connections[connId].lock);
    if (time(NULL) - connections[connId].last_heartbeat > TIMEOUT_LIMIT) {
        // Send heartbeat message and update last_heartbeat timestamp
        char *message = "HEARTBEAT";
        int len = strlen(message);
        ssize_t bytesSent = send(socket_fd, message, len, 0);

        if (bytesSent == len) {
            fprintf(logfile, "%ld: Connection %d heartbeat sent\n", time(NULL), connId);
        } else {
            fprintf(logfile, "%ld: Failed to send heartbeat for connection %d\n", time(NULL), connId);
        }

        connections[connId].last_heartbeat = time(NULL);
    }
    pthread_mutex_unlock(&connections[connId].lock);
}

void *monitorConnection(void *arg) {
    int connId = *((int*) arg);

    while (1) {
        sendHeartbeat(connId, connections[connId].socket_fd);
        sleep(config_interval); // Pause before sending next heartbeat
    }
}

void addConnection(int id, int socket_fd) {
    pthread_mutex_lock(&global_lock);
    Connection conn;
    conn.id = id;
    conn.socket_fd = socket_fd;
    conn.last_heartbeat = 0; // Default last heartbeat is 0

    if (pthread_mutex_init(&conn.lock, NULL) != 0) {
        printf("Mutex init failed\n");
        return;
    }

    connections[id] = conn;

    pthread_t threadId;
    int *arg = malloc(sizeof(*arg));
    *arg = id;

    if (pthread_create(&threadId, NULL, monitorConnection, arg) != 0) {
        printf("Failed to create thread for connection %d\n", conn.id);
        return;
    }
    pthread_detach(threadId); // Detach the thread to prevent zombie threads

    pthread_mutex_unlock(&global_lock);
}

void removeConnection(int id) {
    pthread_mutex_lock(&connections[id].lock);
    close(connections[id].socket_fd); // Close socket to terminate connection
    connections[id].socket_fd = -1; 

    pthread_mutex_unlock(&connections[id].lock);
}

void updateConnectionInterval(int interval) {
    config_interval = interval;
}

// External Monitoring System API
