NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize(int N, int lower, int upper) {
    if (N < 0 || N > 100 || lower < 1 || upper > 65535 || upper < lower) {
        printf("Invalid parameters\n");
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    int* used = (int*)calloc(upper - lower + 1, sizeof(int)); // Keep track of used RNTI values

    for (int i = 0; i < N; i++) {
        int rnti;
        do {
            rnti = lower + rand() % (upper - lower + 1); // Randomly generate a new RNTI until an unused one is found
        } while (used[rnti - lower]);

        used[rnti - lower] = 1;

        array[i].RNTI = rnti;
        array[i].CRCFLAG = ((float)rand() / RAND_MAX); // Randomly set CRCFLAG to 0.0 or 1.0
    }

    free(used);

    return array;
}

void print_and_deallocate(NFAPI_CRC_INDICATION_PDU_T* array, int N) {
