        for (size_t j = 0; j < 10; ++j) {
            int r = rand() % 36;  // ASCII printable characters range from 32-67
            if (r <= 9) rec[i].str[j] = '0' + r;
            else if (r <= 35) rec[i].str[j] = 'A' + r - 10;
            else rec[i].str[j] = 'a' + r - 36;
        }
        rec[i].str[10] = 0;  // null terminator
    }
}

pthread_mutex_t lock;
size_t allocated_mem = 0, max_mem = SIZE_MAX / 2;
void* allocate(size_t size) {
    assert(size + allocated_mem <= max_mem);

    pthread_mutex_lock(&lock);
    void* ptr = malloc(size);
    if (ptr != NULL) {
        allocated_mem += size;
    }
    pthread_mutex_unlock(&lock);

    return ptr;
}

void deallocate(void* ptr, size_t size) {
    pthread_mutex_lock(&lock);
    free(ptr);
    allocated_mem -= size;
    pthread_mutex_unlock(&lock);
}
