typedef struct Node {
    int value;
    char *str;
} Node;

Node **nodes = NULL;
char **strings = NULL;
size_t memoryAllocated = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* initializeNodes(int num_nodes, char *buffer) {
    if (num_nodes <= 0 || buffer == NULL) {
        return NULL; // Return error for invalid input parameters
    }

    pthread_mutex_lock(&lock); // Ensure thread safety

    nodes = malloc(num_nodes * sizeof(Node*));
    strings = malloc(num_nodes * sizeof(char*));

    if (nodes == NULL || strings == NULL) {
        free(nodes);  // If allocation failed, release partially allocated memory
        free(strings);
        pthread_mutex_unlock(&lock);
        return NULL; // Return error for failed allocation
    }

    // Safe initialization with validation and tracking
    for (int i = 0; i < num_nodes; i++) {
        nodes[i] = malloc(sizeof(Node));

        if (nodes[i] == NULL) {  // If allocation failed, release partially allocated memory
            for (int j = 0; j < i; j++) {
                free(nodes[j]->str);
                free(nodes[j]);
            }

            free(nodes);  // Release partially allocated memory
            free(strings);
            pthread_mutex_unlock(&lock);
            return NULL; // Return error for failed allocation
        }

        nodes[i]->value = rand() % 100;

        size_t bufferLength = strlen(buffer + (i * strlen(buffer)));
        nodes[i]->str = malloc((bufferLength + 1) * sizeof(char)); // Allocate memory for the string and a null terminator

        if (nodes[i]->str == NULL) {  // If allocation failed, release partially allocated memory
            free(nodes[i]);

            for (int j = 0; j < i; j++) {
                free(nodes[j]->str);
                free(nodes[j]);
            }

            free(nodes);  // Release partially allocated memory
            free(strings);
            pthread_mutex_unlock(&lock);
            return NULL; // Return error for failed allocation
        }

        strcpy(nodes[i]->str, buffer + (i * strlen(buffer)));
        strings[i] = nodes[i]->str;
        memoryAllocated += sizeof(Node) + ((bufferLength + 1) * sizeof(char)); // Track total memory allocated
    }

    pthread_mutex_unlock(&lock); 
    return nodes;
}
```
