#include <stdlib.h>
#include <pthread.h>

// Structure to represent a MAC PDU
typedef struct {
    int type; // DL or UL type
    void* data; // Actual data of MAC PDU
} MAC_PDU;

// Structure to represent a UE Context
typedef struct ueContext{
    char* UEID;
    MAC_PDU* macpdu;
    pthread_mutex_t lock; // For handling race conditions
    struct ueContext *next;
} UeContext;

// Structure to manage list of UE Contexts
typedef struct {
    UeContext* head;
    pthread_mutex_t lock;
} UEContextList;

UEContextList* createAndPopulateUeContext(char** ueids, int size) {
    UEContextList* l = (UEContextList*)malloc(sizeof(UEContextList));
    l->head = NULL;
    pthread_mutex_init(&l->lock, NULL);

    // Create and populate UeContext nodes for each UEID 
    for (int i = 0; i < size; ++i) {
        UeContext* node = (UeContext*)malloc(sizeof(UeContext));
        pthread_mutex_init(&node->lock, NULL);

        // Here you could potentially integrate with an NMS to fetch ueid info.
        // And get MAC PDU from external data sources and handle different formats etc.
        node->UEID = ueids[i]; 
        node->macpdu = (MAC_PDU*)malloc(sizeof(MAC_PDU));

        pthread_mutex_lock(&l->lock);
        {
            // Insert new nodes at the beginning of the list
            node->next = l->head;
            l->head = node;
        }
        pthread_mutex_unlock(&l->lock);
    }

    return l;
}
``` 
