#include <time.h>
std::atomic<long> lastTimestamp(0);

// Generate unique timestamp
long getUniqueTimeStamp() {
    long ts = time(nullptr);
    while (ts <= lastTimestamp) 
        ts = time(nullptr);

    return lastTimestamp.exchange(ts);
}
