    // Error handling for out-of-memory conditions
    if ((numGroups * sizeof(group)) + (numItems * numGroups * sizeof(item)) > 2097152) {
        printf("Out of memory\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for groups and items
    group** groups = malloc(numGroups * sizeof(group));
    if (groups == NULL) {
        perror("Memory allocation failure");
        exit(EXIT_FAILURE);
