    item** allItems = malloc(numItems * numGroups * sizeof(item));
    if (allItems == NULL) {
        free(groups);
        perror("Memory allocation failure");
        exit(EXIT_FAILURE);
    }

    // Initialize groups with pointers to items
    for (int i = 0; i < numGroups; i++) {
        groups[i].numItems = numItems;
        groups[i].items = &allItems[i * numItems];
    }

    // Initialize item fields
    char* predefinedStrings[] = {"hello", "world", "foo", "bar"};  // Sample strings
    int numPredefined = 4;  // Number of predefined strings

    for (int i = 0; i < numGroups; i++) {
