    *records = calloc(n, sizeof(Record));

    // Check if allocation failed
    if(*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation error\n");
        exit(1);
    }

    // Initialize arrays and structures with random values within specified ranges
    for (size_t i = 0; i < n; ++i) {
        (*offsets)[i] = rand() % LONG_MAX;  // Long offsets range from 0 to LONG_MAX
        do {
            (*keys)[i] = rand() % INT_MAX;   // Keys range from 0 to INT_MAX
        } while(isRepeatedKey(*keys, i));     // Ensure no two records have the same key
    }
}

int isRepeatedKey(int* keys, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        if(keys[n] == keys[i]) {
            return 1;   // Repeated key found
        }
    }
    return 0;   // No repeated key found
}

void freeMemory(long* offsets, int* keys, Record* records) {
    // Free allocated memory
    free(offsets);
    free(keys);

    for (size_t i = 0; i < _n_; ++i) {
        free(records[i].str_ptr);   // Free each string in the record structure
    }
    free(records);  // Finally, free the records array
}
```

This function dynamically allocates memory for three arrays and initializes them with random values. It also checks if allocation failed and handles this error gracefully. The `isRepeatedKey` helper function is used to ensure that no two records have the same key value. Finally, the `freeMemory` function frees all allocated memory when it's no longer needed.
