#define MAX_TASKS 1000
#define MAX_WORKERS 64
#define TASK_TIMEOUT 5000  // in microseconds
#define IDLE_LIFETIME 3000000000  // in nanoseconds

typedef struct {
    void (*task)(void *);
    void *args;
} task_t;

atomic_int num_workers;
pthread_mutex_t worker_lock = PTHREAD_MUTEX_INITIALIZER;

task_t tasks[MAX_TASKS];
volatile int head = 0, tail = 0;

void *worker(void *arg) {
    (void) arg;  // Avoid compiler warnings about unused parameter
    struct timespec start_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (1) {
        if (!atomic_load(&num_workers)) break;

        task_t *task = NULL;

        pthread_mutex_lock(&worker_lock);
        if (head != tail) {  // Queue is not empty
            task = &tasks[tail];
            tail = (tail + 1) % MAX_TASKS;
        }
        pthread_mutex_unlock(&worker_lock);

        struct timespec current_time;
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        long elapsed_ns = (current_time.tv_sec - start_time.tv_sec) * 1000000000 + (current_time.tv_nsec - start_time.tv_nsec);

        if (task != NULL && elapsed_ns >= IDLE_LIFETIME) {
            // Kill this worker since it's been idle for too long
            atomic_fetch_sub(&num_workers, 1);
            break;
        } else if (task != NULL) {
            task->task(task->args);
        } else {
            usleep(TASK_TIMEOUT);
        }
    }

    return NULL;
}

void submit_task(void (*task)(void *), void *args) {
    pthread_mutex_lock(&worker_lock);

    // Check if the task queue is full and we need to create a new worker thread if necessary.
    // Note: This naively assumes that each submitted task takes roughly the same time to process, which may not be true in reality.
    while ((head + 1) % MAX_TASKS == tail && num_workers < MAX_WORKERS) {
        pthread_t worker_thread;
        if (pthread_create(&worker_thread, NULL, &worker, NULL)) {
            fprintf(stderr, "Failed to create new worker thread\n");
            exit(EXIT_FAILURE);
        }
        atomic_fetch_add(&num_workers, 1);
    }

    tasks[head].task = task;
    tasks[head].args = args;
    head = (head + 1) % MAX_TASKS;

    pthread_mutex_unlock(&worker_lock);
}

