typedef struct {
    int value;
} Record;

void memory_management(long **offsets, int **keys, Record ***records, 
                        size_t offsetSize, size_t keySize, size_t recordSize) {

    assert(offsets != NULL);
    *offsets = (long*) malloc(sizeof(long)*offsetSize);
    if (*offsets == NULL) exit(-1);

    assert(keys != NULL);
    *keys = (int*) calloc(keySize, sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        exit(-1);
    }

    assert(records != NULL);
    *records = (Record**) malloc(sizeof(Record*)*recordSize);
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        exit(-1);
    }

    srand((unsigned int) time(NULL)); // for random values in records
    const int range_min = 0;
    const int range_max = 100;

    for (size_t i = 0; i < recordSize; ++i) {
        Record *record = malloc(sizeof(Record));
        if (record == NULL) {
            free(*offsets);
            free(*keys);

            // free previously allocated records
            for (size_t j = 0; j < i; ++j) 
                free((*records)[j]);

            free(*records);
            exit(-1);
        }

        record->value = rand() % (range_max - range_min + 1) + range_min;
        (*records)[i] = record;
    }
}

void sortRecords(Record **records, long *offsets, size_t size) {
    // Implementation of a simple bubble sort algorithm to sort records by offset value
    for (size_t i = 0; i < size-1; ++i) {
        for (size_t j = 0; j < size-i-1; ++j) {
            if (offsets[j] > offsets[j+1]) {
                // Swap records and offsets
                Record *tempRecord = records[j];
                long tempOffset = offsets[j];

                records[j] = records[j+1];
                offsets[j] = offsets[j+1];

                records[j+1] = tempRecord;
                offsets[j+1] = tempOffset;
            }
        }
    }
}
```
The `memory_management` function is responsible for allocating memory for the arrays of offset values, keys and record structures. If an allocation fails, it frees all previously allocated memory and exits with a failure code. 

Before returning from `memory_management`, we populate the records array with randomly generated integers in the specified range. This is done inside a loop that runs until every element of the array has been successfully initialized. If any allocation fails during this process, it frees all previously allocated memory and exits with a failure code.

Please note: 
- The sorting algorithm used here (bubble sort) can be optimized for large arrays using other algorithms or data structures like quicksort, mergesort etc. This is kept simple to showcase the basic concept of memory management and error handling.
- Memory for `records` array elements is not free'd in this code. You would need to add another loop to iterate over each record and call `free(record)` before exiting if you want to prevent memory leaks. 
