#include <pthread.h>

typedef struct {
    int value;
} record;

// mutex for thread safety
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

size_t initialize_records(int key, int range_min, int range_max, size_t num_records) {
    // input validation
    if (range_min >= range_max || num_records <= 0) {
        return -1;  // or any appropriate error code
    }

    pthread_mutex_lock(&lock);

    // allocate memory for arrays
    long* offsets = malloc(sizeof(long) * num_records);
    int* keys = malloc(sizeof(int) * num_records);
    record* records = calloc(num_records, sizeof(record));  // zero-initialize memory

    if (offsets == NULL || keys == NULL || records == NULL) {
        pthread_mutex_unlock(&lock);
        return -1;  // or any appropriate error code
    }

    srand(time(NULL));  // seed the random number generator

    size_t count = 0;
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = rand() % (range_max - range_min + 1) + range_min;  // generate random value within given range

        keys[i] = key;  // initialize to provided key

        records[i].value = rand() % (range_max - range_min + 1) + range_min;  // generate random record value

        if (keys[i] == key) {
            ++count;
        }
    }

    pthread_mutex_unlock(&lock);

    free(offsets);
    free(keys);
    free(records);

    return count;  // number of records with specified key value
}
```

This function does the following:
- Initializes and allocates memory for three arrays using `malloc`, `calloc`, and `realloc`.
- Generates random numbers within a given range for both 'long' offset values and 'int' keys.
