    generator->seed = seed;
    srand(generator->seed);
    generator->range.min = 0.0f;
    generator->range.max = 1.0f;
    pthread_mutex_init(&generator->mutex, NULL);
}

void UpdateRange(DataGenerator* generator, float min, float max) {
    pthread_mutex_lock(&generator->mutex);
    generator->range.min = min;
    generator->range.max = max;
    pthread_mutex_unlock(&generator->mutex);
}

int GenerateRandomInt(DataGenerator* generator) {
    pthread_mutex_lock(&generator->mutex);
    int randValue = (rand() % ((int)generator->range.max - (int)generator->range.min + 1)) + (int)generator->range.min;
    pthread_mutex_unlock(&generator->mutex);
    return randValue;
}

float GenerateRandomFloat(DataGenerator* generator) {
    pthread_mutex_lock(&generator->mutex);
    float scale = (float)(rand()) / RAND_MAX;
    float randValue = generator->range.min + scale * (generator->range.max - generator->range.min);
    pthread_mutex_unlock(&generator->mutex);
    return randValue;
}

void GenerateRandomString(DataGenerator* generator, int length, char* buffer) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
