    int index = findBaseStationIndexById(baseStationId);
    if (index != -1) {
        // Remove UE Context from the base station.
        for (int i = 0; i < numberOfUEsInBaseStation; i++) {
            if (baseStationList[index][i] == context) {
                free(context);
                memmove(&baseStationList[index][i], &baseStationList[index][i + 1], sizeof(UEContext*) * (numberOfUEsInBaseStation - i - 1));
                break;
            }
        }

        numberOfUEsInBaseStation--;
    }

    pthread_mutex_unlock(&listLock);
}

