    int index = findBaseStationIndexById(baseStationId);
    if (index != -1) {
        for (int i = 0; i < numberOfUEsInBaseStation; i++) {
            pthread_t thread;

            // Create a new thread to process the report.
            pthread_create(&thread, NULL, generateReport, report);

            if (report->criticality == 1) {
                // If the report is urgent, detach it from its parent thread and let it run independently.
                pthread_detach(thread);
            } else {
                // Otherwise, wait for it to finish before continuing.
