void* allocateAndInit(size_t size, int keyRangeMin, int keyRangeMax, 
                      int recordValueRangeMin, int recordValueRangeMax, unsigned int seed) {
    pthread_mutex_lock(&lock); // Lock for thread safety

    srand(seed); // Set random seed

    long* offsets = malloc(size * sizeof(long));
    if (offsets == NULL) {
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    int* keys = malloc(size * sizeof(int));
    if (keys == NULL) {
        free(offsets);
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    record* records = malloc(size * sizeof(record));
    if (records == NULL) {
        free(offsets);
        free(keys);
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) { // Initialize arrays
        offsets[i] = i;
        keys[i] = rand() % (keyRangeMax - keyRangeMin + 1) + keyRangeMin;

        records[i].value = rand() % (recordValueRangeMax - recordValueRangeMin + 1) + recordValueRangeMin;

        // Allocate and initialize string pointer in each 'record' structure
        size_t strSize = 10;
        char* str = malloc(strSize);
        if (str == NULL) {
            free(offsets);
            free(keys);
            free(records);
            printf("Memory allocation failed\n");
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        for (size_t j = 0; j < strSize - 1; ++j) {
            int randomChar = rand() % (26 + 26 + 10); // generate a random character [A-Z] or [a-z] or [0-9]
            if (randomChar < 26)
                str[j] = 'A' + randomChar; // A-Z
            else if (randomChar < 52)
                str[j] = 'a' + randomChar - 26; // a-z
            else
                str[j] = '0' + randomChar - 52; // 0-9
        }
        str[strSize - 1] = '\0';

        records[i].str = str;
    }

    memoryUsed += size * (sizeof(long) + sizeof(int) + sizeof(record));
    if (memoryUsed > MAX_MEMORY) { // Check for resource exhaustion
        printf("Memory usage exceeded\n");
        free(offsets);
        free(keys);
        free(records);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    pthread_mutex_unlock(&lock); // Unlock for thread safety

    printf("Memory allocation successful\n");
}
