    // Dynamically allocate memory for arrays and initialize them
    long *offsets = malloc(sizeof(long) * records);
    char *keys = malloc(sizeof(char) * records);
    Data *dataArr = malloc(sizeof(Data) * records);

    // Track total memory allocated by the function
    size_t totalMemory = 0;
    totalMemory += sizeof(long) * records + sizeof(char) * records + sizeof(Data) * records;

    char line[128];
    size_t count = 0, duplicates = 0, invalidLines = 0;
    while (fgets(line, sizeof(line), file)) {
