#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int priorityLevel;
    int arp;
} ServiceInstanceInfo;

typedef struct {
    int elementID;
    ServiceInstanceInfo *serviceInstances;
    int serviceCount;
} NetworkElementInfo;

typedef struct Node {
    NetworkElementInfo data;
    struct Node *next;
} Node;

Node *head = NULL; // Global linked list for storing network elements.
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // Thread-safe lock.

void addNetworkElement(int elementID, int serviceCount) {
    pthread_mutex_lock(&lock);

    Node *newNode = (Node*) malloc(sizeof(Node));
    newNode->data.elementID = elementID;
    newNode->data.serviceInstances = (ServiceInstanceInfo*) malloc(serviceCount * sizeof(ServiceInstanceInfo));
    newNode->data.serviceCount = serviceCount;

    // Generate random QoS parameters for each service instance
    srand(time(NULL));
    for(int i = 0; i < serviceCount; ++i) {
        newNode->data.serviceInstances[i].priorityLevel = rand() % 10 + 1; // Priority level between 1 to 10
        newNode->data.serviceInstances[i].arp = rand() % 2; // ARP is either 0 or 1
    }

    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

void removeNetworkElement(int elementID) {
    pthread_mutex_lock(&lock);

    Node *temp = head, *prev = NULL;

    if (temp != NULL && temp->data.elementID == elementID) { // Check the first node
        head = temp->next;
        free(temp->data.serviceInstances); 
        free(temp);
    } else {
        while (temp != NULL && temp->data.elementID != elementID) { // Search for network element
            prev = temp;
            temp = temp->next;
        }

        if (temp == NULL) return; 

        prev->next = temp->next; // Remove network element from list

        free(temp->data.serviceInstances);
        free(temp);
    }

    pthread_mutex_unlock(&lock);
}
```
This code creates a linked list to hold NetworkElementInfo structures and uses mutexes for thread safety. When adding or removing network elements, it locks the mutex before performing these operations to ensure that they are performed atomically which helps in preventing data corruption when multiple threads attempt to populate the list concurrently. The memory allocated for ServiceInstanceInfo is freed after removing a network element from the list to prevent memory leaks.
