namespace DeviceManager {
    struct DeviceConfig {
        std::string ipAddress;
        int portNumber;
        int timeoutValue;
        std::string macAddress;
    };

    class DeviceConfigManager {
    public:
        static std::unordered_map<std::string, DeviceConfig> configs;
        static size_t totalMemoryAllocated;

        DeviceConfigManager() = default;
        ~DeviceConfigManager() {}
    };

    // Static member variables initialization
    std::unordered_map<std::string, DeviceConfig> DeviceConfigManager::configs;
    size_t DeviceConfigManager::totalMemoryAllocated = 0;
}

extern "C" {
#include <cstring>  // for strlen()

typedef struct {
    char ipAddress[16];  // assuming IP address is max 15 characters long
    int portNumber;
    int timeoutValue;
    char macAddress[18];  // assuming MAC address is 17 characters long
} DeviceConfig_C;

void initializeDevices(int numDevices, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        std::cerr << "Unable to open file: " << filename << std::endl;
        return;
    }

    DeviceConfig_C device;
    char buffer[256];
    size_t bytesRead = 0;
    while (fgets(buffer, sizeof(buffer), file) != nullptr && --numDevices >= 0) {
        sscanf(buffer, "%s %d %d %s", device.ipAddress, &device.portNumber, 
               &device.timeoutValue, device.macAddress);

        // Validate port and timeout values
        if (device.portNumber < 1 || device.portNumber > 65535 || 
            device.timeoutValue < 0) {

            std::cerr << "Invalid port number or timeout value: " 
                      << device.ipAddress << std::endl;
            continue;
        }

        // Generate unique key for ipAddress and insert into unordered_map
        auto result = DeviceManager::DeviceConfigManager::configs.insert({device.ipAddress, {device.ipAddress, device.portNumber, 
                                                                                        device.timeoutValue, device.macAddress}});

        if (!result.second) {
            std::cerr << "Duplicate IP address: " << device.ipAddress << std::endl;
            continue;
        }

        // Track total memory allocated by the function
        DeviceManager::DeviceConfigManager::totalMemoryAllocated += sizeof(device);
    }

    fclose(file);

    // Print allocation information after all allocations are completed
    std::cout << "Total memory allocated: " 
              << DeviceManager::DeviceConfigManager::totalMemoryAllocated << " bytes" << std::endl;
}

void cleanupDevices() {
    for (auto &pair : DeviceManager::DeviceConfigManager::configs) {
        // Deallocate each individual dynamically allocated string in the structure
        free((char*) pair.second.macAddress);
    }

    // Clear unordered_map to ensure all memory is freed 
    DeviceManager::DeviceConfigManager::configs.clear();
}
}  // extern "C"
```
