void updatePassword(DAO *dao, Logger *logger, const char* username, const char* password) {
    pthread_mutex_lock(&updateMutex);

    UserData *user = dao->findUser(username);
    if (!user) {
        printf("User not found\n");
        logger->logError("Failed to update password for user: %s", username);
        pthread_mutex_unlock(&updateMutex);
        return;
    }

    time_t currentTime = time(NULL);
    if (user->numRequests >= MAX_REQUESTS_PER_MINUTE && 
       difftime(currentTime, user->lastUpdatedTime) < 60) {
        printf("Rate limit exceeded\n");
        logger->logError("User: %s exceeded password update rate limit", username);
        pthread_mutex_unlock(&updateMutex);
        return;
    }

    dao->updatePassword(username, password);
    user->numRequests++;
    user->lastUpdatedTime = currentTime;

    logger->logSuccess("User: %s updated their password successfully", username);

    pthread_mutex_unlock(&updateMutex);
}
