int connection_count = 0;  // Number of connections in the list
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;  // Lock for managing connection count and head

// Function to create a new TCP Connection
TCPConnection* CreateNewTCPConnection(char *connection_id, NetworkMetrics metrics, FlowControlConfig flow_control) {
    TCPConnection *newNode = (TCPConnection*)malloc(sizeof(TCPConnection));
