void resize_phy_info_list(PHY_INFO_LIST *list) {
    assert(list != NULL);
    list->capacity *= 2;
    LTE_PHY_INFO_T *newList = (LTE_PHY_INFO_T*)realloc(list->list, list->capacity * sizeof(LTE_PHY_INFO_T));
    if(newList) {
        list->list = newList;
