#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

void allocate_and_initialize(size_t count, long **offsets, int **keys, Record ***records) {
    srand((unsigned int) time(NULL));  // initialize random seed

    *offsets = (long*)malloc(count * sizeof(long));
    if (*offsets == NULL) exit(-1);  // handle malloc failure

    *keys = (int*)calloc(count, sizeof(int));  // zero-initialize keys
    if (*keys == NULL) exit(-1);  // handle calloc failure

    *records = (Record**)malloc(count * sizeof(Record*));
    if (*records == NULL) exit(-1);  // handle malloc failure

    for (size_t i = 0; i < count; ++i) {
        (*offsets)[i] = rand();
        (*keys)[i] = rand() % 100;  // limit the random value within a range
        (*records)[i] = (Record*)malloc(sizeof(Record));
        if ((*records)[i] == NULL) exit(-1);  // handle malloc failure
        (*records)[i]->value = rand() % 100;  // limit the random value within a range
    }
}

void deallocate(long **offsets, int **keys, Record ***records, size_t count) {
    free(*offsets);
    free(*keys);

    for (size_t i = 0; i < count; ++i) {
        free((*records)[i]);  // deallocate each record
    }
    free(*records);  // finally, deallocate the records array
}
```
