['```c
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <pthread.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

typedef struct {
    float value;
    char type;
} SENSOR_DATA;

typedef struct {
    int sensor_id;
    time_t timestamp;
    float measured_value;
} ENV_SENSOR_DATA_T;

typedef struct {
    pthread_mutex_t mutex;
    ENV_SENSOR_DATA_T *list;
    size_t capacity;
    size_t size;
} SENSOR_INFO_LIST;

// Dynamically resizes the list to accommodate new elements.
static void resize(SENSOR_INFO_LIST *sensorInfoList) {
    assert(sensorInfoList);

    sensorInfoList->capacity = (size_t)(1.5f * sensorInfoList->capacity + 2); // Increase capacity by 50% and add a constant factor for new elements
    ENV_SENSOR_DATA_T *newList = realloc(sensorInfoList->list, sensorInfoList->capacity * sizeof(ENV_SENSOR_DATA_T));

    if (newList == NULL) { // If allocation failed, log an error message and exit the program.
        fprintf(stderr, "Failed to allocate memory for new list\n");
        exit(-1);
    }

    sensorInfoList->list = newList;
}

// Initializes a list of sensors with a specific initial capacity.
void initialize(SENSOR_INFO_LIST *sensorInfoList, size_t initialCapacity) {
    assert(sensorInfoList);

    if (initialCapacity < 1) // If the initial capacity is less than 1, log an error message and exit the program.
        fprintf(stderr, "Initial capacity must be greater than zero\n");

    sensorInfoList->list = malloc(initialCapacity * sizeof(ENV_SENSOR_DATA_T));

    if (sensorInfoList->list == NULL) { // If allocation failed, log an error message and exit the program.
        fprintf(stderr, "Failed to allocate memory for list\n");
        exit(-1);
    }

    sensorInfoList->capacity = initialCapacity;
    sensorInfoList->size = 0;
    pthread_mutex_init(&sensorInfoList->mutex, NULL); // Initialize the mutex for thread safety.
}

// Adds a new sensor to the list and resizes if necessary.
void addSensor(SENSOR_INFO_LIST *sensorInfoList, ENV_SENSOR_DATA_T sensor) {
    assert(sensorInfoList);

    pthread_mutex_lock(&sensorInfoList->mutex); // Lock the mutex to ensure exclusive access.

    if (sensorInfoList->size == sensorInfoList->capacity) // If list is full, resize it.
        resize(sensorInfoList);

    sensorInfoList->list[sensorInfoList->size++] = sensor; // Add the new sensor and increment size.

    pthread_mutex_unlock(&sensorInfoList->mutex); // Unlock the mutex to allow other threads to access it.
}

// Frees the memory allocated for the list.
void destroy(SENSOR_INFO_LIST *sensorInfoList) {
    assert(sensorInfoList);

    pthread_mutex_destroy(&sensorInfoList->mutex); // Destroy mutex before freeing list to prevent memory leaks.
    free(sensorInfoList->list);
}

// Saves sensor data to a file.
void saveToFile(SENSOR_INFO_LIST *sensorInfoList, const char *fileName) {
    assert(sensorInfoList && fileName);

    FILE *f = fopen(fileName, "wb");

    if (f == NULL) // If failed to open the file for writing.
        fprintf(stderr, "Failed to open file for writing\n");

    pthread_mutex_lock(&sensorInfoList->mutex); // Lock mutex to ensure exclusive access.

    fwrite(sensorInfoList->list, sizeof(ENV_SENSOR_DATA_T), sensorInfoList->size, f); // Write data to file.

    pthread_mutex_unlock(&sensorInfoList->mutex); // Unlock mutex to allow other threads to access it.

    fclose(f); // Close the file after writing is finished.
}

// Loads sensor data from a file and adds them to the list.
void loadFromFile(SENSOR_INFO_LIST *sensorInfoList, const char *fileName) {
    assert(sensorInfoList && fileName);

    FILE *f = fopen(fileName, "rb");

    if (f == NULL) // If failed to open the file for reading.
        fprintf(stderr, "Failed to open file for reading\n");

    pthread_mutex_lock(&sensorInfoList->mutex); // Lock mutex to ensure exclusive access.

    while (!feof(f)) {
        ENV_SENSOR_DATA_T sensor;
        fread(&sensor, sizeof(ENV_SENSOR_DATA_T), 1, f); // Read data from file.

        if (sensorInfoList->size == sensorInfoList->capacity) // If list is full after reading, resize it.
            resize(sensorInfoList);

        sensorInfoList->list[sensorInfoList->size++] = sensor; // Add the new sensor and increment size.
    }

    pthread_mutex_unlock(&sensorInfoList->mutex); // Unlock mutex to allow other threads to access it.

    fclose(f); // Close the file after reading is finished.
}

int main() {
    SENSOR_INFO_LIST sensorInfoList;
    initialize(&sensorInfoList, 10); // Initialize list with capacity of 10 sensors.

    ENV_SENSOR_DATA_T sensor = { .sensorID = 123, .timestamp = time(NULL), .temperature = 75 };
    addSensor(&sensorInfoList, sensor); // Add a new sensor to the list.

    saveToFile(&sensorInfoList, "sensors.dat"); // Save sensors data to file.

    ENV_SENSOR_DATA_T loadedSensor;
    loadFromFile(&sensorInfoList, "sensors.dat"); // Load sensors data from file and add them to the list.

    destroy(&sensorInfoList); // Free memory allocated for the list.

    return 0;
}
