#include <vector>
using namespace std;
typedef vector<int> vi;
vi match, vis;
vector<vi> AdjList;
bool augments(int l) {                 // return 1 if an augmenting path is found
    if (vis[l]) return 0;             // return 0 otherwise
    vis[l] = 1;
    for (auto r : AdjList[l])
        if ((match[r] == -1) || augments(match[r])) {
            match[r] = l;
            return 1;                           // found 1 augmenting path
        }
    return 0;                               // no augmenting path found
}
int main() {
   int TC, V, M;
   scanf("%d", &TC);
   while (TC--) {
       scanf("%d%d",&V,&M);
       AdjList.assign(2*V+5, vi());
       for (int i = 0; i < M; ++i) {
           int u , v;
           scanf("%d%d", &u, &v);
           --u;--v;
           AdjList[u].push_back(v + V); // forward edge
       }
       match.assign(2*V+5, -1);
       int MCBM = 0;                     // we start with 0 cards in the matching
       for (int l = 0; l < V; ++l) {         // for each card a player can afford to buy...
           vis.assign(V, 0);                   // before augmenting path, reset assignment
           MCBM += augments(l);                    // then we try to find another one
       }
       printf("%d\n", MCBM/2);
   }
