size_t size = 0; 
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; 
int statsCounter = 0; // Statistics counter.

void populateList(NFAPI_CRC_INDICATION_PDU_T* list, int NFAPI_MAX_PDU_SIZE) {
    pthread_mutex_lock(&lock); // Lock the mutex to prevent concurrent access.

    if (list == NULL) { // If the list is not initialized yet, allocate memory for it.
        list = malloc(NFAPI_MAX_PDU_SIZE * sizeof(*list));

        if (list == NULL) { 
            // Handle memory allocation failure.
            pthread_mutex_unlock(&lock);
            return;
        }

        size = NFAPI_MAX_PDU_SIZE;
    } else if (size < NFAPI_MAX_PDU_SIZE) { // If the list is too small, resize it.
        void* newPtr = realloc(list, NFAPI_MAX_PDU_SIZE * sizeof(*list));

        if (newPtr == NULL) { 
            // Handle memory allocation failure.
            pthread_mutex_unlock(&lock);
            return;
        } else {
            list = newPtr;
            size = NFAPI_MAX_PDU_SIZE;
        }
    }

    // Populate the structures in the list with valid data.
    for (int i = 0; i < NFAPI_MAX_PDU_SIZE; ++i) { 
        list[i].RX_UE_INFORMATION_TAG = /* some value */;
        list[i].RNTI = /* some value */;
        list[i].CRCFLAG = /* some value */;
    }

    statsCounter += NFAPI_MAX_PDU_SIZE; // Update the statistics counter.

    pthread_mutex_unlock(&lock); // Unlock the mutex after modifying the list.
}
