#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Record {
    int value;
    double number;
} Record;

static pthread_mutex_t memoryLock = PTHREAD_MUTEX_INITIALIZER;

int allocateMemory(long **offsets, int **keys, double **numbers, Record ***records, 
                   size_t *currentSize, size_t maxAllowed, long *externalOffsets, int *externalKeys, double *externalNumbers) {
    pthread_mutex_lock(&memoryLock);

    if (*currentSize + sizeof(long) > maxAllowed || *offsets == NULL) {
        pthread_mutex_unlock(&memoryLock);
        return -1; // Exceeded the memory limit or invalid pointer to allocated memory.
    }

    // Add new offset value from external data source:
    if (externalOffsets != NULL && *currentSize < maxAllowed) {
        (*offsets)[(*currentSize)/sizeof(long)] = externalOffsets[*currentSize];
        *currentSize += sizeof(long);
    }

    // Add new key value from external data source:
    if (externalKeys != NULL && *currentSize < maxAllowed) {
        (*keys)[(*currentSize)/sizeof(int)] = externalKeys[*currentSize];
        *currentSize += sizeof(int);
    }

    // Add new number value from external data source:
    if (externalNumbers != NULL && *currentSize < maxAllowed) {
        (*numbers)[(*currentSize)/sizeof(double)] = externalNumbers[*currentSize];
        *currentSize += sizeof(double);
    }

    // Allocate and initialize records:
    if ((*records = realloc(*records, sizeof(Record*) + sizeof(Record))) == NULL) {
        pthread_mutex_unlock(&memoryLock);
        return -1; // Memory allocation failed.
    }

    Record *newRecord = malloc(sizeof(Record));
    if (newRecord == NULL) {
        pthread_mutex_unlock(&memoryLock);
        return -1; // Memory allocation failed.
    }

    newRecord->value = 0;  // Fill with external data or any other default value here.
    newRecord->number = 0.0;  // Same as above.

    (*records)[(*currentSize)/(sizeof(Record) + sizeof(void*))] = newRecord;
    *currentSize += sizeof(Record) + sizeof(void*);

    pthread_mutex_unlock(&memoryLock);
    return 0; // Success.
}
```
