The C implementation is a bit complex due to C not having native support for many of the features you need such as exceptions, RAII and classes. Here's a simplified version:

```c
#include <assert.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int value;
} Record;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static uint64_t memoryAllocated = 0;

void* allocateAndInitialize(size_t count) {
    void* memory;

    assert(count > 0 && count <= 1000);  // Ensure input parameters are within acceptable range.

    pthread_mutex_lock(&mutex);  // Lock mutex to ensure thread safety when allocating memory.
    memory = malloc(sizeof(Record) * count);

    if (memory == NULL) {
        fprintf(stderr, "Memory allocation error!\n");
        pthread_mutex_unlock(&mutex);  // Unlock mutex before returning in case of error.
        return NULL;
    }
    memoryAllocated += sizeof(Record) * count;

    for (size_t i = 0; i < count; ++i) {
        static bool first = true;
        int uniqueKey;

        do {
            // Generate a random key. The generator uses the current time as seed to ensure uniqueness across different runs.
            srand((unsigned int)time(NULL));
            uniqueKey = rand();

            if (first) {  // If this is the first record, no need to check for uniqueness.
                ((Record*)memory)[i].value = uniqueKey;
                first = false;
            } else {
                bool unique = true;

                // Check all previously generated keys.
                for (size_t j = 0; j < i; ++j) {
                    if (((Record*)memory)[j].value == uniqueKey) {  // If the key is not unique, generate a new one.
                        unique = false;
                        break;
                    }
                }

                if (unique) {
                    ((Record*)memory)[i].value = uniqueKey;  // The generated key is unique, so we can use it for this record.
                }
            }
        } while (!unique);
    }

    printf("Allocated %lu bytes of memory.\n", sizeof(Record) * count);
    pthread_mutex_unlock(&mutex);  // Unlock mutex once allocation is complete.
    return memory;
}
```

