} LogEntry;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* initialize(size_t recordCount, size_t logEntryCount) {
    if (recordCount <= 0 || logEntryCount <= 0) {
        printf("Error: Invalid array sizes.\n");
        return NULL;
    }

    pthread_mutex_lock(&mutex); // Ensuring atomic operations.

    long* offsets = malloc(recordCount * sizeof(long));
    if (offsets == NULL) {
        printf("Error: Failed to allocate memory for offsets.\n");
        pthread_mutex_unlock(&mutex); // Unlocking on allocation failure.
        return NULL;
    }

    int* keys = calloc(recordCount, sizeof(int));
    if (keys == NULL) {
        printf("Error: Failed to allocate memory for keys.\n");
        free(offsets);
        pthread_mutex_unlock(&mutex); // Unlocking on allocation failure.
        return NULL;
    }

    Record* records = malloc(recordCount * sizeof(Record));
    if (records == NULL) {
        printf("Error: Failed to allocate memory for records.\n");
        free(offsets);
        free(keys);
        pthread_mutex_unlock(&mutex); // Unlocking on allocation failure.
        return NULL;
    }

    LogEntry* logEntries = calloc(logEntryCount, sizeof(LogEntry));
    if (logEntries == NULL) {
        printf("Error: Failed to allocate memory for log entries.\n");
        free(offsets);
        free(keys);
        free(records);
        pthread_mutex_unlock(&mutex); // Unlocking on allocation failure.
        return NULL;
    }

    pthread_mutex_unlock(&mutex);  // Unlocking after successful allocations.
    printf("Memory allocated successfully.\n");
}
