    if (dg == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }

    dg->lower_bound = lower;
    dg->upper_bound = upper;
    pthread_mutex_init(&(dg->mutex), NULL); // Initialize mutex
    return dg; 
}

// Dynamically update the range
void update_range(DataGenerator *dg, int lower, int upper) {
    pthread_mutex_lock(&(dg->mutex));
    dg->lower_bound = lower;
    dg->upper_bound = upper;
    pthread_mutex_unlock(&(dg->mutex));
}

// Generate a random integer within specified range 
int generate_integer(DataGenerator *dg) {
    pthread_mutex_lock(&(dg->mutex));
    int rand_num = (rand() % (dg->upper_bound - dg->lower_bound + 1)) + dg->lower_bound;
    pthread_mutex_unlock(&(dg->mutex));
    return rand_num; 
}

// Generate a random float within specified range
float generate_float(DataGenerator *dg) {
    pthread_mutex_lock(&(dg->mutex));
    float scale = rand() / (float) RAND_MAX; // [0, 1.0]
    float rand_num =  dg->lower_bound + scale * (dg->upper_bound - dg->lower_bound);
    pthread_mutex_unlock(&(dg->mutex));
    return rand_num; 
}
