class RandomGenerator {
public:
    std::mt19937 gen;
    static std::uniform_int_distribution<> dis;

    RandomGenerator() : gen(std::random_device{}()) {}
};

std::uniform_int_distribution<> RandomGenerator::dis = std::uniform_int_distribution<>{0, 100};

extern "C" {
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h> 
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
}

class TcpConnection {
public:
    int clientSocket, serverSocket;

    TcpConnection() : clientSocket(0), serverSocket(0) {}
};

std::mutex mtx; 

extern "C" void* initializeRecords(int recordNum, size_t *memorySize) {
    if (recordNum < 1 || recordNum > 5000) {
        std::cerr << "Invalid number of records. Must be between 1 and 5000." << std::endl;
        return NULL;
    }

    RandomGenerator gen;
    size_t totalMemory = sizeof(int) * recordNum + sizeof(long) * recordNum;
    int* keys = (int*)malloc(totalMemory);
    long* offsets = (long*)malloc(sizeof(long) * recordNum);

    if (!keys || !offsets) {
        std::cerr << "Failed to allocate memory." << std::endl;
        free(keys);
        free(offsets);
        return NULL;
    }

    mtx.lock();
    for (int i = 0; i < recordNum; ++i) {
        offsets[i] = gen.dis(gen.gen);
        keys[i] = gen.dis(gen.gen);

        // Ensure unique key by regenerating if not unique.
        for (int j = 0; j < i; ++j) {
            while (keys[i] == keys[j]) {
                keys[i] = gen.dis(gen.gen);
            }
        }
    }

    *memorySize = totalMemory;
    mtx.unlock();

    return reinterpret_cast<void*>(offsets);
}

extern "C" TcpConnection* createConnections() {
    RandomGenerator gen;
    int clientSocket = 0, serverSocket = 0;
    struct sockaddr_in serv_addr; 

    if ((clientSocket = socket(AF_INET, SOCK_STREAM, 0)) < 0) { 
        std::cerr << "Socket creation error" << std::endl;
        return NULL; 
    } 

    serv_addr.sin_family = AF_INET; 
    serv_addr.sin_port = htons(gen.dis(gen.gen)); 

    if (inet_pton(AF_INET, "127.0.0.1", &serv_addr.sin_addr) <= 0) { 
        std::cerr << "Invalid address/ Address not supported" << std::endl;
        return NULL; 
    } 

    if (connect(clientSocket, (struct sockaddr*)&serv_addr, sizeof(serv_addr)) < 0) { 
        std::cerr << "Connection Failed" << std::endl;
        return NULL; 
    }

    TcpConnection *con = new TcpConnection();
    con->clientSocket = clientSocket;
    con->serverSocket = serverSocket;

    return con;
}
```
Please note that this is a simplified version of the code and does not cover all aspects you requested. It's a start for you to expand on it according to your requirements. Also, please remember that in real-world applications, always use libraries and APIs provided by programming languages when they are available, instead of trying to implement similar functionalities from scratch.
