        printf("Insufficient memory for allocation. Aborting...\n");
        exit(-1);
    }

    long* offsets = mmap(NULL, total_mem, PROT_READ | PROT_WRITE, MAP_PRIVATE|MAP_ANONYMOUS, -1, 0);

    if (offsets == MAP_FAILED) {
