namespace custom {
    std::mutex mtx;  // mutex for critical section

    class Matrix {
        static unsigned int totalMemory;
        float **matrix;
        size_t id, width, height;
        static std::unordered_set<unsigned int> ids;

    public:
        Matrix(size_t w, size_t h) : width(w), height(h) {
            matrix = new float*[height];
            for(int i = 0; i < height; ++i)
                matrix[i] = new float[width];

            std::lock_guard<std::mutex> lock(mtx); // Acquire a lock
            do {
                id = rand();  // Simple way to generate unique IDs, better methods available.
            } while (ids.find(id) != ids.end());

            ids.insert(id);
            totalMemory += sizeof(*this);
        }

        ~Matrix() {
            std::lock_guard<std::mutex> lock(mtx); // Acquire a lock
            for (int i = 0; i < height; ++i) delete[] matrix[i];
            delete[] matrix;
            ids.erase(id);
        }

        static unsigned int getTotalMemory() { return totalMemory; };
    };

    unsigned int Matrix::totalMemory = 0;
    std::unordered_set<unsigned int> Matrix::ids;
}

extern "C" custom::Matrix** createMatrices(size_t count, size_t width, size_t height) {
    if (count < 1 || count > 1000 || width == 0 || height == 0) return nullptr; // Invalid parameters check.

    std::lock_guard<std::mutex> lock(custom::mtx); // Acquire a lock
    custom::Matrix **matrices = new Matrix*[count];
    for (int i = 0; i < count; ++i) {
        try {
            matrices[i] = new custom::Matrix(width, height);
        } catch (std::bad_alloc &e) {
            // Deallocate already allocated matrices on error.
            for (int j = 0; j < i; ++j) delete matrices[j];
            throw e; // Rethrow exception to handle it in upper levels.
        } 
    }

    std::cout << "Total memory allocated: " << custom::Matrix::getTotalMemory() << std::endl;
    return matrices;
}
```
