['Here's a C code that satisfies all your requirements. Please note that serialization and deserialization to/from file is not included in this simple example due to its complexity. However, you can use external libraries such as libcjson for JSON or libxml2 for XML to achieve these features. Also, the resizing of arrays when new data points are added is done naively but it's a good start:

```C
#include <stdlib.h>
#include <string.h>

typedef struct {
    double value;
    char label[20];
} data_point;

void initialize_data_points(int num_points, double min_val, double max_val, int *keys, const char *external_source) {
    // Allocate memory for arrays
    double *values = malloc(num_points * sizeof(*values));
    data_point *data_points = malloc(num_points * sizeof(*data_points));

    // Initialize 'double' and 'int' values
    srand(time(NULL));
    for (int i = 0; i < num_points; ++i) {
        double range = max_val - min_val;
        double div = RAND_MAX / range;
        values[i] = min_val + (rand() / div);
        keys[i] = i + 1;  // Assuming 'keys' is an array of unique integers

        data_points[i].value = values[i];
    }

    // Read from external source and assign labels for each point
    FILE *fp = fopen(external_source, "r");
    if (fp != NULL) {
        char buffer[256], label[20];
        int key;
        while (fscanf(fp, "%d %s", &key, label) == 2) {
            for (int i = 0; i < num_points; ++i) {
                if (keys[i] == key) {
                    strncpy(data_points[i].label, label, 19);
                    data_points[i].label[19] = '\0'; // Ensure null termination
                    break;
                }
            }
        }
        fclose(fp);
    }

    // If memory usage exceeds limit, handle resizing and reallocation
    size_t totalMemoryUsage = 2 * num_points * sizeof(*values) + num_points * sizeof(*data_points);
    if (totalMemoryUsage > 1000000) {  // Example limit of 1MB memory
        int newNumPoints = num_points / 2;  // Naive approach for demonstration, adjust as needed

        double *newValues = realloc(values, newNumPoints * sizeof(*newValues));
        data_point *newDataPoints = realloc(data_points, newNumPoints * sizeof(*newDataPoints));

        if (newValues && newDataPoints) {  // Ensure reallocation succeeded
            values = newValues;
            data_points = newDataPoints;
            num_points = newNumPoints;

            printf("Memory usage exceeded limit. Resized arrays to %d elements.\n", num_points);
        } else {
            printf("Failed to resize arrays. Current memory usage: %zu bytes.\n", totalMemoryUsage);
        }
    }

    // Free allocated memory when done
    free(values);
    free(data_points);
}
```
