int validatePrime(int n) {
    if (n <= 1) return 0;
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) return 0;
    }
    return 1;
}

int validatePowerOfTwo(int n) {
    while(n != 1){
        if(n % 2 != 0) return 0;
        n = n / 2;
     }
     return 1;  
}

int createArrays(long **offsets, int **keys, Record ***records, int size, long *external_offsets, int *external_keys) {
    if (validatePrime(size)) {
        printf("Error: Size should be a prime number.");
        return ERROR_CODE;
    }

    // Allocate memory for offsets array. 
    *offsets = malloc(sizeof(long)*size);
    if (*offsets == NULL) {
