["Here is a solution in C:

```c
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int priority;
    char* description;
    time_t timestamp;
} Task;

typedef struct {
    int id;
    Task** tasks;
} Project;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int initializeTasks(Task** list, size_t numTasks) {
    *list = malloc(numTasks * sizeof(Task));
    if (*list == NULL) return -1; // allocation failure

    for (size_t i = 0; i < numTasks; ++i) {
        (*list)[i].priority = rand() % 100 + 1; // random priority level within [1, 100]
        (*list)[i].description = NULL; // initial description set to NULL for external data source integration
        (*list)[i].timestamp = time(NULL); // timestamp of task creation
    }

    return 0; // success
}

int initializeProjects(Project** list, size_t numProjects) {
    *list = malloc(numProjects * sizeof(Project));
    if (*list == NULL) return -1; // allocation failure

    for (size_t i = 0; i < numProjects; ++i) {
        (*list)[i].id = i + 1; // project id

        // dynamically allocating the task list for each project.
        if(initializeTasks(&((*list)[i].tasks), 20 /* constant tasks per project */)) { // assuming 20 tasks per project
            free(*list);
            return -1; // allocation failure, cleanup previous allocations
        }
    }

    return 0; // success
}

int resizeTaskList(Task** list, size_t newSize) {
    pthread_mutex_lock(&mutex); // ensures thread safety when accessing and modifying task list

    Task* newList = realloc(*list, newSize * sizeof(Task));
    if (newList == NULL && newSize != 0) {
        pthread_mutex_unlock(&mutex); 
        return -1; // allocation failure
    }

    *list = newList;

    for (size_t i = newSize / sizeof(Task); i < newSize; ++i) {
        (*list)[i].priority = 0; // initializing new tasks with default priority 
        (*list)[i].description = NULL; // description set to NULL for external data source integration
        (*list)[i].timestamp = time(NULL); // timestamp of task creation
    }

    pthread_mutex_unlock(&mutex);
    return 0; // success
}

void freeTaskList(Task** list, size_t numTasks) {
    for (size_t i = 0; i < numTasks; ++i) {
        if((*list)[i].description != NULL) {
            free((*list)[i].description); // cleanup allocated strings
        }
    }

    free(*list); 
}

void freeProjectList(Project** list, size_t numProjects) {
    for (size_t i = 0; i < numProjects; ++i) {
        freeTaskList(&((*list)[i].tasks), 20 /* constant tasks per project */); // assuming 20 tasks per project
    }

    free(*list); 
}
```
This code demonstrates a solution to the problem. The `initializeTasks` and `initializeProjects` functions dynamically allocate memory for task and project lists respectively, setting their initial values as required. The `resizeTaskList` function increases or decreases the size of an existing task list using the `realloc` function. Memory is cleaned up by calling `free` on each allocated block when they're no longer needed. Thread safety is ensured through use of a mutex, ensuring only one thread accesses and modifies the task list at a time. 

Please note that this code assumes some constant values for simplicity, such as all projects having exactly 20 tasks. This can be adjusted to suit your specific requirements. Also, the `initializeTasks` function sets descriptions to NULL, implying an external data source is being used to fetch actual task descriptions. Please replace `NULL` with appropriate logic for fetching real descriptions from your data source.
"]

