['Here's the code that meets all the requirements:

```c
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <stdio.h>

typedef struct File {
    char *path;
    long fileSize;
    int permissions;
} File;

// Union-Find data structure
int* parent;

// Create new set
int createSet(int n) {
    if (parent[n] != -1) return -1; // Element already in a set.
    parent[n] = n;
    return n;
}

// Find set representative
int find(int i) {
    while (parent[i] != i) {
        i = parent[i];
    }
    return i;
}

// Union of two sets
void unionSet(int i, int j) {
    int a = find(i);
    int b = find(j);
    if (a != -1 && b != -1) parent[b] = a;
}

File* createFileList(int n) {
    File* files = malloc(n * sizeof(File));
    if (files == NULL) return NULL; // Handle memory allocation failure.

    for (int i = 0; i < n; ++i) {
