#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    atomic_int value;
} Record;

typedef struct {
    pthread_mutex_t mutex;
    _Atomic(Record*) *records;
    size_t capacity;
    size_t size;
} MemoryPool;

MemoryPool create_memory_pool(size_t initial_capacity) {
    MemoryPool pool = { .mutex = PTHREAD_MUTEX_INITIALIZER };
    pool.records = malloc(initial_capacity * sizeof(*pool.records));
    pool.capacity = initial_capacity;
    pool.size = 0;
    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    for (size_t i = 0; i < pool->size; ++i) {
        free(&pool->records[i]);
    }
    pthread_mutex_destroy(&pool->mutex);
    free(pool->records);
}

Record* allocate_record(MemoryPool* pool) {
    if (atomic_load(&pool->size) >= atomic_load(&pool->capacity)) {
        pthread_mutex_lock(&pool->mutex);
        if (atomic_load(&pool->size) >= atomic_load(&pool->capacity)) {  // double check to avoid race condition
            pool->records = realloc(pool->records, 2 * pool->capacity * sizeof(*pool->records));
        }
        pthread_mutex_unlock(&pool->mutex);
    }

    Record* record = calloc(1, sizeof(*record)); // initialize to zeroes
    atomic_store(&pool->records[atomic_fetch_add(&pool->size, 1)], record);
    return record;
}
```
