        for (size_t i = set->capacity; i < newCapacity; ++i) {
            set->labels[i] = malloc(10 * sizeof(char));  // Assuming labels are 9 characters + '\0'.
            if (set->labels[i] == NULL) {
                // Handle allocation failure here.
                return;
            }
        }

        set->capacity = newCapacity;
    }

    set->offsets[set->count] = offset;
    set->keys[set->count] = key;
