int elementsCount = 0;

void resizeList(int newSize) {
    NFAPI_CRC_INDICATION_PDU_T *newList = realloc(list, newSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (newList == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for the list: %s", strerror(errno));
        return;
    } else {
        list = newList;
        listSize = newSize;

        // Initialize newly allocated elements if necessary.
        for (int i = elementsCount; i < listSize; ++i) {
            list[i].RX_UE_INFORMATION_TAG = 0;
            list[i].RNTI = 0;
        }
    }
}

int isDuplicate(NFAPI_CRC_INDICATION_PDU_T *list, int RNTI, int index) {
    for (int i = 0; i < index; ++i) {
        if (list[i].RNTI == RNTI) {
            return 1;
        }
    }
    return 0;
}

void addElement(NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&lock);

    // Resize the list if needed.
    if (elementsCount == listSize) {
        resizeList(listSize + 1024);  // Adjust the increment as per requirement.
    }

    if (!isDuplicate(list, element.RNTI, elementsCount)) {
        list[elementsCount] = element;
        ++elementsCount;
        syslog(LOG_INFO, "Element added to the list with RNTI %d", element.RNTI);
    } else {
        syslog(LOG_ERR, "Duplicate RNTI found: %d", element.RNTI);
    }

