void serialize_to_file(Record *records, int num_records, const char* filename) {
    FILE *f = fopen(filename, "wb");
    if (f == NULL) {
        perror("Error opening file");
        return;
    }

    for (int i = 0; i < num_records; ++i) {
        fwrite(&records[i], sizeof(Record), 1, f);
    }

    fclose(f);
}

void deserialize_from_file(Record **records, int *num_records, const char* filename) {
    FILE *f = fopen(filename, "rb");
    if (f == NULL) {
        perror("Error opening file");
        return;
    }

    Record record;
    while (fread(&record, sizeof(Record), 1, f)) {
        ++(*num_records);
        *records = realloc(*records, (*num_records) * sizeof(Record));
        (*records)[*num_records - 1] = record;
    }

    fclose(f);
}

