void read_csv(const char *filepath, long **offsets, int **keys, Record ***records, size_t num_records) {
    // Validate the input file path
    if (filepath == NULL || strlen(filepath) == 0) {
        fprintf(stderr, "Invalid file path\n");
        return;
    }

    FILE *fp = fopen(filepath, "r");
    if (fp == NULL) {
        perror("Error opening the file");
        return;
    }

    // Allocate memory for arrays
    *offsets = malloc(num_records * sizeof(long));
    if (*offsets == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    *keys = malloc(num_records * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    *records = malloc(num_records * sizeof(Record*));
    if (*records == NULL) {
        free(*keys);
        free(*offsets);
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Initialize random number generator
    srand(time(NULL));

    // Read the CSV file line by line
    char buffer[1024];
    size_t i = 0;
    while (fgets(buffer, sizeof(buffer), fp) != NULL && i < num_records) {
        if (sscanf(buffer, "%ld,%d", &((*offsets)[i]), &((*keys)[i])) == 2) {
            // Allocate memory for and initialize the record structure
            (*records)[i] = malloc(sizeof(Record));
            if ((*records)[i] == NULL) {
                fprintf(stderr, "Memory allocation failed\n");
                break;
            }

            // Generate a random value for the record
            (*records)[i]->value = rand() % 201 - 100;
            ++i;
        } else {
            fprintf(stderr, "Invalid line format in CSV file\n");
            break;
        }
    }

    if (ferror(fp)) {
        perror("Error reading the file");
    }

    // Resize arrays to match actual number of records read from CSV file
    *offsets = realloc(*offsets, i * sizeof(long));
    *keys = realloc(*keys, i * sizeof(int));
    *records = realloc(*records, i * sizeof(Record*));

    fclose(fp);
}
```
