#include "zlib.h"

// Define a record structure
typedef struct {
    long offset;
    int key;
} Record;

// Define a data structure to track statistics and manage concurrency
typedef struct {
    pthread_mutex_t lock;
    size_t numAllocations;
    size_t numDeallocations;
    size_t totalMemoryUsed;
    Record* records;
} DataStructure;

// Initialize the data structure and allocate memory for it
DataStructure* initializeData(size_t size) {
    srand(time(NULL)); // Seed the random number generator

    DataStructure* ds = malloc(sizeof(DataStructure));
    if (ds == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for data structure");
        return NULL;
    }

    ds->records = calloc(size, sizeof(Record));
    if (ds->records == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for records array");
        free(ds);
        return NULL;
    }

    ds->numAllocations = 1;
    ds->totalMemoryUsed = size * sizeof(Record);

    // Initialize the lock
    if (pthread_mutex_init(&(ds->lock), NULL) != 0) {
        syslog(LOG_ERR, "Failed to initialize mutex");
        free(ds->records);
        free(ds);
        return NULL;
    }

    syslog(LOG_INFO, "Data structure initialized successfully");
    return ds;
}

// Populate the data structure with random values within a specified range
void populateRecords(DataStructure* ds, int lowerBound, int upperBound) {
    for (size_t i = 0; i < sizeof(ds->records)/sizeof(Record); ++i) {
        ds->records[i].offset = rand() % (upperBound - lowerBound + 1) + lowerBound;
        ds->records[i].key = rand();
    }
}

// Serialize the data structure to a file using thread safety and compression.
int serializeData(DataStructure* ds, const char* filename) {
    pthread_mutex_lock(&(ds->lock)); // Lock for safe access

    gzFile out = gzopen(filename, "wb");
    if (out == NULL) {
        syslog(LOG_ERR, "Failed to open file for writing: %s", filename);
        pthread_mutex_unlock(&(ds->lock)); // Unlock after error handling
        return -1;
    }

    int result = gzwrite(out, ds->records, sizeof(Record) * (sizeof(ds->records)/sizeof(Record)));
    if (result == 0 || result != sizeof(Record) * (sizeof(ds->records)/sizeof(Record))) {
        syslog(LOG_ERR, "Failed to write data to file: %s", filename);
        gzclose(out);
        pthread_mutex_unlock(&(ds->lock)); // Unlock after error handling
        return -1;
    }

    gzclose(out);
    pthread_mutex_unlock(&(ds->lock)); // Unlock after successful operation

    syslog(LOG_INFO, "Data serialized to file: %s", filename);
    return 0;
}

// Deserialize the data structure from a file
int deserializeData(DataStructure* ds, const char* filename) {
    gzFile in = gzopen(filename, "rb");
    if (in == NULL) {
        syslog(LOG_ERR, "Failed to open file for reading: %s", filename);
        return -1;
    }

    int result = gzread(in, ds->records, sizeof(Record) * (sizeof(ds->records)/sizeof(Record)));
    if (result == 0 || result != sizeof(Record) * (sizeof(ds->records)/sizeof(Record))) {
        syslog(LOG_ERR, "Failed to read data from file: %s", filename);
        gzclose(in);
        return -1;
    }

    gzclose(in);

    syslog(LOG_INFO, "Data deserialized from file: %s", filename);
    return 0;
}

// Clean up the data structure and free memory
void cleanupData(DataStructure* ds) {
    pthread_mutex_destroy(&(ds->lock)); // Destroy lock

    free(ds->records);
    free(ds);

    syslog(LOG_INFO, "Data structure cleaned up successfully");
}
