void allocate_memory(double** doubles, char*** strings, Point*** points, size_t length) {
    *doubles = calloc(length, sizeof(double));
    if (*doubles == NULL) {
        printf("Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    *strings = malloc(sizeof(char*) * length);
    if (*strings == NULL) {
        free(*doubles);
        printf("Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < length; ++i) {
        (*strings)[i] = calloc(MAX_STRING_LENGTH, sizeof(char));
        if ((*strings)[i] == NULL) {
            free(*doubles);
            for (size_t j = 0; j < i; ++j)
                free((*strings)[j]);
            printf("Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
    }

    *points = calloc(length, sizeof(Point));
    if (*points == NULL) {
        free(*doubles);
        for (size_t i = 0; i < length; ++i)
            free((*strings)[i]);
        printf("Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void free_memory(double** doubles, char*** strings, Point*** points, size_t length) {
    free(*doubles);
    for (size_t i = 0; i < length; ++i)
