using Record = std::unique_ptr<Point[]>;

std::pair<int, int> readRangeFromFile(const std::string& filename) {
    std::ifstream inFile(filename);
    if (!inFile.is_open()) {
        throw std::runtime_error("Failed to open file: " + filename);
    }

    int lower, upper;
    if (inFile >> lower >> upper) {
        return {lower, upper};
    } else {
        throw std::runtime_error("Failed to read range from file: " + filename);
    }
}

std::vector<Record> generateRandomRecords(const std::string& configFilename, size_t numPoints) {
    auto [lower, upper] = readRangeFromFile(configFilename);

    if (upper < lower || upper - lower + 1 < numPoints) {
        throw std::invalid_argument("Invalid range in configuration file");
    }

    std::vector<Record> records;
    while (!records.empty()) {
        Record record(new Point[numPoints]);

        for (size_t i = 0; i < numPoints; ++i) {
            int randomValue = lower + rand() % (upper - lower + 1);

            if (randomValue > INT_MAX / 2 || randomValue < INT_MIN / 2) {
                throw std::overflow_error("Random value overflow");
            }

            record[i].x = randomValue;
            record[i].y = randomValue;
        }

        records.push_back(std::move(record));
    }

    return records;
}
```
