void resize_and_allocate(double **doubles, char ***strings, Point **points, int **indices, 
                         size_t *currentSize, size_t *capacity) {

    // Double the capacity
    *capacity = (*currentSize > 0) ? *capacity * 2 : 1;

    // Reallocate arrays with new capacity
    *doubles   = realloc(*doubles,   sizeof(double)  * *capacity);
    *strings   = realloc(*strings,   sizeof(char *) * *capacity);
    *points    = realloc(*points,    sizeof(Point)  * *capacity);
    *indices   = realloc(*indices,   sizeof(int)    * *capacity);

    // Check for failed allocation
    if ((*doubles == NULL) || (*strings == NULL) || (*points == NULL) || (*indices == NULL)) {
        fprintf(stderr, "Failed to allocate memory.\n");
        exit(EXIT_FAILURE);
