typedef struct {
    int integer;
    char *key;
    double real;
} Record;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static size_t allocatedMemory = 0;

Record* initializeRecords(int num, int intRangeMin, int intRangeMax, 
                          double doubleRangeMin, double doubleRangeMax) {
    assert(num > 0 && "Number of records must be positive");
    assert(intRangeMin < intRangeMax && "Invalid integer range");
    assert(doubleRangeMin < doubleRangeMax && "Invalid real number range");

    pthread_mutex_lock(&lock);
    Record *records = (Record*)malloc(num * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory\n");
        return NULL;
    }

    allocatedMemory += num * sizeof(Record);

    for (int i = 0; i < num; ++i) {
        records[i].integer = intRangeMin + rand() % (intRangeMax - intRangeMin + 1);

        // Ensure unique keys, this is a simplified example and might not 
        // work for all possible inputs as it doesn't check against collisions.
        records[i].key = malloc(20 * sizeof(char));
        sprintf(records[i].key, "Key%d", i);

        double range = doubleRangeMax - doubleRangeMin;
        double div = RAND_MAX / range;
        records[i].real = doubleRangeMin + (rand() / div);
    }

    pthread_mutex_unlock(&lock);
    return records;
}

void printAndFreeRecords(Record* records, int num) {
    assert(records && "Null pointer passed to free function");

    for (int i = 0; i < num; ++i) {
        printf("Integer: %d, Key: %s, Real number: %f\n", 
               records[i].integer, records[i].key, records[i].real);

        free(records[i].key);
    }

    pthread_mutex_lock(&lock);
    allocatedMemory -= num * sizeof(Record);
    if (allocatedMemory == 0) {
        printf("All memory freed\n");
    } else {
        printf("%zu bytes of memory still in use.\n", allocatedMemory);
    }

    free(records);
    pthread_mutex_unlock(&lock);
}
``` 
