typedef struct record {
    int value;
    char *str;
    double *dbl;
} record_t;

int initialize(size_t size, int keyRange[2], double valueRange[2], int recordRange[2], size_t strLength, int verbose) {
    long *offsets = malloc(sizeof(long) * size);
    if (offsets == NULL) {
        printf("Memory allocation for offset failed\n");
        return -1;
    }

    int *keys = malloc(sizeof(int) * size);
    if (keys == NULL) {
        printf("Memory allocation for keys failed\n");
        free(offsets);
        return -1;
    }

    double *values = malloc(sizeof(double) * size);
    if (values == NULL) {
        printf("Memory allocation for values failed\n");
        free(offsets);
        free(keys);
        return -1;
    }

    record_t *records = malloc(sizeof(record_t) * size);
    if (records == NULL) {
        printf("Memory allocation for records failed\n");
        free(offsets);
        free(keys);
        free(values);
        return -1;
    }

    srand(time(NULL));  // Seed the random number generator

    for (size_t i = 0; i < size; ++i) {
        offsets[i] = i;

        keys[i] = keyRange[0] + rand() % (keyRange[1] - keyRange[0] + 1);

        values[i] = valueRange[0] + ((double)rand() / RAND_MAX) * (valueRange[1] - valueRange[0]);

        records[i].value = recordRange[0] + rand() % (recordRange[1] - recordRange[0] + 1);
        records[i].str = malloc(sizeof(char) * (strLength + 1));  // Include space for null terminator
        if (records[i].str == NULL) {
            printf("Memory allocation for string in record failed\n");
            free(offsets);
            free(keys);
            free(values);
            for (size_t j = 0; j < i; ++j) {  // Free allocated memory for previous records
                free(records[j].str);
            }
            free(records);
            return -1;
        }
        for (size_t j = 0; j < strLength; ++j) {
            records[i].str[j] = 'A' + rand() % 36;  // Generate a random alphanumeric character
        }
        records[i].str[strLength] = '\0';  // Null-terminate the string

        records[i].dbl = malloc(sizeof(double));
        if (records[i].dbl == NULL) {
            printf("Memory allocation for double in record failed\n");
            free(offsets);
            free(keys);
            free(values);
            for (size_t j = 0; j <= i; ++j) {  // Free allocated memory for previous records and this record's string
                free(records[j].str);
                if (j < i) {
                    free(records[j].dbl);
                }
            }
            free(records);
            return -1;
        }
        *records[i].dbl = ((double)rand() / RAND_MAX) * (valueRange[1] - valueRange[0]);  // Generate a random double number within the range of values

        if (verbose) {
            printf("Offset: %ld, Key: %d, Value: %.2f, Record Value: %d, String: %s, Double: %.2f\n", offsets[i], keys[i], values[i], records[i].value, records[i].str, *records[i].dbl);
        }
    }

    // Free allocated memory when done
    free(offsets);
    free(keys);
    free(values);
    for (size_t i = 0; i < size; ++i) {
        free(records[i].str);
        free(records[i].dbl);
    }
    free(records);

    return 0;
}
```
