typedef struct DeviceConfig {
    char* IPaddress;
    int portNumber;
    char* MACaddress;
    unsigned long identifier;
} DeviceConfig;

DeviceConfig** initializeDevices(unsigned short numDevices) {
    static std::mutex mutex_lock;
    std::lock_guard<std::mutex> guard(mutex_lock);  // Ensure thread safety

    if (numDevices < 1 || numDevices > 100) {
        return nullptr;  // Invalid input parameter
    }

    DeviceConfig** devices = new DeviceConfig*[numDevices];
    std::srand(std::time(nullptr));

    try {
        for (unsigned short i = 0; i < numDevices; ++i) {
            devices[i] = new DeviceConfig();

            // Initialize members with some random values
            devices[i]->IPaddress = new char[16];  // Assuming IP addresses are in format xxx.xxx.xxx.xxx
            for (int j = 0; j < 15; ++j) {
                if(j%4 == 3){
                    devices[i]->IPaddress[j] = '.';
                } else{
                    devices[i]->IPaddress[j] = '0' + std::rand() % 9;
                }
            }

            devices[i]->portNumber = 1024 + std::rand() % (65535 - 1024);

            devices[i]->MACaddress = new char[18]; // Assuming MAC addresses are in format xx:xx:xx:xx:xx:xx
            for(int j = 0; j < 17; ++j){
                if(j%3 == 2){
                    devices[i]->MACaddress[j] = ':';
                } else {
                    devices[i]->MACaddress[j] = '0' + std::rand() % 9;
                }
            }

            // Generate a unique identifier for each device
            bool isUniqueIdGenerated = false;
            while(!isUniqueIdGenerated) {
                devices[i]->identifier = std::rand();

                isUniqueIdGenerated = true;
                for(unsigned short j = 0; j < i; ++j){
                    if(devices[j]->identifier == devices[i]->identifier){
                        isUniqueIdGenerated = false;
                        break;
                    }
                }
            }
        }
    } catch (...) {  // Exception safety
        for (unsigned short i = 0; i < numDevices; ++i) {
            delete devices[i]->IPaddress;
            delete devices[i]->MACaddress;
            delete devices[i];
        }

        delete[] devices;
        throw;  // Re-throw to let the caller know that something went wrong
    }

    return devices;
}
