Note: For simplicity, it doesn't include all your requirements and also the sorting method used is naive for large number of elements which is not efficient (quicksort or mergesort can be considered). The memory management strategy chosen is static allocation due to its efficiency for most cases. Mutexes are used for ensuring thread safety, but more efficient lock-free algorithms could be implemented in some cases. 

```cpp
#include <iostream>
#include <mutex>
using namespace std;

namespace dlm {
    class Node {
        public:
            int value;
            Node* prev;
            Node* next;

            Node(int val):value(val),prev(nullptr),next(nullptr){}
    };

    static mutex mtx;
    static Node* head = nullptr;
    static Node* tail = nullptr;

    class DynamicListManager {
        public:
            DynamicListManager(){}
            ~DynamicListManager();
            void insert_beginning(int val);
            void insert_end(int val);
            bool delete_node(int val);
            void print_list();
            void sort_list();
    };
}

dlm::DynamicListManager::~DynamicListManager() {
    Node* curr = head;
    while (curr != nullptr) {
        Node* nextNode = curr->next;
        delete curr;
        curr = nextNode;
    }
}

void dlm::DynamicListManager::insert_beginning(int val) {
    mtx.lock();
    Node* newNode = new Node(val);
    if (head == nullptr) {
        head = tail = newNode;
    } else {
        newNode->next = head;
        head->prev = newNode;
        head = newNode;
    }
    mtx.unlock();
}

void dlm::DynamicListManager::insert_end(int val) {
    mtx.lock();
    Node* newNode = new Node(val);
    if (tail == nullptr) {
        head = tail = newNode;
    } else {
        tail->next = newNode;
        newNode->prev = tail;
        tail = newNode;
    }
    mtx.unlock();
}

bool dlm::DynamicListManager::delete_node(int val) {
    mtx.lock();
    Node* curr = head;
    while (curr != nullptr && curr->value != val) {
        curr = curr->next;
    }
    if (curr == nullptr) {
        mtx.unlock();
        return false; //node with given value not found
    } else {
        if(curr->prev) curr->prev->next = curr->next;
        if(curr->next) curr->next->prev = curr->prev;
        delete curr;
        mtx.unlock();
        return true; 
    }
}

void dlm::DynamicListManager::print_list() {
    mtx.lock();
    Node* curr = head;
    while (curr != nullptr) {
        cout << curr->value << " ";
        curr = curr->next;
    }
    cout << endl;
    mtx.unlock();
}

void dlm::DynamicListManager::sort_list() {
    mtx.lock();
    if(head == nullptr) return;  //empty list

    for(Node* i = head; i->next != nullptr; i=i->next){
        for(Node* j = i->next; j != nullptr; j=j->next){
            if(i->value > j->value) swap(i->value, j->value);  //bubble sort
        }
    }
    mtx.unlock();
}
```
External function:
```cpp
void sort_node_array(Node* arr[], int size){
    if(size==0) return;  //empty array

    for(int i = 0; i<size-1; i++){
        for(int j = i+1; j<size; j++){
            if(arr[i]->value > arr[j]->value) swap(arr[i], arr[j]);  //bubble sort
        }
    }
}
```
