["Here is the C function for inserting an integer after the first occurrence of a specified integer in a doubly linked list:

```c
#include <stdlib.h>
#include <time.h>

typedef struct Node {
    int data;
    struct Node* next;
    struct Node* prev;
} Node;

Node* insertAfter(Node** head, int x, int val) {
    Node* node = (Node*) malloc(sizeof(Node));
    if(!node){
        exit(-1);  // memory allocation failed
    }

    srand(time(NULL));
    int range_min = 0;
    int range_max = 100;
    node->data = rand() % (range_max - range_min + 1) + range_min;  // Random data within the specified range

    if (*head == NULL){
        *head = node;
        return node;
    }

    Node* ptr = *head;
    while(ptr != NULL && ptr->data != x) {
        ptr = ptr->next;
    }

    if (ptr == NULL){  // Specified integer not found, insert at end of list
        Node* last = *head;
        while(last->next != NULL) {
            last = last->next;
        }

        last->next = node;
        node->prev = last;
    } else {  // Specified integer found, insert after it
        Node* temp = ptr->next;
        if (temp != NULL) {
            temp->prev = node;
        }

        ptr->next = node;
        node->prev = ptr;
        node->next = temp;
    }

    return node;
}
```

