void* initializeRecords(void *arg) {
    srand(time(NULL));

    long unsigned memoryAllocated = 0;
    FILE *logFile = fopen("log_file.txt", "w");

    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return NULL;
    }

    int num_records = ((int*)arg)[0];
    int min_value = ((int*)arg)[1];
    int max_value = ((int*)arg)[2];

    if (num_records < 1 || num_records > 1000 || min_value >= max_value) {
        fprintf(logFile, "Invalid input parameters\n");
        return NULL;
    }

    long *offsets = malloc(sizeof(long) * num_records);
    if (offsets == NULL) {
        fprintf(logFile, "Failed to allocate memory for offsets\n");
        return NULL;
    }
    memoryAllocated += sizeof(long) * num_records;

    int *keys = malloc(sizeof(int) * num_records);
    if (keys == NULL) {
        fprintf(logFile, "Failed to allocate memory for keys\n");
        free(offsets);
        return NULL;
    }
    memoryAllocated += sizeof(int) * num_records;

    Record *records = malloc(sizeof(Record) * num_records);
    if (records == NULL) {
        fprintf(logFile, "Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return NULL;
    }
    memoryAllocated += sizeof(Record) * num_records;

    int valueRange = max_value - min_value + 1;

    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < num_records; i++) {
        int value;

        do {
            value = rand() % valueRange + min_value;

            pthread_mutex_lock(&lock);
            for(int j=0;j<i;j++){
                if(keys[j] == value)
                    break; 
                else if(j==i-1)
                    keys[i] = value;
            }

            pthread_mutex_unlock(&lock);
        } while (0);

        records[i].value = value;
    }

    fprintf(logFile, "Total memory allocated: %lu bytes\n", memoryAllocated);
    fclose(logFile);

    free(offsets);
    free(keys);
    free(records);

    return NULL;
}
```
