['Here is a simple representation of such system. This code does not handle all edge cases and potential issues like overflow in arithmetic operations, ensuring thread safety while calling the function concurrently from multiple threads etc as described above. However, it provides an outline for how you could structure your program to implement this kind of system.

```cpp
#include <cstdlib>
#include <iostream>
#include <mutex>
#include <memory>

namespace NodeManager {
    struct Node;

    // Forward declaration for unique_ptr to Node
    using NodePtr = std::unique_ptr<Node>;

    // The node structure
    struct Node {
        static int nextId;
        static std::mutex idLock; 
        int id;
        int value;
        Node* next;

        Node(int val = 0) : value(val), next(nullptr) {
            std::lock_guard<std::mutex> lock(idLock);
            id = ++nextId;
        }

        ~Node() { delete next; }
    };

    // Initialize static member variables
    int Node::nextId = 0;
    std::mutex Node::idLock; 
}

// Define a C function that allocates memory for and initializes an array of `Node` structures
extern "C" void* initializeNodes(int num) {
    static constexpr size_t MAX_NODES = 1000; // Assume this as the max possible nodes we can have.
    static NodeManager::NodePtr pool[MAX_NODES]; 
    static std::mutex nodeLock; 

    if(num < 1 || num > MAX_NODES) {
        std::cerr << "Invalid number of nodes: " << num << std::endl;
        return nullptr;
    }

    // Protect shared resource with a mutex
    const std::lock_guard<std::mutex> lock(nodeLock);

    NodeManager::NodePtr* nodePool = new NodeManager::NodePtr[num]; 

    for (int i = 0; i < num; ++i) {
        try {
            // Create a new node and store it in the pool array.
            nodePool[i] = std::make_unique<NodeManager::Node>(i);
        } catch(const std::bad_alloc& e) {
            delete[] nodePool; 
            throw; 
        }
    }

    return static_cast<void*>(nodePool);
}
```
