#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long* offset;
    int* key;
} RecordArray;

int allocateMemory(RecordArray* array, size_t records) {

    // Allocate memory for the arrays
    array->offset = (long*) malloc(records * sizeof(long));
    if (array->offset == NULL) {
        printf("Failed to allocate memory for offset.\n");
        return -1;
    }

    array->key = (int*) malloc(records * sizeof(int));
    if (array->key == NULL) {
        free(array->offset); // Clean up in case of failure
        printf("Failed to allocate memory for key.\n");
        return -1;
    }

    return 0; // Success
}

void setRandomValues(int* array, size_t records, int min, int max) {
    srand((unsigned int) time(NULL)); // Seed the random number generator
    for (size_t i = 0; i < records; ++i) {
        array[i] = rand() % (max - min + 1) + min; // Generate a random number in the range [min, max]
    }
}

void freeMemory(RecordArray* array) {
    if (array->offset != NULL) {
        free(array->offset);
        array->offset = NULL;
    }
    if (array->key != NULL) {
        free(array->key);
        array->key = NULL;
    }
}

int main() {
    RecordArray array; // Struct to hold the two arrays

