    for (; i < 17; ++i){
        if ((i+1) % 3 == 0){
            sprintf(str + i, ":");
            ++i;
        } else {
            sprintf(str + i, "%2.2X", rand()%256);
            i += 2;
        }
    }
}

void addNIC(char* macAddress, char* ipAddress) {
