    Node_t *newNode = (Node_t *)malloc(sizeof(Node_t));
    if (!newNode){
        printf("Memory allocation failed!\n");
        exit(-1);
    }

    newNode->nic = (NIC_t*) malloc(sizeof(NIC_t));
    if(!newNode->nic) {
