int compress_log(LogEntry *entry) {
    Bytef buffer[128];  // Adjust this based on your average message size.
    uLongf compressedSize = sizeof(buffer);

    int result = compress(buffer, &compressedSize, (Bytef*) entry->message, strlen(entry->message));
    if (result != Z_OK) {
        fprintf(stderr, "Error compressing log message: %d\n", result);
        return EXIT_FAILURE;
    }

    free(entry->message);  // Free the original uncompressed message.
    entry->message = malloc(compressedSize);
    if (entry->message == NULL) {
        perror("Error allocating memory for compressed log message.");
        return EXIT_FAILURE;
    }

    memcpy(entry->message, buffer, compressedSize);  // Copy the compressed data.
    return EXIT_SUCCESS;
}
