int* readInput(size_t *len) {
    size_t capacity = 2;
    int *array = (int*)malloc(capacity * sizeof(int));

    if (!array) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    printf("Enter positive integers, enter 0 to stop:\n");

    while (1) {
        int num;

        if (scanf("%d", &num) != 1 || num < 0) {
            fprintf(stderr, "Invalid input!\n");
            exit(EXIT_FAILURE);
        } else if (num == 0) {
            break;
        }

        // Dynamically resize the array when necessary
        if (*len == capacity) {
            capacity *= 2;
            int *temp = realloc(array, capacity * sizeof(int));

            if (!temp) {
                perror("Memory reallocation failed");
                free(array);
                exit(EXIT_FAILURE);
            } else {
                array = temp;
            }
        }

        array[(*len)++] = num;
    }

    return array;
}

int findMaximum(const int *array, size_t len) {
    if (len == 0 || !array) {
        fprintf(stderr, "Invalid input!\n");
        exit(EXIT_FAILURE);
    }

    int max = array[0];

    for (size_t i = 1; i < len; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }

    return max;
}

void freeArray(int *array) {
    free(array);
}

void task() {
    size_t len = 0;
    int* numbers = readInput(&len);

    printf("Maximum value: %d\n", findMaximum(numbers, len));

    freeArray(numbers);
}
