#include <sys/stat.h>
#include <fcntl.h>

typedef struct {
    int value;
} record;

int allocate_and_initialize(long **offsets, int **keys, record ***records, int num_records, int min_value, int max_value) 
{
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    if (max_value < min_value) {
        FILE *file = fopen("logfile.txt", "a");
        if (file != NULL) 
        {
            fprintf(file, "Error: max value is less than min value\n");
            fclose(file);
        }

        return -1; // Empty range error code.
    }

    pthread_mutex_lock(&mutex);

    *offsets = memalign(sizeof(long), num_records * sizeof(long));
    *keys = memalign(sizeof(int), num_records * sizeof(int));
    *records = malloc(num_records * sizeof(record*));

    if (*offsets == NULL || *keys == NULL || *records == NULL) 
    {
        FILE *file = fopen("logfile.txt", "a");
        if (file != NULL) 
        {
            fprintf(file, "Error: memory allocation failed\n");
            fclose(file);
        }

        return -2; // Memory allocation error code.
    }

    srand(time(NULL));
    for (int i = 0; i < num_records; i++) 
    {
        (*records)[i] = malloc(sizeof(record));

        if ((*records)[i] == NULL) 
        {
