ModuleList* load_configuration_file(const char *file_path) {
    FILE *file = fopen(file_path, "r");
    if (file == NULL) {
        return NULL;
    }

    ModuleList *module_list = malloc(sizeof(ModuleList));
    module_list->count = 0;
    module_list->modules = NULL;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        Module *module = malloc(sizeof(Module));

        const char s[2] = ",";
        char *token;

        token = strtok(line, s);
        module->module_id = atoi(token);

        // Assume APIs and metrics are separated by commas
        int api_count = 0;
        while ((token = strtok(NULL, s)) != NULL) {
            if (api_count == 0) {
                module->apis = malloc(sizeof(ApiFunction));
            } else {
                module->apis = realloc(module->apis, sizeof(ApiFunction) * (api_count + 1));
            }

            module->apis[api_count].api_id = atoi(token);
            api_count++;
        }

        int metric_count = 0;
        while ((token = strtok(NULL, s)) != NULL) {
            if (metric_count == 0) {
                module->metrics = malloc(sizeof(PerformanceMetric));
            } else {
                module->metrics = realloc(module->metrics, sizeof(PerformanceMetric) * (metric_count + 1));
            }

            // Assuming the metric_id is at even indexes and execution_time is at odd indexes in the line
            if (metric_count % 2 == 0) {
                module->metrics[metric_count/2].metric_id = atoi(token);
            } else {
                module->metrics[(metric_count - 1)/2].execution_time = atoi(token);
            }

            metric_count++;
        }

        if (module_list->count == 0) {
            module_list->modules = malloc(sizeof(Module));
        } else {
            module_list->modules = realloc(module_list->modules, sizeof(Module) * (module_list->count + 1));
        }

        module_list->modules[module_list->count] = *module;
        module_list->count++;
    }

    fclose(file);
    return module_list;
}
```

