response:
['Here is a sample implementation in C using POSIX threads and `mmap` for proper memory alignment. Please note that this example does not cover logging to an external file, but it should be straightforward to add that functionality using standard library functions like `fopen` and `fprintf`:

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/mman.h>

typedef struct {
    int value;
} record;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* allocateAndInitialize(long** offsets, int** keys, record*** records, size_t numRecords) {
    if (numRecords == 0) {
        return NULL; // empty range error
    }

    pthread_mutex_lock(&lock);

    *offsets = mmap(NULL, numRecords * sizeof(long), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (*offsets == MAP_FAILED) {
        pthread_mutex_unlock(&lock);
        return NULL; // offset allocation failure
    }

    *keys = mmap(NULL, numRecords * sizeof(int), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (*keys == MAP_FAILED) {
        pthread_mutex_unlock(&lock);
        munmap(*offsets, numRecords * sizeof(long)); // clean up offset allocation
        return NULL; // keys allocation failure
    }

    *records = mmap(NULL, numRecords * sizeof(record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (*records == MAP_FAILED) {
        pthread_mutex_unlock(&lock);
        munmap(*offsets, numRecords * sizeof(long)); // clean up offset allocation
        munmap(*keys, numRecords * sizeof(int)); // clean up keys allocation
        return NULL; // records allocation failure
    }

    pthread_mutex_unlock(&lock);

    srand((unsigned int) time(NULL));
    for (size_t i = 0; i < numRecords; ++i) {
        (*records)[i].value = rand(); // initialize record values
    }

    return NULL;
}
```
The `mmap` function is used to allocate memory which ensures alignment for better performance. Note that this code uses POSIX threads (pthreads) and requires a Unix-like operating system, as Windows does not support the `MAP_ANONYMOUS` flag in `mmap`.

Please note: In production code you should also check the return value of all function calls for errors. This code does not include error checking after each call to malloc or srand and simply assumes that these operations will succeed. 

In a real-world scenario, proper error handling would be added using methods like errno variable, perror()/strerror(), return values, etc. Also, for better logging experience use dedicated libraries such as log4cxx, log4cpp or Boost.Log instead of printing directly to a file.
']

