    MeasurementReport measurementReport;
    ReportingConfiguration reportingConfig;
} UEContext;

void *safeMalloc(size_t size) {
    void *ptr = malloc(size);

    if (ptr == NULL) {
        printf("Memory allocation failed. Exiting program...\n");
        exit(EXIT_FAILURE);
    }

    return ptr;
}

UEContext* createAndPopulateUEContexts(int numOfUEs, int minId, int maxId) {
    if (numOfUEs < 1 || minId >= maxId) {
        printf("Invalid input parameters. Exiting program...\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    UEContext* contexts = safeMalloc(sizeof(UEContext) * numOfUEs);
    int uniqueIds[maxId - minId + 1];  // Track used IDs
    memset(uniqueIds, 0, sizeof(int)*(maxId-minId+1));

    for (int i = 0; i < numOfUEs; i++) {
        int ueId;

        do {
            ueId = rand() % (maxId - minId + 1) + minId; // Generate a random ID within the range
        } while(uniqueIds[ueId-minId] == 1);  // Check if ID is already in use

        uniqueIds[ueId-minId] = 1;

        contexts[i].ueId = ueId;
        contexts[i].measurementReport.signalStrength = rand() % 50 + 60; // Example signal strength between 60 and 109 dBm
        contexts[i].measurementReport.latency = rand() % 200 + 30; // Example latency in ms
        contexts[i].measurementReport.packetLoss = (float)(rand() % 10) / 100.f; // Example packet loss percentage
        contexts[i].reportingConfig.reportingInterval = 60; // Report every minute
    }

    printf("Total memory allocated: %ld bytes\n", sizeof(UEContext) * numOfUEs);

    return contexts;
}
``` 

The function `createAndPopulateUEContexts` creates an array of UE Context structures and populates them with random values. It ensures that the IDs are unique by storing used IDs in a separate array. This solution also handles memory allocation failures by calling `exit(EXIT_FAILURE)` when dynamic memory allocation fails, which will terminate the program with an error code.
']

