```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct data_s {
    int value;
    char *string;
    struct data_s *next;
} data_t;

typedef struct node_s {
    int value;
    data_t *data_head;
} node_t;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
data_t* head = NULL;
int memory_limit = 0;
int current_memory = 0;
int concurrency_limit = 1; // Default: No threading.
pthread_mutex_t concurrency_lock = PTHREAD_MUTEX_INITIALIZER;
int threads_using = 0;

void *allocate(size_t size) {
    pthread_mutex_lock(&concurrency_lock);
    while (threads_using >= concurrency_limit) {
        // Wait for other thread to finish.
    }
    threads_using++;
    pthread_mutex_unlock(&concurrency_lock);

    if(current_memory + size > memory_limit){
        printf("Memory limit exceeded!\n");
        exit(EXIT_FAILURE); // Or handle error in other way.
    }

    void *ptr = malloc(size);
    pthread_mutex_lock(&lock);
    current_memory += size;
    data_t* new_data = (data_t*)malloc(sizeof(data_t));
    new_data->string = (char *)ptr;
    new_data->next = head;
    head = new_data;

    pthread_mutex_unlock(&lock);
    threads_using--;
    return ptr;
}

void initialize(node_t* nodes, int size, int node_range, int data_range) {
    srand((unsigned int)time(NULL));

    for (int i = 0; i < size; ++i) {
        nodes[i].value = rand() % node_range;

        // Allocate memory for 'data' structure.
        data_t *new_data = allocate(sizeof(data_t));
        if (!new_data) {
            printf("Failed to allocate memory for data[%d]!\n", i);
            exit(EXIT_FAILURE); // Or handle error in other way.
        }

        new_data->value = rand() % data_range;
        char *string = (char *)allocate(11); 
        if (!string) {
            printf("Failed to allocate memory for string[%d]!\n", i);
            exit(EXIT_FAILURE); // Or handle error in other way.
        }

        strncpy(string, "random_str", 10); // For simplicity, set a constant string.
        new_data->next = NULL;
    }
}
