```c
#include <stdlib.h>
#include <sqlite3.h>
#include <time.h>
#include <math.h>

typedef struct point {
    double x;
    double y;
} Point;

void test_module() {
    // Allocate memory for arrays
    int* indices = malloc(sizeof(int) * 10);
    double* values = calloc(10, sizeof(double));
    Point* points = malloc(sizeof(Point) * 10);

    srand(time(NULL)); // Seed the random number generator

    sqlite3* db;
    char* err_msg = 0;

    int rc = sqlite3_open("test.db", &db);

    if (rc != SQLITE_OK) {

        fprintf(stderr, "Cannot open database: %s\n", 
                sqlite3_errmsg(db));
        sqlite3_close(db);

        return;
    }

    char* create_table = "CREATE TABLE IF NOT EXISTS points (x DOUBLE, y DOUBLE);";

    rc = sqlite3_exec(db, create_table, 0, 0, &err_msg);

    if (rc != SQLITE_OK ){

        fprintf(stderr, "Failed to create table\n");
        fprintf(stderr, "SQL error: %s\n", err_msg);

        sqlite3_free(err_msg);
        sqlite3_close(db);

        return;
    }

    // Initialize struct point's coordinates to random values within specified ranges.
    for (int i = 0; i < 10; ++i) {
        points[i].x = ((double)rand() / (double)(RAND_MAX)) * 10.0;  
        points[i].y = ((double)rand() / (double)(RAND_MAX)) * 10.0; 

        char insert[256];
        sprintf(insert, "INSERT INTO points VALUES (%lf, %lf);", points[i].x, points[i].y);

        rc = sqlite3_exec(db, insert, 0, 0, &err_msg);

        if (rc != SQLITE_OK ){

            fprintf(stderr, "Failed to insert data\n");
            fprintf(stderr, "SQL error: %s\n", err_msg);

            sqlite3_free(err_msg);
        }
    }

    // Free allocated memory
    free(indices);
    free(values);
    free(points);

    sqlite3_close(db); 
}
```

