```cpp
#include <iostream>
#include <random>
#include <chrono>
#include <thread>
#include <mutex>
#include <unordered_map>
#include <memory>

class Node {
public:
    int value;
    std::shared_ptr<Node> next;
    unsigned long uniqueID;
};

namespace mySpace{
std::mutex mtx;  // mutex for critical section
unsigned long uniqueID = 0;
std::unordered_map<unsigned long, Node*> mapNodes;
}

class MemoryManager {
public:
    static std::shared_ptr<Node> allocate(int value) {
        mySpace::mtx.lock();
        auto node = std::make_shared<Node>();
        node->value = value;
        try {
            node->uniqueID = ++mySpace::uniqueID;
            if (mySpace::mapNodes.find(node->uniqueID) != mySpace::mapNodes.end()) {
                throw std::runtime_error("Duplicate unique ID!");
            }
            mySpace::mapNodes[node->uniqueID] = node.get();
        } catch (std::exception& e){
            std::cout << "Exception: " << e.what() << "\n";
        }
        mySpace::mtx.unlock();
        return node;
    }

    static void deallocate(unsigned long id) {
        mySpace::mtx.lock();
        if (mySpace::mapNodes[id] != nullptr){
            delete mySpace::mapNodes[id];
            mySpace::mapNodes.erase(id);
        }
        mySpace::mtx.unlock();
    }
};

void logEntryGenerator(int numOfEntries) {
    std::random_device rd;
