int debug_flag = 0;
void (*callback)(long*, int*, Record*, char***);
char** externalSource = NULL;

void function(size_t size, int keyRangeStart, int keyRangeEnd, 
              int recordRangeStart, int recordRangeEnd, int debugFlag, 
              void* (*allocator)(), void (*callback)(long*, int*, Record*, char***)) {

    if (size == 0 || keyRangeEnd <= keyRangeStart || 
        recordRangeEnd <= recordRangeStart || allocator == NULL || 
        callback == NULL) {

        printf("Invalid input parameters\n");
        return;
    }

    debug_flag = debugFlag;

    long* offsets = (long*)allocator(size * sizeof(long));
    int* keys = (int*)allocator(size * sizeof(int));
    Record* records = (Record*)allocator(size * sizeof(Record));
    char** strings = (char**)allocator(size * sizeof(char*));

    for (size_t i = 0; i < size; ++i) {
        offsets[i] = i;

        keys[i] = keyRangeStart + rand() % ((keyRangeEnd - keyRangeStart) + 1);

        records[i].value = recordRangeStart + rand() % ((recordRangeEnd - recordRangeStart) + 1);
        strings[i] = (char*)allocator(10 * sizeof(char));
        for (int j = 0; j < 9; ++j) {
            strings[i][j] = 'a' + rand() % 26;
        }
        strings[i][9] = '\0';

        if (debug_flag == 1) {
            printf("Initialized offset: %ld, key: %d, record value: %d, string: %s\n", 
                   offsets[i], keys[i], records[i].value, strings[i]);
        }
    }

    if (callback != NULL) {
        callback(offsets, keys, records, &strings);
    }

    for (size_t i = 0; i < size; ++i) {
        free(allocator(strings[i]));
    }
    free(allocator(strings));
    free(allocator(records));
    free(allocator(keys));
    free(allocator(offsets));
}
```
