['Here is an example solution implemented in C, which uses mutexes from pthreads library to ensure thread-safety. Please note that this function only takes 'long' and 'int' as input parameters, but the 'record' structure could be any complex data type you want to use. 

```c
#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; 

long totalRecords = 0;
int randSeed = 123456789; // default seed value for reproducibility.

void* allocateMemory(const long offsetSize, const int keySize, const int recordSize) {
    pthread_mutex_lock(&mutex);

    if (offsetSize <= 0 || keySize <= 0 || recordSize <= 0) {
        printf("Invalid input parameters. Parameters should be greater than 0.\n");
        exit(EXIT_FAILURE);
    }

    srand(randSeed); // set custom seed for reproducibility.

    long* offsets = (long*) malloc(sizeof(long) * offsetSize);
    if(offsets == NULL){
        printf("Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    int* keys = (int*) malloc(sizeof(int) * keySize);
    if(keys == NULL){
        printf("Memory allocation failed.\n");
        free(offsets); // Free the memory allocated for offsets before exiting.
        exit(EXIT_FAILURE);
    }

    record* records = (record*) malloc(sizeof(record) * recordSize);
    if(records == NULL){
        printf("Memory allocation failed.\n");
        free(offsets); // Free the memory allocated for offsets before exiting.
        free(keys); // Free the memory allocated for keys before exiting.
        exit(EXIT_FAILURE);
    }

    // initialize arrays and records
    for (long i = 0; i < offsetSize; ++i) {
        offsets[i] = rand();  // some random value for the offset array.
    }

    for (int i = 0; i < keySize; ++i) {
        keys[i] = rand(); // some random value for the key array.
    }

    for (int i = 0; i < recordSize; ++i) {
        records[i].value = rand();  // some random value for the record struct.
    }

    totalRecords += recordSize; // update total records created.

    pthread_mutex_unlock(&mutex);

    return (void*)records;
}
```
This function uses mutex locks to ensure thread safety, dynamic memory allocation techniques for arrays and a custom seed value for random number generation for reproducibility. It handles errors in memory allocation by exiting the program gracefully with an appropriate error message. 

Please note that this is just one of many ways you could implement such functionality. The actual solution would depend on your specific requirements, constraints, and programming environment.
']

