#define MAX_MEMORY 1024*1024 // 1MB in bytes

typedef struct {
    int value;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record **records;
    size_t allocatedSize;
    size_t numRecords;
} Arrays;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; 
size_t totalCreated = 0;

Arrays *initialize(int seed, size_t initialSize) {
    srand(seed); // Set custom seed

    Arrays *arrays = (Arrays*)malloc(sizeof(Arrays));
    arrays->offsets = (long*)calloc(initialSize, sizeof(long));
    arrays->keys = (int*)calloc(initialSize, sizeof(int));
    arrays->records = (Record**)calloc(initialSize, sizeof(Record*));

    if (!arrays->offsets || !arrays->keys || !arrays->records) {
        printf("Memory allocation failure!\n");
        exit(-1); // Handle memory error gracefully
    }

    arrays->allocatedSize = initialSize;
    arrays->numRecords = 0;

    return arrays;
}

void createRecord(Arrays *arrays, int externalData) {
    pthread_mutex_lock(&lock); // Lock for thread safety

    if (totalCreated >= MAX_MEMORY) {
        printf("Memory limit exceeded!\n");
        exit(-1);
    }

    // Dynamically resize arrays if they are full
    while(arrays->numRecords >= arrays->allocatedSize) {
        size_t newSize = arrays->allocatedSize * 2;

        long *newOffsets = (long*)realloc(arrays->offsets, newSize * sizeof(long));
        int *newKeys = (int*)realloc(arrays->keys, newSize * sizeof(int));
        Record **newRecords = (Record**)realloc(arrays->records, newSize * sizeof(Record*));

        if (!newOffsets || !newKeys || !newRecords) {
            printf("Memory allocation failure while resizing arrays!\n");
            exit(-1); // Handle memory error gracefully
        }

        arrays->offsets = newOffsets;
        arrays->keys = newKeys;
        arrays->records = newRecords;
        arrays->allocatedSize = newSize;
    }

    Record *record = (Record*)malloc(sizeof(Record));
    record->value = externalData ? readFromExternal() : rand(); // Use random value if no external data is provided

    arrays->offsets[arrays->numRecords] = 0;
    arrays->keys[arrays->numRecords] = rand();
    arrays->records[arrays->numRecords] = record;
    totalCreated += sizeof(Record);
    ++(arrays->numRecords);

    pthread_mutex_unlock(&lock); // Unlock after modification
}

void freeArrays(Arrays *arrays) {
    for (size_t i = 0; i < arrays->numRecords; ++i) {
        free(arrays->records[i]);
    }

    free(arrays->offsets);
    free(arrays->keys);
    free(arrays->records);
    free(arrays);
}
