    char* TrafficFlowTemplate;
    int PriorityLevel;
    int ARP;
    enum SessionState {Active, Inactive} state;
    time_t lastUpdatedTime;
} LTE_UESessionInfo;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
LTE_UESessionInfo *sessions = NULL;
char* directoryPath;

void createDirectory() {
    char* dirName = "MyDir";
    char buf[100];
    sprintf(buf, "%s/%s", getenv("HOME"), dirName); 
    if (mkdir(buf, 0755) == -1 && errno != EEXIST) {
        perror("Could not create directory");
        return;
    }
    sprintf(buf, "DIRECTORY_PATH=%s", buf);
    putenv(buf);
}

void manageSessions() {
    if (getenv("DIRECTORY_PATH") == NULL) {
        pthread_mutex_lock(&lock);
        if (directoryPath == NULL) createDirectory();
        pthread_mutex_unlock(&lock);
    }

    sessions = malloc(sizeof(LTE_UESessionInfo) * 100000);
    if (!sessions) {
        perror("Could not allocate memory");
        return;
    }
}

void* simulateNetworkEvents(void* arg) {
    int index = *((int*)arg);
    while (1) {
        pthread_mutex_lock(&lock);
        sessions[index].state = rand() % 2 == 0 ? Active : Inactive;
        sessions[index].lastUpdatedTime = time(NULL);
        pthread_mutex_unlock(&lock);
        sleep(10);
    }
}

int main() {
    manageSessions();

    if (sessions == NULL) return -1;

    pthread_t threads[100000];
    int indexes[100000];
    for(int i = 0; i < 100000; i++) {
        indexes[i] = i;
        if (pthread_create(&threads[i], NULL, simulateNetworkEvents, &indexes[i]) != 0){
            perror("Failed to create thread");
            return -1;
        }
    }

    for(int i = 0; i < 100000; i++) {
        if (pthread_join(threads[i], NULL) != 0){
            perror("Failed to join thread");
            return -1;
        }
    }

    free(sessions);
    pthread_mutex_destroy(&lock);

    return 0;
}
```
Please keep in mind, this is an overly simplified demonstration and a lot of things are missing (for instance, actual session management, logging etc.). Furthermore, managing sessions with threads without using any sort of thread pool library can be resource intensive if you have to handle a very large number of sessions. You might want to consider something more efficient like libuv for example or switch to a language with better support for concurrency, such as Go.
