['Here is a possible implementation of your request:

```c
#include <stdlib.h>
#include <string.h>

typedef struct {
    int value;
} record;

int log_error(const char *message);
int log_warning(const char *message);

static void free_resources(long *offsets, int *keys, record **records) {
    if (offsets != NULL) {
        free(offsets);
    }

    if (keys != NULL) {
        free(keys);
    }

    if (records != NULL && *records != NULL) {
        free(*records);
        *records = NULL;
    }
}

int init_records(long *offsets, int *keys, record **records, size_t num_elements, int min_value, int max_value) {
    if (num_elements == 0 || min_value > max_value) {
        log_error("Invalid arguments");
        return -1;
    }

    offsets = malloc(sizeof(*offsets) * num_elements);
    keys = malloc(sizeof(*keys) * num_elements);
    record *tmp_records = malloc(sizeof(*tmp_records) * num_elements);

    if (offsets == NULL || keys == NULL || tmp_records == NULL) {
        log_error("Failed to allocate memory");
        free_resources(offsets, keys, records);
        return -1;
    }

    memset(keys, 0, sizeof(*keys) * num_elements);
    memset(tmp_records, 0, sizeof(*tmp_records) * num_elements);

    for (size_t i = 0; i < num_elements; ++i) {
        keys[i] = min_value + rand() % ((max_value + 1) - min_value);
        tmp_records[i].value = keys[i];
    }

    *records = tmp_records;

    return 0;
}
```

This code first checks if the input arguments are valid. If they're not, it logs an error and returns -1 to indicate failure. It then attempts to allocate memory for each array. If any of these allocations fail, it logs another error, frees all previously allocated memory (if any), and returns -1 again. If successful, it fills the 'keys' array with random values in the range [min_value, max_value], and sets up the 'record' array accordingly. Finally, it assigns the record array to the output parameter and returns 0 to indicate success.
