["Here's a basic code block demonstrating how you could approach this task using C programming language:

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
} Record;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int initArrays(long **offsets, long *numOffsets, int **keys, int *numKeys, 
               Record ***records, int *numRecords) {
    if (*numOffsets < 0 || *numKeys < 0 || *numRecords < 0) return -1; // Invalid parameters.

    pthread_mutex_lock(&mutex); // Locking for thread safety.

    *offsets = malloc(sizeof(long) * (*numOffsets)); 
    if (*offsets == NULL) { 
        pthread_mutex_unlock(&mutex);
        return -2; // Allocation failed.
    }
    *keys = malloc(sizeof(int) * (*numKeys));
    if (*keys == NULL) {
        free(*offsets);
        pthread_mutex_unlock(&mutex);
        return -2; // Allocation failed.
    }

    // Allocating memory for records and validating the allocation.
    *records = malloc(sizeof(Record *) * (*numRecords)); 
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        pthread_mutex_unlock(&mutex);
        return -2; // Allocation failed.
    }

    for (int i = 0; i < *numRecords; ++i) { 
        (*records)[i] = malloc(sizeof(Record));
        if ((*records)[i] == NULL) { 
            // Free already allocated records.
            for (--i; i >= 0; --i) free((*records)[i]);
            free(*offsets);
            free(*keys);
            pthread_mutex_unlock(&mutex);
            return -2; // Allocation failed.
        }
    }

    pthread_mutex_unlock(&mutex); 
    return 0; // Successfully allocated memory.
}
```
In the above code, `initArrays` is a function that takes the size of each array (offsets, keys and records) as parameters. It allocates memory for the arrays using `malloc()` with a check to handle allocation failure. The arrays are locked with a mutex while being initialized to ensure thread safety, preventing potential race conditions from simultaneous access or modification. 

