    // Allocate memory for the arrays
    long* offsets = malloc(sizeof(long)*size);
    int* keys = malloc(sizeof(int)*size);
    double* precisions = malloc(sizeof(double)*size);
    Record* records = malloc(sizeof(Record)*size);

    // Check if allocation was successful
    if (!offsets || !keys || !precisions || !records) {
        free(offsets);
        free(keys);
        free(precisions);
        free(records);
        return NULL;
    }

    srand(seed); // Seed the random number generator

    for (size_t i = 0; i < size; ++i) {
        records[i].value = rand(); // Initialize record fields
        records[i].offsets = offsets;
        records[i].keys = keys;
        records[i].precisions = precisions;
    }

    return records;
}

void freeRecords(Record* records) {
    if (records) {
        // Free individual arrays
        free(records->offsets);
        free(records->keys);
        free(records->precisions);

        // Free record array
        free(records);
    }
}
```

