// Define a structure for network interface
typedef struct {
    int id;
    char ip[16];
    char subnet_mask[16];
    char gateway[16];
} NetworkInterface;

NetworkInterface *readInterfaces(const char* filename, int num) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Failed to open file.\n");
        return NULL;
    }

    // Dynamically allocate array of interfaces
    NetworkInterface *interfaces = malloc(num * sizeof(NetworkInterface));
    if (interfaces == NULL) {
        printf("Memory allocation failed.\n");
        fclose(file);
        return NULL;
    }

    // Populate the interface structures with data from file
    for (int i = 0; i < num; i++) {
        interfaces[i].id = i+1;  // Assuming IDs are sequential and start from 1.
        fscanf(file, "%s %s %s", interfaces[i].ip, interfaces[i].subnet_mask, interfaces[i].gateway);
    }

    fclose(file);
    return interfaces;
