int findLargest(int *arr, int n) {
    if (n <= 0 || arr == NULL) return -1; // Invalid input

    int maxVal = arr[0];
    for(int i = 1; i < n; i++) 
        if(maxVal < arr[i])
            maxVal = arr[i];

    return maxVal;
}

void initPDU_T(NFAPI_CRC_INDICATION_PDU_T* pdu, int rx, int rnti, unsigned crc) {
    if (pdu == NULL || rx < 0 || rnti < 0 || crc > (1<<23)) 
        return; // Invalid input

    pthread_mutex_lock(&lock);

    pdu->RX_UE_INFORMATION_TAG = rx;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG = crc;

    pthread_mutex_unlock(&lock);
}

void manageMemory(int N) {
