['Your task requires a fair amount of C programming and understanding of data structures. Here's how you might go about it:

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    double value;
    time_t timestamp;
} data_point;

typedef struct {
    double *floats;
    int *keys;
    data_point *data_points;
    pthread_mutex_t mutex;
} array_manager;

array_manager* create_array_manager(int size, double min, double max) {
    srand((unsigned int) time(NULL));

    array_manager *am = (array_manager*) malloc(sizeof(array_manager));
    if (!am) return NULL;

    am->floats = (double*) malloc(size * sizeof(double));
    am->keys = (int*) calloc(size, sizeof(int));
    am->data_points = (data_point*) malloc(size * sizeof(data_point));

    if (!am->floats || !am->keys || !am->data_points) {
        free(am->floats);
        free(am->keys);
        free(am->data_points);
        free(am);

        return NULL;
    }

    pthread_mutex_init(&(am->mutex), NULL);

    int i;
    for (i = 0; i < size; ++i) {
        am->keys[i] = rand();

        double value = min + ((double)rand() / RAND_MAX) * (max - min);  // Uniform distribution.
        am->floats[i] = value;

        am->data_points[i].value = value;
        am->data_points[i].timestamp = time(NULL);
    }

    return am;
}

void print_array_manager(const array_manager *am, int size) {
    pthread_mutex_lock(&(am->mutex));

    for (int i = 0; i < size; ++i) {
        printf("Key: %d, Float: %f, Timestamp: %ld\n", 
               am->keys[i], am->floats[i], am->data_points[i].timestamp);
    }

    pthread_mutex_unlock(&(am->mutex));
}

void destroy_array_manager(array_manager *am) {
    if (!am) return;

    free(am->floats);
    free(am->keys);
    free(am->data_points);
    pthread_mutex_destroy(&(am->mutex));
    free(am);
}
```
The `create_array_manager` function takes the size of the arrays and a range for random number generation as parameters. It allocates memory for the three types of arrays, initializes them with random numbers and timestamps, and returns a pointer to an array manager struct that holds these arrays. If memory allocation fails for any reason, it frees all previously allocated memory and returns NULL.

The `print_array_manager` function locks the mutex before accessing the data points, prints out their contents, and then unlocks the mutex. This prevents other threads from modifying the data while printing is in progress.

The `destroy_array_manager` function frees all memory that was allocated for an array manager struct, including its contained arrays. It also destroys the mutex to clean up resources before the program ends.
