response:
['Here is a modified version of your code that includes error handling, thread safety using pthread mutexes, and optimizations to minimize allocations:

```c
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <errno.h>
#include <float.h>
#include <time.h>
#define MAX_RANGE 100.0f

typedef struct point {
    float x;
    float y;
} Point;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

float* generate_points(int num_points, int** keys, Point** points) {
    if (num_points <= 0 || errno == ERANGE) {
        return NULL; // Invalid number of points
    }

    srand((unsigned int)time(NULL)); // Initialize random seed

    float* floats = calloc(num_points, sizeof(float));
    *points = calloc(num_points, sizeof(Point));
    *keys = calloc(num_points, sizeof(int));

    if (floats == NULL || *points == NULL || *keys == NULL) {
        // Memory allocation failed, free previously allocated memory and return error code
        perror("Memory allocation failed");

        free(floats);
        free(*points);
        free(*keys);

        return NULL;
    }

    float range = MAX_RANGE / RAND_MAX;

    // Generate random values, thread safe using mutex
    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_points; i++) {
        floats[i] = rand() * range;
        (*points)[i].x = rand() * range;
        (*points)[i].y = rand() * range;
        (*keys)[i] = i;
    }
    pthread_mutex_unlock(&lock);

    return floats;
}
```
The function now checks if the number of points is valid and handles errors related to invalid input. It also initializes a random seed using time for better randomness, and optimizes memory usage by initializing allocated memory with zeros instead of default values. The thread-safety is implemented through pthread mutexes, which only allow one thread at a time to execute the critical section where new points are generated.
']

