} Timestamp;

typedef struct record {
    int value;
    long* offsets;
    int* keys;
    double* doubles;
    char** strings;
    Timestamp** timestamps;
} Record;

// function for generating random numbers in range (inclusive)
int rand_range(int min, int max) {
    return rand() % (max - min + 1) + min;
}

Record* create_records(long* offsets, int offset_count, int* keys, int key_count, 
                       double* doubles, int double_count, char** strings, int string_count, 
                       Timestamp** timestamps, int timestamp_count) {
    if (offset_count != key_count || key_count != double_count || 
        double_count != string_count || string_count != timestamp_count) {
        return NULL;
    }

    Record* records = malloc(sizeof(Record) * offset_count);
    if (records == NULL) return NULL;

    for (int i = 0; i < offset_count; ++i) {
        records[i].value = rand_range(-100, 100);
        records[i].offsets = &offsets[i];
        records[i].keys = &keys[i];
        records[i].doubles = &doubles[i];
        records[i].strings = &strings[i];
        records[i].timestamps = &timestamps[i];
    }

    return records;
}
```
