['This task requires a good understanding of C programming, especially in terms of system calls and low-level memory management. Here is a simple implementation to get you started:

```c
#include <stdio.h>
#include <dirent.h>
#include <sys/stat.h>
#include <time.h>
#include <string.h>
#include <pthread.h>
#include <assert.h>
#include <unistd.h>

typedef struct {
    char* name;
    long size;
    time_t lastModifiedTime;
} file_info;

file_info* allocate_memory(int numOfRecords) {
    assert(numOfRecords > 0);  // Validating input parameters.

    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;  // Mutex to ensure thread-safety.
    pthread_mutex_lock(&mutex);

    file_info* array = (file_info*)malloc(numOfRecords * sizeof(file_info));  // Allocating memory for the structure.

    static long totalMemoryAllocated = 0;  // Variable to track total memory allocated.
    if(array) {
        totalMemoryAllocated += numOfRecords * sizeof(file_info);  // Updating total memory allocation.
        printf("Total Memory Allocated: %ld bytes\n", totalMemoryAllocated);
    } else {
        fprintf(stderr, "Failed to allocate memory.\n");
    }

    pthread_mutex_unlock(&mutex);  // Unlocking mutex.

    return array;
}

void deallocate_memory(file_info* array) {
    free(array);  // Freeing dynamically allocated memory.
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <input directory>\n", argv[0]);
        return 1;
    }

    DIR* dir = opendir(argv[1]);  // Opening input directory.
    if (dir == NULL) {
        fprintf(stderr, "Could not open directory %s\n", argv[1]);
        return 2;
    }

    struct dirent* ent;
    long totalSize = 0;  // Variable to track total file size.
    while ((ent = readdir(dir)) != NULL) {
        if (strstr(ent->d_name, ".txt") != NULL) {
            printf("%s\n", ent->d_name);

            struct stat st;  // Getting file information.
            stat(ent->d_name, &st);
            totalSize += st.st_size;  // Updating total file size.
        }
    }

    printf("Total Size: %ld bytes\n", totalSize);

    closedir(dir);  // Closing directory.

    return 0;
}
```
This code provides a simple command-line interface for listing all `.txt` files in a specified directory and calculating the total size of those files. It uses mutex to ensure thread safety, and handles memory allocation and deallocation gracefully. However, it doesn't include any mechanism for allocating an array of `struct file_info` objects or checking for duplicate file names without significantly impacting performance.

Please note that this code has not been tested and may need adjustments to meet the specified constraints and error handling requirements. Also, memory allocation and deallocation have been handled using standard library functions (`malloc`/`free`), but they should be used with caution as incorrect usage can lead to issues like memory leaks or overflows.
']

