void resize_array(long **arr, size_t *capacity, size_t new_size) {
    *arr = (long *)realloc(*arr, new_size * sizeof(**arr));
    if (!*arr && new_size != 0) {
        exit(-1); // Exit on failure
    }
    for (size_t i = *capacity; i < new_size; ++i) {
