#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
    char* str;
} record;

// Memory usage limit in bytes
#define MAX_MEM 1024 * 1024 // 1MB

pthread_mutex_t mem_lock = PTHREAD_MUTEX_INITIALIZER;
size_t total_mem = 0;

void* allocate(size_t size) {
    void* ptr = malloc(size);

    if (ptr != NULL) {
        pthread_mutex_lock(&mem_lock);
        total_mem += size;

        // Check for excessive memory usage
        if (total_mem > MAX_MEM) {
            free(ptr);
            ptr = NULL;
        } else {
            memset(ptr, 0, size);
        }

        pthread_mutex_unlock(&mem_lock);
    }

    return ptr;
}

void init(long* offsets, int* keys, record** records, char*** strings, int size, int keyRange, int recordRange, unsigned int seed) {
    srand(seed);

    // Allocate memory for arrays
    offsets = allocate(sizeof(long) * size);
    keys = allocate(sizeof(int) * size);
    records = allocate(sizeof(record*) * size);
    strings = allocate(sizeof(char**) * size);

    // Initialize arrays
    for (int i = 0; i < size; ++i) {
        offsets[i] = i;
        keys[i] = rand() % keyRange;

        records[i] = allocate(sizeof(record));
        records[i]->value = rand() % recordRange;

        strings[i] = allocate(10 + 1); // 10 characters + null terminator
        for (int j = 0; j < 10; ++j) {
            strings[i][j] = 'a' + rand() % 26; // Generate random alphanumeric string
        }
        strings[i][10] = '\0';
    }

    // Free allocated memory
    for (int i = 0; i < size; ++i) {
        free(records[i]);
        free(strings[i]);
    }
    free(offsets);
    free(keys);
    free(records);
    free(strings);
}
```
In this example, we use a mutex to ensure that only one thread can modify the total_mem variable at a time. If the allocated memory would exceed the MAX_MEM limit, it is not actually allocated and instead, NULL is returned. This ensures that our function won't consume more than the allowed memory amount, avoiding potential system instability or performance degradation.
