```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    char* message; // event message buffer
    int type;      // type of the event
    long timestamp;// timestamp of the event
} Event;

int generate_events(Event** events, long* timestamps, int* types, 
                    size_t array_size, long range_start, long range_end) {

    if (range_end < range_start || range_start < 0 || range_end < 0 || 
        array_size <= 0) {
         return -1; // Invalid input ranges
    }

    srand(time(NULL));
    timestamps = malloc(array_size * sizeof(*timestamps));
    types = malloc(array_size * sizeof(*types));
    if (timestamps == NULL || types == NULL) {
        return -2; // Insufficient memory error
    } 

    for (int i = 0; i < array_size; ++i) {
        timestamps[i] = range_start + rand() % (range_end - range_start + 1);
        types[i] = rand(); // Generate random event type
    }

    *events = malloc(array_size * sizeof(**events));
    if (*events == NULL) {
        return -2; // Insufficient memory error
    } 

    for (int i = 0; i < array_size; ++i) {
        int message_length = 10 + rand() % 46; // Random length between 10 to 55 chars.
        (*events)[i].message = malloc(message_length);

        if ((*events)[i].message == NULL) {
            return -2; // Insufficient memory error
        } 

        for (int j = 0; j < message_length-1; ++j) {
            (*events)[i].message[j] = 'a' + rand() % ('z'-'a'); // Generate random string.
        }
        (*events)[i].message[message_length-1] = '\0'; 

        (*events)[i].type = types[i];
        (*events)[i].timestamp = timestamps[i];
    }

    return 0; // Success
}
```
This function dynamically allocates memory for arrays of long and int values representing timestamps and event types. It also allocates an array of Event structures, each containing a char buffer to store the message of the event along with its type and timestamp. The length of random generated strings can vary between 10 to 55 characters inclusive.
