['(The code provided here is a basic implementation and may need to be adjusted according to the specific requirements of your program.)
```c
// Define record structure
typedef struct {
    int key;
    int value;
} record;

void initializeHashTable(int num_records) 
{
    if (num_records < 0 || num_records > 10000) 
	{
        printf("Invalid number of records. It should be between 0 and 10,000.\n");
        return;
    }

    int* bucket_sizes = (int*)malloc(num_records * sizeof(int));
    record** buckets = (record**)malloc(num_records * sizeof(record*));
    record* records = (record*)malloc(num_records * sizeof(record));

    if(bucket_sizes == NULL || buckets == NULL || records == NULL) 
	{
        printf("Memory allocation failed.\n");
        free(bucket_sizes);
        free(buckets);
        free(records);
        return;
    }

    // Initialize bucket sizes and pointers to NULL
    for (int i = 0; i < num_records; ++i) 
	{
        bucket_sizes[i] = 0;
        buckets[i] = NULL;
    }

    size_t total_memory_allocated = 0;
    total_memory_allocated += num_records * sizeof(int);
    total_memory_allocated += num_records * sizeof(record*);
    total_memory_allocated += num_records * sizeof(record);

    // Initialize records
    srand((unsigned int)time(NULL));  // Seed random number generator
    for (int i = 0; i < num_records; ++i) 
	{
        records[i].key = rand();  // Generate a unique key
        records[i].value = i;     // Initialize value

        int bucket_index = records[i].key % num_records;  // Hash function
        if(buckets[bucket_index] == NULL)
            buckets[bucket_index] = &records[i];
        else
        {
            record* temp = buckets[bucket_index];
             while(temp->next != NULL)  // Collision handling using chaining
                temp = temp->next;
            temp->next = &records[i];
        }
    }

    printf("Total memory allocated: %zu bytes\n", total_memory_allocated);

    // Free the allocated memory...
    free(bucket_sizes);
    free(buckets);
    free(records);
}
```
This code first validates the input number of records to be within acceptable range (0-10,000). It then allocates three arrays: `bucket_sizes` for storing bucket sizes, `buckets` for linked list pointers, and `records` for record structures. Memory allocation is checked for failure and if it fails, all allocated memory is freed before returning from the function.

The function then iterates over each array to initialize its elements as per requirement. For collision handling in case of duplicate keys, chaining is used where a new record's address is stored into `next` field of last record. 

Finally, it prints out total memory allocated and frees all dynamically allocated memory before the function returns. Please note that this code doesn't handle multi-threaded access or unique key generation for multiple threads inserting records concurrently. You would need to implement appropriate synchronization mechanisms if your program is a multi-threaded one.
