```c
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record_t;

record_t* records = NULL;
size_t capacity = 0, size = 0;
const size_t CHUNK_SIZE = 1024;

void ensureCapacity(size_t newSize) {
    if (newSize > capacity) {
        capacity += CHUNK_SIZE;
        records = realloc(records, sizeof(*records) * capacity);
        if (!records) {
            fprintf(stderr, "Error: could not allocate memory.\n");
            exit(EXIT_FAILURE);
        }
    }
}

void addRecord() {
    ensureCapacity(size + 1);
    records[size].value = rand();  // Set random value to each record's int field.
    ++size;
}

int main() {
    srand((unsigned) time(NULL));   // Initialize random number generator.

    long* offsets = malloc(1024 * sizeof(*offsets));  // Allocate memory for array of 'long' offset values.
    int* keys = calloc(1024, sizeof(*keys));          // Allocate and zero-initialize an array of 'int' keys.

    ensureCapacity(CHUNK_SIZE);  // Initially, allocate a chunk.
    for (size_t i = 0; i < 512; ++i) {
        addRecord();  // Add some records.
    }
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
```
