void sortRecords(long *offsets, Record **records, size_t length) {
    for (size_t i = 0; i < length - 1; ++i) {
        for (size_t j = 0; j < length - i - 1; ++j) {
            if (*(offsets + j) > *(offsets + j + 1)) {
                long tempOffset = *(offsets + j);
                Record* tempRecord = *(records + j);

                *(offsets + j) = *(offsets + j + 1);
                *(records + j) = *(records + j + 1);

                *(offsets + j + 1) = tempOffset;
                *(records + j + 1) = tempRecord;
            }
        }
    }
}

void manageMemory(long **offsets, int **keys, Record ***records, size_t length) {
    srand(time(NULL));  // Seed the random number generator.

    *offsets = (long*) calloc(length, sizeof(long));
    if (*offsets == NULL) exit(EXIT_FAILURE);

    *keys = (int*) malloc(sizeof(int) * length);
    if (*keys == NULL) {
        free(*offsets);
        exit(EXIT_FAILURE);
    }

    *records = (Record**) calloc(length, sizeof(Record*));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        exit(EXIT_FAILURE);
