Record* initializeDatabase(int initialCapacity, int maxStringLength) {
    srand((unsigned int) time(NULL)); // seed the random number generator

    Record* database = (Record*) malloc(initialCapacity * sizeof(Record));

    if (!database) {
        printf("Failed to allocate memory for records\n");
        exit(1);
    }

    for (int i = 0; i < initialCapacity; ++i) {
        database[i].key = rand();

        // Dynamically allocate identifier and string_field
        int identifierLength = 256;
        database[i].identifier = (char*) malloc(identifierLength * sizeof(char));
        if (!database[i].identifier) {
            printf("Failed to allocate memory for identifier\n");
            exit(1);
        }

        sprintf(database[i].identifier, "record_%d", i+1); // Create a unique identifier

        database[i].string_field = (char*) malloc(maxStringLength * sizeof(char));
        if (!database[i].string_field) {
            printf("Failed to allocate memory for string field\n");
            exit(1);
        }
    }

    return database;
}

void resizeDatabase(Record** database, int* currentCapacity, int newCapacity, int maxStringLength) {
    *database = realloc(*database, newCapacity * sizeof(Record));

    if (!*database) {
        printf("Failed to resize memory for records\n");
        exit(1);
    }

    // Allocate and initialize new records
    for (int i = *currentCapacity; i < newCapacity; ++i) {
        (*database)[i].key = rand();

        int identifierLength = 256;
        (*database)[i].identifier = (char*) malloc(identifierLength * sizeof(char));
        sprintf((*database)[i].identifier, "record_%d", i+1); 

        (*database)[i].string_field = (char*) malloc(maxStringLength * sizeof(char));
    }

    *currentCapacity = newCapacity;
}

int main() {
    const int initialCapacity = 5;
    const int maxStringLength = 256;
    int currentDatabaseSize = initialCapacity;

    Record* database = initializeDatabase(initialCapacity, maxStringLength);

    printf("Initialized database with capacity %d\n", currentDatabaseSize);

    // Resize the database if needed
    resizeDatabase(&database, &currentDatabaseSize, 10, maxStringLength);

    printf("Resized database to capacity %d\n", currentDatabaseSize);

    // Free memory
    for (int i = 0; i < currentDatabaseSize; ++i) {
        free(database[i].identifier);
        free(database[i].string_field);
    }

    free(database);

    return 0;
}
```
