    srand(time(NULL));

    for (int i = 0; i < num; ++i) {
        pthread_mutex_lock(&lock);

        int key = keys[i];
        while (key >= 1000 || key < 0) {
            ++key;
            if (key > 999) key = 0;
            for (int j = 0; j < num; ++j) {
