extern void logError(const char* message, ...);
extern void logWarning(const char* message, ...);

UeContext** createAndPopulateUEContexts(unsigned int ueCount, unsigned int reportingIntervalSec) {
    // Allocate memory for UE Context array
    UeContext** ueContextArray = (UeContext**)malloc(sizeof(UeContext*) * ueCount);
    if (!ueContextArray) {
        logError("Memory allocation failed.");
        return NULL;
    }

    // Fetch UE IDs from the external source.
    unsigned int fetchedCount = 0;
    unsigned short* ueIds = fetchUeIds(&fetchedCount);
    if (!ueIds) {
        logWarning("Failed to fetch UE IDs.");
        return NULL;
    }

    // Populate the UE Context array with valid UE IDs.
    for (unsigned int i = 0; i < ueCount && i < fetchedCount; i++) {
        if (ueIds[i] > 65535) {
            logWarning("Invalid UE ID: %d", ueIds[i]);
            continue;
        }

        // Allocate memory for each UE Context.
        UeContext* ueContext = (UeContext*)malloc(sizeof(UeContext));
        if (!ueContext) {
            logError("Memory allocation failed.");
            return NULL;
        }

        // Initialize the UE Context with valid data.
        ueContext->ueId = ueIds[i];
        pthread_mutex_lock(&reportMutex);
        if (measurementReportCount > 0) {
            // Reuse an existing Measurement Report from the pool.
            measurementReportCount--;
            ueContext->measurementReport = measurementReportPool[measurementReportCount];
        } else {
            // Allocate a new Measurement Report.
            MeasurementReport* measurementReport = (MeasurementReport*)malloc(sizeof(MeasurementReport));
            if (!measurementReport) {
                logError("Memory allocation failed.");
                return NULL;
            }
            ueContext->measurementReport = measurementReport;
        }
        pthread_mutex_unlock(&reportMutex);

        // Initialize the reporting configuration.
        ueContext->isPeriodicEnabled = true;
        ueContext->reportingIntervalSec = reportingIntervalSec;

        ueContextArray[i] = ueContext;
    }

    free(ueIds);
    return ueContextArray;
}
