['Here's an example solution in C:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    float temperature;
    float humidity;
    int pressure;
} sensor_reading;

// Function to read from file
int read_sensor_readings(const char *filename, sensor_reading **data) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Failed to open the file.\n");
        return -1; // Return error code in case of failure.
    }

    int size = 0;
    int capacity = 10;
    *data = malloc(capacity * sizeof(sensor_reading));
    if (*data == NULL) {
        printf("Failed to allocate memory.\n");
        return -2; // Return error code in case of failure.
    }

    char line[100];
    while (fgets(line, sizeof(line), file)) {
        if (size >= capacity) {
            capacity *= 2;
            sensor_reading *temp = realloc(*data, capacity * sizeof(sensor_reading));
            if (temp == NULL) {
                printf("Failed to re-allocate memory.\n");
                return -3; // Return error code in case of failure.
            }
            *data = temp;
        }

        sensor_reading reading;
        char *token;
        token = strtok(line, ",");
        if (token == NULL) continue; // Skip invalid lines.
        reading.temperature = atof(token);

        token = strtok(NULL, ",");
        if (token == NULL) continue; // Skip invalid lines.
        reading.humidity = atof(token);

        token = strtok(NULL, ",");
        if (token == NULL) continue; // Skip invalid lines.
        reading.pressure = atoi(token);

        (*data)[size++] = reading;
    }

    fclose(file);
    return size; 
}
```

This function reads from the file line by line, parsing each line into a sensor_reading struct and adding it to the array. The function returns the number of readings or a negative error code in case of an error.

