typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct CRC_INDICATION_REL8_TAG {
        int CRCFLAG;
    } crcTag;
} NFAPI_CRC_INDICATION_PDU_T;

sem_t semaphore;
int totalMemoryAllocated = 0;

void* allocateAndTrack(size_t size) {
    void* memory = malloc(size);
    if (memory == NULL) {
        printf("Failed to allocate memory\n");
        exit(1);
    }
    totalMemoryAllocated += size;
    return memory;
}

void deallocateAndTrack(void* memory, size_t size) {
    free(memory);
    totalMemoryAllocated -= size;
}

int main() {
    srand(time(NULL));
    sem_init(&semaphore, 0, 1); // Initialize a binary semaphore

    int N = 100, M = 1000;
    NFAPI_CRC_INDICATION_PDU_T* list = allocateAndTrack(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    int* array = allocateAndTrack(sizeof(int) * M);

    // Populate the structures and the array
    for (int i = 0; i < N; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand();
        list[i].RNTI = rand() % 65536; // Validate RNTI in the valid range (1 to 65535)
        list[i].crcTag.CRCFLAG = rand() % 2; // Ensure CRCFLAG is either 0 or 1
    }
    for (int i = 0; i < M; ++i) {
        array[i] = rand();
    }

    sem_wait(&semaphore); // Wait and lock the critical section

    int maxVal = -1;
    for (int i = 0; i < M; ++i) {
        if (array[i] > maxVal) maxVal = array[i];
    }
    printf("Max value: %d\n", maxVal);

    sem_post(&semaphore); // Release the critical section

    deallocateAndTrack(list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    deallocateAndTrack(array, sizeof(int) * M);

    printf("Total memory allocated: %d bytes\n", totalMemoryAllocated);

    sem_destroy(&semaphore); // Delete the semaphore

    return 0;
}
