namespace MyNamespace {
    struct Node {
        int value;
        Node* next;
        long id;
    };

    std::vector<Node*> nodes;
    std::mutex mtx;  // For thread safety.

    void allocate_memory(int numNodes, std::vector<long>& offsets, std::vector<int>& keys) {
        std::lock_guard<std::mutex> lock(mtx);  // Lock the mutex to ensure thread-safe memory allocation.

        srand(time(0));  // Seed the random number generator.

        for (int i = 0; i < numNodes; ++i) {
            Node* node = new Node();

            // Assign a unique id to each node.
            std::random_device rd;  
            std::mt19937 gen(rd()); 
            std::uniform_int_distribution<> dis(0, INT_MAX);
