            nodes.push_back(node);
        }

        std::sort(nodes.begin(), nodes.end(), [](const Node* a, const Node* b) { return a->value < b->value; });  // Sort nodes based on their values.

        for (int i = 0; i < numNodes; ++i) {
            offsets[i] = reinterpret_cast<long>(nodes[i]);  // Calculate and assign the offset to each node.
        }
    }
}
