void loadLibrary(int idx) {
    handle[idx] = dlopen(libNames[idx], RTLD_LAZY);
    if (!handle[idx]) {
        fprintf(stderr, "Error loading library: %s\n", dlerror());
        exit(EXIT_FAILURE);
    }
}

void (*func)(double*, int*, char**, config*); // function pointer for dynamic loaded functions

void processData(int size, config* cfg) {
    double* doubles = malloc(sizeof(double) * size);
    if (doubles == NULL) {
        perror("Error allocating memory");
        exit(EXIT_FAILURE);
    }

    int* keys = malloc(sizeof(int) * size);
    if (keys == NULL) {
        perror("Error allocating memory");
        free(doubles);
        exit(EXIT_FAILURE);
    }

    char** strings = malloc(sizeof(char*) * size);
    if (strings == NULL) {
        perror("Error allocating memory");
        free(doubles);
        free(keys);
        exit(EXIT_FAILURE);
    }

    data_record* records = malloc(sizeof(data_record) * size);
    if (records == NULL) {
        perror("Error allocating memory");
        free(doubles);
        free(keys);
        free(strings);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < size; ++i) {
        doubles[i] = cfg->min_double + ((double)rand() / RAND_MAX) * (cfg->max_double - cfg->min_double);
        keys[i] = cfg->min_int + rand() % (cfg->max_int - cfg->min_int + 1);

        // generate a random string of length 10 for demonstration purposes
        strings[i] = malloc(sizeof(char) * 11);
        if (strings[i] == NULL) {
            perror("Error allocating memory");
            free(doubles);
            free(keys);
            // free all previously allocated strings before exiting
            for (int j = 0; j < i; ++j) {
                free(strings[j]);
            }
            free(records);
            exit(EXIT_FAILURE);
        }

        for (int k = 0; k < 10; ++k) {
            strings[i][k] = 'a' + rand() % 26;
        }
        strings[i][10] = '\0';

        records[i].doubles = &doubles[i];
        records[i].keys = &keys[i];
        records[i].strings = &strings[i];
    }

    for (int i = 0; i < 3; ++i) {
        if (handle[i] != NULL) {
            func = dlsym(handle[i], "processData");
            char* error = dlerror();
            if (error != NULL) {
                fprintf(stderr, "Error locating symbol: %s\n", error);
                exit(EXIT_FAILURE);
            }

            (*func)(doubles, keys, strings, cfg); // call dynamic loaded function
        }
    }

    for (int i = 0; i < size; ++i) {
        free(strings[i]);
    }

    free(records);
    free(doubles);
    free(keys);
    free(strings);
}
``` 
Please note that this example provides a basic structure and doesn't include the dynamic loading of libraries or the processData function for each library. You will need to implement these parts according to your specific needs, such as defining the functions in your shared libraries and modifying `processData` accordingly. Also, make sure you have the necessary development packages (like libgmp-dev for GMP) installed on your system when compiling with dynamic linking.
']

