typedef struct 
{
    void* mem_block;
    size_t mem_size;
} custom_mem_block;

custom_mem_block custom_alloc(size_t size) {
    custom_mem_block block = { .mem_block = NULL, .mem_size = 0 };

    if (size > 10000 || size <= 0) 
        return block;

    block.mem_block = malloc(size);
    if (!block.mem_block) 
        return block;

    block.mem_size = size;

    return block;
}

void custom_free(custom_mem_block* block) {
    if (block && block->mem_block) {
        free(block->mem_block);
        block->mem_block = NULL;
        block->mem_size = 0;
    }
}

int initialize_data(long* offsets, int* keys, record** records, char*** strings, int size) {
    if (size > 10000 || size <= 0) 
        return -1;

    offsets = malloc(size * sizeof(*offsets));
    if (!offsets) 
