async function loadAndExecuteScript(scriptUrl, isDependency = false) {
    return new Promise((resolve, reject) => {
        let scriptElement = document.createElement('script');
        scriptElement.src = scriptUrl;

        if (isDependency) {
            scriptElement.onload = resolve;
        } else {
            scriptElement.async = false; // If it's not a dependency, load in order
