// Function to check if a UE ID already exists in the list of contexts.
int isUEIdUnique(long ue_id, UEContext* head) {
    pthread_mutex_lock(&lock);
    for (UEContext* current = head; current != NULL; current = current->next) {
        if (current->ue_id == ue_id) {
            return 0; // False, not unique.
        }
    }
    pthread_mutex_unlock(&lock);
    return 1; // True, unique.
}

// Function to add a UE Context to the list.
void addUEContext(long ue_id, float signal_strength, float latency, float packet_loss, long reporting_interval, UEContext** head) {
    pthread_mutex_lock(&lock);
    UEContext* newNode = (UEContext*) malloc(sizeof(UEContext));

    if (newNode == NULL || !isUEIdUnique(ue_id, *head)) {
        log_error("Memory allocation failed or UE ID is not unique.");
        return;
    }

    newNode->ue_id = ue_id;
    newNode->signal_strength = signal_strength;
    newNode->latency = latency;
    newNode->packet_loss = packet_loss;
    newNode->reporting_interval = reporting_interval;

    // Add at the beginning.
    newNode->next = *head;
    *head = newNode;

    pthread_mutex_unlock(&lock);
}

// Function to update UE Context based on ID.
void updateUEContext(long ue_id, float signal_strength, float latency, float packet_loss, long reporting_interval, UEContext* head) {
    pthread_mutex_lock(&lock);
    for (UEContext* current = head; current != NULL; current = current->next) {
        if (current->ue_id == ue_id) {
            current->signal_strength = signal_strength;
            current->latency = latency;
            current->packet_loss = packet_loss;
            current->reporting_interval = reporting_interval;
        }
    }
    pthread_mutex_unlock(&lock);
}

