#include "mcrl2/core/parser_toolset.h"
#include "mcrl2/data/parse.h"

namespace mcrl2 {

namespace data {

static
std::string make_identifier(const std::string& s)
{
  return core::make_quoted_identifier(s);
}

core::term_list<core::identifier_string> parse_variables(std::string const& text)
{
  using namespace core;
  parser_toolset toolset;
  std::vector<std::string> identifier_strings = toolset.parser().split_identifiers(text);
  term_list<identifier_string> result;
  for (const std::string& s : identifier_strings)
  {
    // an identifier string must have the following format: 'vN' where N is a non-negative integer
    if (!s.empty() && s[0] == 'v')
    {
      try
      {
        int index = boost::lexical_cast<int>(s.substr(1));
        result.push_front(variable(index, basic_sort()));
      }
      catch (boost::bad_lexical_cast&)
      {
        throw mcrl2::runtime_error("Error parsing variable " + s);
      }
    }
    else
    {
      std::string name = make_identifier(s);
      result.push_front(variable(name, basic_sort()));
    }
  }
  return atermpp::reverse(result);
}

} // namespace data

