namespace detail {

/// \brief Toolbox for rewriters.
template <typename Rewriter>
class rewriter_toolbox: public Rewriter::rewriter_base
{
  protected:
    typedef Rewriter rewriter_type;
    typedef typename rewriter_type::expression_type expression_type;
    using Rewriter::rewriter_base::operator();

  public:
    /// \brief Forwards a data expression to another rewriting function.
    /// \param f A function of type std::function<expression_type(const expression_type&)>
    template <typename Func>
    expression_type rewrite_and_apply(const expression_type& x, const Func& f)
    {
      return this->rewrite_aux(x, [f](const rewriter_toolbox& self, const expression_type& y){ return f(y); });
    }
};

} // namespace detail

