/// \file mcrl2/data/replace_sorts.h
/// \brief add your file description here.

#ifndef MCRL2_DATA_REPLACE_SORTS_H
#define MCRL2_DATA_REPLACE_SORTS_H

#include "mcrl2/data/builder.h"

namespace mcrl2 {

namespace data {

/// \brief Replaces all occurrences of the sort expression s1 in x by s2
template <typename Builder>
void replace_sorts(Builder& b, const sort_expression& s1, const sort_expression& s2, typename Builder::expression_type& x)
{
  struct replacer: public data_expression_builder<Builder>
  {
    const sort_expression& m_s1;
    const sort_expression& m_s2;

    using super = data_expression_builder<Builder>;
    using typename super::expression_type;
    using typename super::variable_type;

    replacer(const Builder& b, const sort_expression& s1, const sort_expression& s2)
      : super(b), m_s1(s1), m_s2(s2)
    {}

    expression_type operator()(const function_symbol& x) const override
    {
      return update_application(x);
    }

    expression_type operator()(const where_clause& x) const override
    {
      return super::apply_rewriter(*this, x.body());
    }

  private:
    expression_type update_function_sort(const function_sort& x) const
    {
      if (x == m_s1)
        return function_sort(replace_sorts(b(), m_s1, m_s2, x.domain()), replace_sorts(b(), m_s1, m_s2, x.codomain()));
      else
        return super::operator()(x);
    }

    expression_type update_application(const function_symbol& x) const
    {
      auto f = [this](const sort_expression& s){ return replace_sorts(b(), m_s1, m_s2, s); };
      sort_expression result = utilities::map_replace_function<sort_expression>(f, x.sort());
      if (result != x.sort())
        return function_symbol(x.name(), result);
      else
        return super::operator()(x);
    }
  };

  b().rewrite(*this, replacer(b(), s1, s2), x);
}

/// \brief Replaces all occurrences of the sort expression s1 in x by s2.
template <typename Builder>
void replace_sorts(Builder& b, const sort_expression& s1, const sort_expression& s2, typename Builder::variable_type& x)
{
  if (x.sort() == s1)
    x = variable(x.name(), replace_sorts(b(), s1, s2, x.sort()));
}

/// \brief Replaces all occurrences of the sort expression s1 in x by s2.
inline void replace_sorts(data::rewriter& rewr, const sort_expression& s1, const sort_expression& s2, data_expression& x)
{
  rewriter r(rewr);
  r.update(x, [&](const data_expression& y){ return replace_sorts(y, s1, s2); });
}

/// \brief Replaces all occurrences of the sort expression s1 in x by s2.
inline void replace_sorts(data::rewriter& rewr, const sort_expression& s1, const sort_expression& s2, variable_list& x)
{
  for (variable& v : x)
    replace_sorts(rewr, s1, s2, v);
}

/// \brief Replaces all occurrences of the sort expression s1 in x by s2.
inline void replace_sorts(data::rewriter& rewr, const sort_expression& s1, const sort_expression& s2, data_equation& x)
{
  variable_list parameters;
  for (const data_assignment& assignment : x.assignments())
    parameters.push_back(assignment.variable());
  replace_sorts(rewr, s1, s2, parameters);
}

/// \brief Replaces all occurrences of the sort expression s1 in x by s2.
inline void replace_sorts(data::rewriter& rewr, const sort_expression& s1, const sort_expression& s2, data_specification& x)
{
  for (auto i = x.constructors().begin(); i != x.constructors().end(); ++i)
    replace_sorts(rewr, s1, s2, *i);
}

/// \brief Replaces all occurrences of the sort expression s1 in x by s2.
inline void replace_sorts(data::rewriter& rewr, const sort_expression& s1, const sort_expression& s2, sort_list& x)
{
  for (sort_expression& sort : x)
    replace_sorts(rewr, s1, s2, sort);
}

/// \brief Replaces all occurrences of the sort expression s1 in x by s2.
inline void replace_sorts(data::rewriter& rewr, const sort_expression& s1, const sort_expression& s2, data_type& x)
{
  for (sort_constructor& constructor : x.constructors())
    replace_sorts(rewr, s1, s2, constructor);
}

/// \brief Replaces all occurrences of the sort expression s1 in x by s2.
inline void replace_sorts(data::rewriter& rewr, const sort_expression& s1, const sort_expression& s2, basic_sort& x)
{
  if (x == s1)
    x = s2;
}

} // namespace data

} // namespace mcrl2

