/// \file read_textual_specification.cpp

#include "mcrl2/data/parse.h"
#include "mcrl2/utilities/input_tool.h"
#include "mcrl2/bes/io.h"

using namespace mcrl2;
using bes::tools::input_tool;

class textual_specification_tool: public input_tool
{
  protected:
    typedef input_tool super;

    bool process_data(const std::string& s) override
    {
      try
      {
        mCRL2log(log::debug) << "Parsing data specification:\n" << s << "\n";
        data::parse_specification(s);
      }
      catch (mcrl2::runtime_error& e)
      {
        mCRL2log(log::error) << e.what() << "\n";
        return false;
      }
      return true;
    }

  public:
    textual_specification_tool(): super("textual_specification", "Wieger Wesselink; Richard J. Boulton",
                                      "Reads a data specification from a string and checks if it is well formed",
                                      "Read a textual specification (either in the format of mCRL2 or directly as a Coq term) from INFILE and write this to OUTFILE.")
    {}
};

int main(int argc, char** argv)
{
  return textual_specification_tool().execute(argc, argv);
