/// \file write_textual_specification.cpp

#include "mcrl2/data/print.h"
#include "mcrl2/utilities/input_output_tool.h"

using namespace mcrl2;
using bes::tools::input_output_tool;

class textual_specification_tool: public input_output_tool
{
  protected:
    typedef input_output_tool super;

    bool process_data(const data::data_specification& dataspec, const std::string& s) override
    {
      out() << data::pp(dataspec) << "\n";
      return true;
    }

  public:
    textual_specification_tool(): super("write_textual_specification", "Wieger Wesselink",
                                       "writes a textual specification to the output stream",
                                       "Read a data specification from INFILE and write this data specification in textual format to OUTFILE. If OUTFILE is not supplied, stdout is used.")
    {}
};

int main(int argc, char** argv)
{
  return textual_specification_tool().execute(argc, argv);
