#define BOOST_TEST_MODULE untyped_domain_test
#include <boost/test/included/unit_test.hpp>

#include "mcrl2/data/parse.h"
#include "mcrl2/data/untyped_domain.h"

using namespace mcrl2;

BOOST_AUTO_TEST_CASE(test_boolean)
{
  const data::sort_expression b(data::basic_sort("B"));
  const data::function_symbol f("f", data::variable_list({b}));
  BOOST_CHECK(!data::is_untyped_domain(f));
}

BOOST_AUTO_TEST_CASE(test_real)
{
  std::string s = "sort R;\n"
                  "\n"
                  "proc P(x:R)\n"
                  "end P;\n";
  data::data_specification dataspec = data::parse_data_specification(s);
  const data::function_symbol f("f", data::variable_list({data::real()}));
  BOOST_CHECK(!data::is_untyped_domain(f));
}

BOOST_AUTO_TEST_CASE(test_set)
{
  std::string s = "sort R;\n"
                  "\n"
                  "proc P(x:Set(R))\n"
      "end P;\n";
  data::data_specification dataspec = data::parse_data_specification(s);
  const data::function_symbol f("f", data::variable_list({data::set_(data::real())}));
  BOOST_CHECK(!data::is_untyped_domain(f));
}

BOOST_AUTO_TEST_CASE(test_elementary)
{
  std::string s = "sort R;\n"
                  "\n"
                  "proc P(x:R)\n"
      "end P;\n";
  data::data_specification dataspec = data::parse_data_specification(s);
  const data::function_symbol f("f", data::variable_list({dataspec.sorts().front()}));
  BOOST_CHECK(!data::is_untyped_domain(f));
