static
void test_constant(const std::string& text, const data::sort_expression& expected_sort)
{
  std::cout << "Test constant: " << text << std::endl;
  std::istringstream is(text + ";");
  std::string result;
  const data::data_expression& e = data::parse_data_expression(is, text.size() + 1);
  if (e != expected_sort)
  {
    mCRL2log(log::error) << "test_constant: " << text << "\nresult     : " << e << std::endl;
  }
  BOOST_CHECK(e == expected_sort);
}

BOOST_AUTO_TEST_CASE(test_parse2)
{
  using data::basic_sort;
  using data::real;
  using data::pos_int;
  using data::bool_;
  using data::struct_;
  using data::list;

  test_constant("c", basic_sort("S"));
  test_constant("true", bool_());
  test_constant("false", bool_());
