#define BOOST_TEST_MODULE parse_test4
#include <boost/test/included/unit_test.hpp>

#include "mcrl2/data/parse.h"
#include "mcrl2/data/rewriter.h"
#include "mcrl2/data/normalize.h"

using namespace mcrl2;

void test_expression(const std::string& expr, const data::sort_expression& expected)
{
  std::cerr << "Testing expression: '" << expr << "'\n";
  std::istringstream is(expr);
  data::text_parser parser(is);
  data::data_expression e;
  BOOST_CHECK(parser.parse_sorted_var(e));
  data::sort_expression s = expected;
  s = data::normalize_sorts(s);
  if (s != e.sort())
  {
    std::cerr << "Error: result '" << e << "' has sort '" << e.sort() << "', which differs from the expected sort '" << s << "'\n";
  }
  BOOST_CHECK(s == e.sort());
}

BOOST_AUTO_TEST_CASE(test_main)
{
  using namespace mcrl2::data;
  data::rewriter rr(core::detail::default_values::AddConstructors);
  test_expression("x : Bool", sort_bool::bool_());
  test_expression("x : Pos", pos::pos());
  test_expression("x : Nat", nat::nat());
  test_expression("f : Bool -> Set(Bool)", function_sort(sort_bool::bool_(), basic_sort("Set", { sort_bool::bool_() })));
  test_expression("g : List(Bool) -> Set(Bool)", function_sort(list(sort_bool::bool_()), basic_sort("Set", { sort_bool::bool_() })));
  test_expression("f : Nat#Nat -> Bool", function_sort(cross({ nat::nat(), nat::nat() }), sort_bool::bool_()));
  test_expression("h : Nat x List(Bool)#Enum(Bool) -> Set(Pos)", function_sort(struct_(nat::nat(), cross({ list(sort_bool::bool_()), enum_({ "a", "b" }) })), basic_sort("Set", { pos::pos() })));
  test_expression("h : Nat x List(Bool)#Enum(Bool) -> Set(Pos)", function_sort(struct_(nat::nat(), cross({ list(sort_bool::bool_()), enum_({ "a", "b" }) })), basic_sort("Set", { pos::pos() })));
