void test_expression(const std::string& expr, const data::data_expression& expected)
{
  std::cerr << "Testing expression: '" << expr << "'\n";
  std::istringstream is(expr);
  data::text_parser parser(is);
  data::data_expression e;
  BOOST_CHECK(parser.parse_sorted_var(e));
  if (expected != e)
  {
    std::cerr << "Error: result '" << e << "' differs from the expected expression '" << expected << "'\n";
  }
  BOOST_CHECK(expected == e);
}

