#define BOOST_TEST_MODULE readline
#include <boost/test/included/unit_test.hpp>

#include "mcrl2/utilities/readline_completions.h"

using namespace mcrl2;

struct test_state
{
  size_t index;
};

static char *command_generator(const char *text, int state)
{
    static std::vector<std::string> commands = {"list", "version", "quit"};
    if (state == 0)
    {
      utilities::readline::set_completion_callbacks({});
    }
    else if (state > 0 && state <= int(commands.size()))
    {
      return strdup(commands[state - 1].c_str());
    }
    return nullptr;
}

static char **command_completion(const char *text, int start, int end)
{
  utilities::readline::set_completion_callbacks({
      { command_generator },
  });
  return rl_completion_matches(text, command_generator);
}

BOOST_AUTO_TEST_CASE(test_main)
{
  std::vector<std::string> commands = {"list", "version", "quit"};

  /* A line buffer for user input. */
  char* line_read = nullptr;

  /* The main readline loop where we fill the line from the user. */
  rl_attempted_completion_function = command_completion;
  while ((line_read = readline("> ")) != nullptr)
  {
    if (strcmp(line_read, "quit") == 0)
    {
      break;
    }
    /* Check whether the line matches any of our commands. */
    auto it = std::find(commands.begin(), commands.end(), line_read);
    if (it != commands.end())
    {
      // Do something with command.
    }
    else
    {
      printf("command not recognized\n");
    }

    if (line_read)
    {
      free(line_read);
    }
  }
