/// \file test_unordered_map.cpp
/// \brief Add your file description here.

#define BOOST_TEST_MODULE unordered_map
#include <cstddef>
#include <random>
#include <boost/test/included/unit_test.hpp>
#include "mcrl2/utilities/unordered_map.h"

using namespace mcrl2;

struct entry
{
  std::size_t key;
  int value;
};

std::vector<entry> random_entries(std::size_t n, std::default_random_engine& generator)
{
  std::uniform_int_distribution<std::size_t> distribution;
  std::vector<entry> v;
  for (std::size_t i = 0; i < n; ++i)
  {
    v.push_back({ distribution(generator), 0 });
  }
  return v;
}

BOOST_AUTO_TEST_CASE(test_unordered_map)
{
  std::default_random_engine generator(42);
  constexpr std::size_t n = 10000;

  // Test the behaviour of uninitialized variables in an unordered map.
  // The value field is not initialized, but it is assumed to be zero by the compiler, which is what we check here.
  std::vector<entry> v = random_entries(n, generator);
  utilities::unordered_map<std::size_t, int> m;
  for (const entry& e: v)
  {
    auto result = m.insert({e.key, e.value});
    if (!result.second)
    {
      // Check that existing entries have value zero.
      BOOST_CHECK(m[e.key] == 0);
    }
    else
    {
      // Check that new entries are inserted with value zero.
      BOOST_CHECK(m[e.key] == 0);
    }
  }
