struct TestCaseInformation
{
  // input parameters
  std::string process_parameter_file;
  std::string lps_filename;
  std::string binary_filename;
  std::string fsm_filename;
  std::string trace_filename;
  std::string last_state_fsm_filename;
  bool is_trace=false;

  // output parameters
  std::size_t number_of_states=0;
  std::size_t number_of_transitions=0;
};

inline
void throw_runtime_error(const std::string& s)
{
  throw mcrl2::runtime_error(s);
}

inline
std::ostream& operator<<(std::ostream& out, const TestCaseInformation& info)
{
  if (!info.process_parameter_file.empty())
  {
    out << "Process parameter file        : " << info.process_parameter_file << "\n";
  }
  else if (!info.lps_filename.empty())
  {
    out << "LPS file                      : " << info.lps_filename << "\n";
  }
  else if (!info.binary_filename.empty())
  {
    out << "Binary file                   : " << info.binary_filename << "\n";
  }
  else if (!info.fsm_filename.empty())
  {
    out << "FSM file                      : " << info.fsm_filename << "\n";
  }
  else
  {
    throw mcrl2::runtime_error("Unexpected error");
  }

  if (!info.trace_filename.empty())
  {
    out << "Trace file                    : " << info.trace_filename << "\n";
  }

  if (!info.last_state_fsm_filename.empty())
  {
    out << "Last state FSM file           : " << info.last_state_fsm_filename << "\n";
  }

  return out;
}

