#ifndef TRACE_H
#define TRACE_H

#include <set>
#include "mcrl2/utilities/text_utility.h"

namespace mcrl2 {

class trace
{
  public:
    typedef std::vector<std::string> string_list;

    explicit trace(const string_list& actions = string_list())
      : m_actions(actions)
    {}

    const string_list& actions() const { return m_actions; }
    bool empty() const { return m_actions.empty(); }
    std::size_t size() const { return m_actions.size(); }
    std::string front() const { return m_actions.front(); }
    std::string back() const { return m_actions.back(); }
    bool operator<(const trace& t) const { return m_actions < t.m_actions; }
    void push_front(const std::string& s) { m_actions.insert(m_actions.begin(),s); }
    void pop_front() { if (!empty()) m_actions.erase(m_actions.begin()); }

  private:
    string_list m_actions;
};

inline
std::ostream& operator<<(std::ostream& out, const trace& t)
{
  return out << "(" << core::detail::print_list(out, t.actions()) << ")";
}

/// \brief A set of traces.
typedef std::set<trace> trace_set;

inline
std::ostream& operator<<(std::ostream& out, const trace_set& S)
{
  return out << "{" << core::detail::print_list(out, S) << "}";
}

/// \brief Returns the traces in the sequence of states given by a vector of strings.
trace_set compute_traces(const std::vector<std::string>& state_sequence);

void print_traces();
} // namespace mcrl2;
