using namespace mcrl2;

static void test_traces()
{
  // check empty traces
  trace t1,t2;
  BOOST_CHECK(t1 == t2);
  BOOST_CHECK(!(t1 < t2));
  std::vector<std::string> v = { "a", "b" };
  trace t3(v), t4(v);
  BOOST_CHECK(t3 == t4);
  BOOST_CHECK(!(t3 < t4));
}

static void test_compute_traces()
{
  std::vector<std::string> v;
  auto traces = compute_traces(v);
  BOOST_CHECK(traces.empty());

  v = { "a", "b" };
  traces = compute_traces(v);
  BOOST_CHECK(!traces.empty());
}

static void test_lts()
{
  std::string LTSSPEC=
    "act a, b;                                    \n"
    "                                         \n"
    "map  id: Nat;                               \n"
    "                                          \n"
    "eqn  id = 1;                                 \n"
    "proc P(s2:Nat) = sum m: Nat. Act(a,m). P(s2); \n"
    "                                         \n"
    "init P(4);                                   \n";

  lts::lts_automorphism_grapher g;
  lps::specification spec=remove_stochastic_operators(linearise(LTS_SPEC));
  state_priority_queue fringe;
  std::deque<lts_automorphism_trace> trace_fringe;
  std::multimap<std::size_t, lts_automorphism_state> distance_map;
  g.generate_lts(spec, fringe, trace_fringe, distance_map, false);
  BOOST_CHECK(!g.get_states().empty());
}

static void test_lts2()
{
  std::string LTSSPEC=
    "act a, b;                                    \n"
    "                                         \n"
    "map  id: Nat;                               \n"
    "                                          \n"
    "var s1,s2 : Nat;                             \n"
    "eqn  s1 = 0;                                  \n"
    "     s2 = 0;                                  \n"
    "proc P(s1:Nat) = sum m: Nat. Act(a,m). P(s1); \n"
    "                                         \n"
    "init P(4);                                   \n";
  lts::lts_automorphism_grapher g;
  lps::specification spec=remove_stochastic_operators(linearise(LTSSPEC));
  state_priority_queue fringe;
  std::deque<lts_automorphism_trace> trace_fringe;
  std::multimap<std::size_t, lts_automorphism_state> distance_map;
  g.generate_lts(spec, fringe, trace_fringe, distance_map, false);
  BOOST_CHECK(!g.get_states().empty());
}

void test_trace()
{
  test_traces();
  test_compute_traces();
  test_lts();
  test_lts2();
