/// \brief Returns true if text contains a prefix that is in the list of known prefixes.
inline
bool has_prefix(const std::string& text, const std::vector<std::string>& prefixes)
{
  for (std::vector<std::string>::const_iterator i = prefixes.begin(); i != prefixes.end(); ++i)
  {
    if (text.substr(0, i->size()) == *i)
    {
      return true;
    }
  }
  return false;
}

/// \brief Returns the filename stripped from path and extension. E.g., "/home/john/test.txt" is transformed to "test".
inline
std::string strip_path_and_extension(const std::string& s)
{
  return core::detail::remove_extension(s, core::detail::find_filename(s));
}

/// \brief Returns the directory that contains a filename. E.g., "/home/john/test.txt" is transformed to "/home/john".
inline
std::string strip_filename(const std::string& s)
{
  return core::detail::remove_extension(s, s);
}

/// \brief Returns the path of a filename, excluding the final slash. E.g., "/home/john/test.txt" is transformed to "/home/john".
inline
std::string strip_filename(const std::vector<std::string>& v)
{
  if (v.empty())
  {
    throw mcrl2::runtime_error("strip_filename: list of file names cannot be empty");
  }
  return core::detail::find_path(v[0]);
}

/// \brief Returns a filename that includes both path and extension. E.g., if the arguments are "/home/john" and "txt", this function returns "/home/john.txt".
inline
std::string add_extension(const std::string& s, const std::string& ext)
{
  return core::detail::add_extension(s, ext);
}

/// \brief Returns a filename that includes both path and extension of the first argument. E.g., if the arguments are "/home/john" and "test", this function returns "/home/john.txt" where "txt" is the extension belonging to test.
inline
std::string add_extension(const std::string& s, const std::vector<std::string>& v)
{
  if (v.empty())
  {
    throw mcrl2::runtime_error("add_extension: list of file names cannot be empty");
  }
  return core::detail::add_extension(s, v[0]);
}

/// \brief Returns a filename that includes both path and extension. E.g., if the arguments are "/home/john" and "txt", this function returns "/home/john.txt".
inline
std::string add_filename(const std::string& s, const std::string& ext)
{
  return core::detail::add_extension(s, ext);
}

/// \brief Returns a filename that includes both path and extension of the first argument. E.g., if the arguments are "/home/john" and "test", this function returns "/home/john.txt" where "txt" is the extension belonging to test.
inline
std::string add_filename(const std::vector<std::string>& v, const std::string& filename)
{
  if (v.empty())
  {
    throw mcrl2::runtime_error("add_extension: list of file names cannot be empty");
  }
  return core::detail::add_filename(v[0], filename);
}

/// \brief Returns true if text is a valid filename.
inline
bool is_valid_filename(const std::string& s)
{
  return !s.empty() && (s.find('/') == std::string::npos);
}

