#ifndef MCRL2_LPSREALZONE_H
#define MCRL2_LPSREALZONE_H

#include "mcrl2/data/abstraction.h"
#include "mcrl2/process/action_label.h"
#include "mcrl2/process/multi_action.h"
#include "mcrl2/utilities/indexed_set.h"
#include "realzone.h"

namespace mcrl2 {

namespace process {
namespace detail {
struct action_name;  // forward declaration
}
}

/// \brief The LpsRealZone class.
class LpsRealZone: public RealZone
{
public:
  /// \brief Constructor.
  template <typename T>
  explicit LpsRealZone(const T& real_zone);

  ~LpsRealZone();

  bool is_realizable(core::identifier_string s) const;

  std::set<std::size_t> realizability_numbers() const;

private:
  struct action_name : public mcrl2::data::variable, boost::equality_comparable<action_name>
  {
    typedef mcrl2::process::detail::action_name super;
    action_name(const super& name) : super(name.basic()) {}

    bool operator==(const action_name& other) const { return basic() == other.basic(); }
  };

  typedef mcrl2::utilities::indexed_set<action_name> ActionSet;

  void compute_realizability(ActionSet* actions, std::map<std::size_t, std::vector<ActionSet::const_iterator> >& realizable);
};

inline bool LpsRealZone::is_realizable(core::identifier_string s) const
{
  return m_name_to_index.find(s) != m_name_to_index.end();
}

template <typename T>
LpsRealZone::LpsRealZone(const T& real_zone) : RealZone()
{
  if (real_zone.process().has_time())
  {
    throw mcrl2::runtime_error("Time not supported in LPS.");
  }

  // The process parameters are interpreted as action labels, they cannot be used in the state realizability.
  ActionSet actions;
  for (const data::variable& v: real_zone.process().action_parameters())
  {
    actions.insert(action_name(v));
  }

  // The synchronization vector contains both action labels and action names, but only the latter can be used in state realizability.
  for (const process::action& a: real_zone.process().synchronisation().actions())
  {
    if (!a.label().is_tau() && actions.insert(action_name(a.label().name())).second)
    {
      m_name_to_index[a.label().name().basic().string()] = static_cast<std::size_t>(m_names.size());
      m_names.push_back(a.label().name().basic().string());
    }
  }

  compute_realizability(&actions, m_action_numbers);
}

} // namespace mcrl2

