#include "mcrl2/utilities/indexed_set.h"

namespace mcrl2 {

/// \brief The RealZone class.
class RealZone: public data::abstraction, boost::equality_comparable<RealZone>
{
public:
  /// \brief Constructor.
  explicit RealZone(const data::data_specification& dataspec);
  RealZone();

  ~RealZone();

  bool operator==(const RealZone& other) const;

protected:
  std::vector<std::string> m_names;
  std::map<std::string, std::size_t> m_name_to_index;
  std::map<std::size_t, std::vector<std::size_t> > m_action_numbers; // realizable actions per number of action(s)
};

inline bool RealZone::operator==(const RealZone& other) const
{
  return m_name_to_index == other.m_name_to_index && m_names == other.m_names && m_action_numbers == other.m_action_numbers;
}

