// \brief Rename the action labels in a labelled transition system
template <typename LABEL>
void rename_action_labels(LTS<LABEL, lps::explorer>& l, const std::map<LABEL, LABEL>& label_renaming)
{
  for (std::size_t i = 0; i < l.num_states(); ++i)
  {
    LTS<LABEL, lps::explorer>::outgoing_transition_iterator it = l.out(i);
    while (it != l.out_end(i))
    {
      auto j = label_renaming.find(l.transition_label(*it));
      if (j == label_renaming.end())
      {
        throw mcrl2::runtime_error("Error in renaming transition labels: could not find an image for " + pp(l.transition_label(*it)));
      }
      l.set_transition_label(*it, j->second);
      ++it;
    }
  }
}

template <typename LABEL>
void rename_action_labels(LTS<LABEL, detail::const_lts_explorer>& l, const std::map<LABEL, LABEL>& label_renaming)
{
  LTS<LABEL, detail::lts_explorer> r;
  for (std::size_t i = 0; i < l.num_states(); ++i)
  {
    r.add_state(l.state_label(i));
    typename LTS<LABEL, detail::const_lts_explorer>::outgoing_transition_iterator it = l.out(i);
    while (it != l.out_end(i))
    {
      auto j = label_renaming.find(l.transition_label(*it));
      if (j == label_renaming.end())
      {
        throw mcrl2::runtime_error("Error in renaming transition labels: could not find an image for " + pp(l.transition_label(*it)));
      }
      r.add_transition(i, l.transition_target(*it), j->second);
      ++it;
    }
  }
  l = LTS<LABEL, detail::lts_explorer>(r);
}

template <typename LABEL>
void rename_action_labels(buchi_lts<LABEL, lps::explorer>& l, const std::map<LABEL, LABEL>& label_renaming)
{
  for (std::size_t i = 0; i < l.num_states(); ++i)
  {
    buchi_lts<LABEL, lps::explorer>::outgoing_transition_iterator it = l.out(i);
    while (it != l.out_end(i))
    {
      auto j = label_renaming.find(l.transition_label(*it));
      if (j == label_renaming.end())
      {
        throw mcrl2::runtime_error("Error in renaming transition labels: could not find an image for " + pp(l.transition_label(*it)));
      }
      l.set_transition_label(*it, j->second);
      ++it;
    }
  }
}

template <typename LABEL>
void rename_action_labels(buchi_lts<LABEL, detail::const_lts_explorer>& l, const std::map<LABEL, LABEL>& label_renaming)
{
  buchi_lts<LABEL, detail::lts_explorer> r;
  for (std::size_t i = 0; i < l.num_states(); ++i)
  {
    r.add_state(l.state_label(i));
    buchi_lts<LABEL, detail::const_lts_explorer>::outgoing_transition_iterator it = l.out(i);
    while (it != l.out_end(i))
    {
      auto j = label_renaming.find(l.transition_label(*it));
      if (j == label_renaming.end())
      {
        throw mcrl2::runtime_error("Error in renaming transition labels: could not find an image for " + pp(l.transition_label(*it)));
      }
      r.add_transition(i, l.transition_target(*it), j->second);
      ++it;
    }
  }
  l = buchi_lts<LABEL, detail::lts_explorer>(r);
}

