/// \file lts_preprocess.h
/// \brief This is a header defining a number of functions that pre-process an LTS, removing redundant states and transitions.

#ifndef MCRL2_LTS_PREPROCESS_H
#define MCRL2_LTS_PREPROCESS_H

#include "mcrl2/utilities/unordered_map.h"
#include "mcrl2/lts/lts.h"
#include <set>
#include "mcrl2/lps/explorer.h"

namespace mcrl2
{
namespace lts
{

/// \brief Preprocesses an LTS by removing redundant states and transitions.
template < class LTS_TYPE, class EXPLORER >
void preprocess(LTS_TYPE& lts)
{
  typedef typename LTS_TYPE::state_type state_t;
  typedef typename LTS_TYPE::transition_label_t transition_label_t;
  typedef std::pair<state_t, transition_label_t> pair_t;
  typedef std::set<std::size_t> set_of_states_t;
  // For each state in the LTS, maintain a map from pairs of state labels and transition labels to sets of states.
  unordered_map<state_t, unordered_map<pair_t, set_of_states_t > > outgoing_transition_maps;
  for(std::size_t i=0; i < lts.num_states(); ++i)
  {
    LTS_TYPE::outgoing_transition_iterator it = lts.out_begin(i);
    while (it != lts.out_end(i))
    {
      pair_t label_pair = std::make_pair(lts.state_label(lts.transition_target(*it)), lts.transition_label(*it));
      outgoing_transition_maps[lts.state_label(i)][label_pair].insert(lts.transition_target(*it));
      ++it;
    }
  }
  LTS_TYPE::outgoing_transition_iterator it = lts.out_begin();
  while (it != lts.out_end())
  {
    pair_t label_pair = std::make_pair(lts.state_label(lts.transition_target(*it)), lts.transition_label(*it));
    if (outgoing_transition_maps[lts.state_label(lts.transition_source(*it))][label_pair].size() > 1)
    {
      // Remove the transition because it is redundant.
      lts.del_transition(lts.transition_source(*it), *it);
    }
    ++it;
  }
}

/// \brief Preprocesses an LTS by removing redundant states and transitions.
template < class LTS_TYPE >
void preprocess(LTS_TYPE& lts, typename LTS_TYPE::state_label_t p)
{
  typedef typename LTS_TYPE::transition_label_t transition_label_t;
  typedef std::pair<typename LTS_TYPE::state_type, transition_label_t> pair_t;
  typedef unordered_map<std::size_t, bool> set_of_states_t;
  // For each state in the LTS, maintain a map from pairs of state labels and transition labels to sets of states.
  unordered_map<typename LTS_TYPE::state_type, unordered_map<pair_t, set_of_states_t > > outgoing_transition_maps;
  for(std::size_t i=0; i < lts.num_states(); ++i)
  {
    LTS_TYPE::outgoing_transition_iterator it = lts.out_begin(i);
    while (it != lts.out_end(i))
    {
      pair_t label_pair = std::make_pair(lts.state_label(lts.transition_target(*it)), lts.transition_label(*it));
      outgoing_transition_maps[lts.state_label(i)][label_pair][lts.transition_target(*it)]=true;
      ++it;
    }
  }
  LTS_TYPE::outgoing_transition_iterator it = lts.out_begin();
  while (it != lts.out_end())
  {
    pair_t label_pair = std::make_pair(lts.state_label(lts.transition_target(*it)), lts.transition_label(*it));
    if (outgoing_transition_maps[lts.state_label(lts.transition_source(*it))][label_pair].size() > p)
    {
      // Remove the transition because it is redundant.
      lts.del_transition(lts.transition_source(*it), *it);
    }
    ++it;
  }
}

/// \brief Preprocesses an LTS by removing redundant states and transitions.
template < class EXPLORER >
void preprocess(EXPLORER& lts)
{
  return preprocess< typename EXPLORER::lts_t, EXPLORER >(lts);
}

/// \brief Preprocesses an LTS by removing redundant states and transitions.
template < class EXPLORER >
void preprocess(EXPLORER& lts, std::size_t p)
{
  return preprocess< typename EXPLORER::lts_t, EXPLORER >(lts,p);
}

