enum transition_info { has_no_transitions = 0, has_transition_labels = has_no_transitions + 1 };  /// \brief Additional information for the data structure of an LTS.

/// \brief The type that is used to store a state label in an LTS.
using state_label_t = std::size_t;

/// \brief The type that is used to store a transition label in an LTS.
struct transition_label_t
{
  std::size_t label;
};

inline
bool operator==(transition_label_t const& x, transition_label_t const& y)
{
  return x.label == y.label;
}

/// \brief The type that is used to store a transition in an LTS.
struct transition_t
{
  std::size_t target;
  transition_label_t label;
};

inline
bool operator==(transition_t const& x, transition_t const& y)
{
  return x.target == y.target && x.label == y.label;
}

/// \brief The type that is used to store a multi-action in an LTS.
struct multi_action_label_string_t
{
  std::vector<std::size_t> labels;
};
