namespace detail
{

template <class LABEL>
inline
void add_transition(LABEL label, std::vector<transition_label_t>& action_labels, std::vector<std::size_t>& transition_indices)
{
  action_labels.push_back({ label });
}

template <class LABEL>
inline
void add_transition(LABEL label, utilities::indexed_set<transition_label_t>& action_labels, std::vector<std::size_t>& transition_indices)
{
  auto i = action_labels.insert({ label });
  transition_indices.push_back(i.first->second);
}

} // namespace detail

/// \brief Adds a transition to an LTS, where labels are stored in a hash table (if possible). This can be used for both single and multi action LTS's.
template <class LABEL>
inline
void add_transition(LABEL label, std::vector<transition_label_t>& action_labels, std::vector<std::size_t>& transition_indices)
{
  detail::add_transition(label, action_labels, transition_indices);
}

/// \brief Adds a transition to an LTS, where labels are stored in a hash table (if possible). This can be used for both single and multi action LTS's.
template <class LABEL>
inline
void add_transition(LABEL label, utilities::indexed_set<transition_label_t>& action_labels, std::vector<std::size_t>& transition_indices)
{
  detail::add_transition(label, action_labels, transition_indices);
}

