namespace mcrl2 {

namespace lts {

/// \brief Exception for reporting LTS input/output errors.
class io_error : public mcrl2::runtime_error
{
  public:
    explicit io_error(const std::string& msg) : mcrl2::runtime_error(msg) {}
};

/// \brief Throws an exception if a stream is bad.
inline void check_istream(std::ifstream& is, const std::string& filename = "")
{
  if (is.fail())
  {
    throw io_error("Failed to read from file: " + filename);
  }
}

/// \brief Throws an exception if a stream is bad.
inline void check_ostream(std::ofstream& os, const std::string& filename = "")
{
  if (os.fail())
  {
    throw io_error("Failed to write to file: " + filename);
  }
}

/// \brief Throws an exception if a stream is bad.
inline void check_stream(std::ios& s, const std::string& filename = "")
{
  if (s.fail())
  {
    throw io_error("Failed to use file: " + filename);
  }
}

/// \brief Throws an exception if the number of arguments is not correct.
inline void check_num_args(const std::size_t n, const std::string& line)
{
  if (n < 1)
  {
    throw io_error("Failed to read LTS: incorrect number of arguments on line " + line);
  }
}

/// \brief Throws an exception if the state label is larger than the maximum allowed value.
inline void check_state_label(const std::size_t n)
{
  const std::size_t max = 1024*1024;
  if (n >= max)
  {
    throw io_error("Failed to read LTS: state label too large, must be less than " + std::to_string(max));
  }
}

/// \brief Throws an exception if the transition label is larger than the maximum allowed value.
inline void check_transition_label(const std::size_t n)
{
  const std::size_t max = 1024*1024;
  if (n >= max)
  {
    throw io_error("Failed to read LTS: transition label too large, must be less than " + std::to_string(max));
  }
}

/// \brief Throws an exception if the state or transition index is larger than the maximum allowed value.
inline void check_index(const std::size_t n)
{
  const std::size_t max = 1024*1024;
  if (n >= max)
  {
    throw io_error("Failed to read LTS: state or transition index too large, must be less than " + std::to_string(max));
  }
}

} // namespace lts

