#ifndef MCRL2_LTS_PREPROCESS_H
#define MCRL2_LTS_PREPROCESS_H

#include "mcrl2/lts/lts.h"
#include <vector>

namespace mcrl2 {

namespace lts {

/// \brief Removes states that are unreachable from an initial state of a labelled transition system (LTS).
template <typename STATE, typename ACTION>
void remove_unreachable_states(lts<STATE, ACTION>& l)
{
  // collect the reachable states
  std::vector<std::size_t> reachable;
  for (const auto& t : l.initial_transitions())
  {
    std::deque<std::size_t> stack = { t.to() };
    while (!stack.empty())
    {
      std::size_t i = stack.back();
      stack.pop_back();
      if (std::find(begin(reachable), end(reachable), i) == reachable.end())
      {
        reachable.push_back(i);
        for (const auto& t : l.out_transitions(i))
        {
          stack.push_back(t.to());
        }
      }
    }
  }
  // remove unreachable states
  std::vector<std::size_t> mapping(l.num_states(), std::size_t(-1)); // maps old indices to new ones
  for (std::size_t i = 0; i < reachable.size(); ++i)
  {
    mapping[reachable[i]] = i;
  }
  l = lts_apply(l, mapping);
}

/// \brief Preprocess a labelled transition system (LTS). Currently only removes unreachable states.
template <typename STATE, typename ACTION>
void preprocess(lts<STATE, ACTION>& l)
{
  remove_unreachable_states(l);
}

