#ifndef MCRL2_UTILITIES_INPUT_TOOL_H
#define MCRL2_UTILITIES_INPUT_TOOL_H

#include "mcrl2/utilities/command_line_interface.h"

namespace mcrl2 {

namespace utilities {

/// \brief Base class for tools that read one or more input files.
class input_tool : public command_line_interface
{
  protected:
    std::vector<std::string> m_input_filenames; // The list of input filenames
    tool_mode m_tool_mode = tool_read_write; // By default, tools support read and write operations.

    /// \brief Add common options for an input tool to the command line parser.
    void add_common_input_output_options(interface_description& desc)
    {
      desc.add_option("file", make_file_argument("INFILE"), "The name of the file from which to read");
    }

  public:

    /// \brief Constructor for an input tool, reading one or more files.
    explicit input_tool(const std::string& argv0)
      : command_line_interface("Tool that reads one or more input files.", argv0), m_input_filenames()
    { }

    /// \brief Constructor for an input tool, reading one file.
    explicit input_tool(const std::string& description, const std::string& argv0)
      : command_line_interface("Tool that reads one input file.", argv0), m_input_filenames()
    { }

    /// \brief Returns the list of filenames.
    const std::vector<std::string>& input_filenames() const
    {
      return m_input_filenames;
    }

    /// \brief Returns true if there is exactly one input filename.
    bool has_single_file() const
    {
      return m_input_filenames.size() == 1;
    }

    /// \brief Parse command line options and add your own.
    void parse_options(const command_line_parser& parser) override
    {
      m_tool_mode = parser.has_option("read-only") ? tool_read_write : tool_read_write;
      if (parser.has_argument("file"))
      {
        m_input_filenames = parser.values("file");
      }
    }
};

} // namespace utilities

} // namespace mcrl2

