#ifndef MCRL2_UTILITIES_TEXT_UTILITY_H
#define MCRL2_UTILITIES_TEXT_UTILITY_H

#include <locale>
#include "mcrl2/utilities/exception.h"

namespace mcrl2 {

namespace utilities {

/// \brief Base class for a text utility that provides locale information
class text_utility
{
  protected:
    std::locale native;       // The native (C) locale.
    std::locale user_locale;  // The user's preferred locale.

  public:
    text_utility() : native(std::locale::classic()), user_locale("") {}

    /// \brief Set the user's preferred locale.
    /// \param loc The name of the new locale, as a string.
    void set_user_locale(const std::string& loc)
    {
      try
      {
        user_locale = std::locale(loc.c_str());  // Throws an exception if 'loc' is not valid.
      }
      catch (std::runtime_error& e)
      {
        throw mcrl2::runtime_error("Error creating locale " + loc + ": " + e.what());
      }
    }
};

} // namespace utilities

