#ifndef MCRL2_UTILITIES_TIMER_H
#define MCRL2_UTILITIES_TIMER_H

#include <chrono>

namespace mcrl2 {

namespace utilities {

// Timer class.
class timer
{
  protected:
    std::chrono::time_point<std::chrono::steady_clock> start; // Start time of the operation

  public:
    timer() : start(std::chrono::steady_clock::now()) {}

    /// \brief Resets the timer. This is equivalent to a restart.
    void reset() { start = std::chrono::steady_clock::now(); }

    /// \brief Returns the time in seconds that has passed since creation or last reset.
    double elapsed() const
    {
      auto end = std::chrono::steady_clock::now();
      return std::chrono::duration<double>(end - start).count();
    }
};

} // namespace utilities

