#ifndef MCRL2_PBES_SOLVE_CARTESIAN_STATE_SPACE_GENERATOR_H
#define MCRL2_PBES_SOLVE_CARTESIAN_STATE_SPACE_GENERATOR_H

#include "mcrl2/pbes/detail/state_space_generator.h"

namespace mcrl2 {

namespace pbes_system {

template <typename Base>
class solve_cartesian_state_space_generator : public state_space_generator<Base>
{
  typedef state_space_generator<Base> super;
  using typename super::index_type;
  using super::m_pbes;
  using super::m_solution;
  using super::m_variable_generator;

public:
  solve_cartesian_state_space_generator(const pbes& p, std::vector<propositional_variable_instantiation> expected)
    : super(p, expected), m_current_state(-1)
  {}

protected:
  virtual void increment()
  {
    ++m_current_state;
    if (m_current_state >= static_cast<index_type>(m_variable_generator.size()))
    {
      m_current_state = -1; // signifies end of state space.
    }
  }

public:
  virtual void solve()
  {
    increment();
    super::solve();
    if (m_current_state == -1)
    {
      return;
    }

    for (auto& v : m_pbes.equations())
    {
      assert(v.variable().name() < m_solution.size());
      m_solution[v.variable().name()] = m_variable_generator[m_current_state][v.variable().name()];
    }
  }

protected:
  index_type m_current_state;
};

} // namespace pbes_system

} // namespace mcrl2

