#include "mcrl2/pbes/io.h"
#include "mcrl2/utilities/exception.h"

namespace mcrl2 {

namespace pbes_system {

/// \brief Exception for things that go wrong in the PBES solver.
class pbes_solve_error : public mcrl2::runtime_error
{
  public:
    template <typename... ARGUMENTS>
    explicit pbes_solve_error(const std::string& error_msg, ARGUMENTS... message)
      : runtime_error(error_msg, message...)
    {}
};

inline
void solve(const pbes& p, const data::variable_list& parameters, bool print_minimal = false, std::ostream* out = 0)
{
  detail::pbes_system::solve<false>(p, parameters, print_minimal, out);
}

inline
void solve_data(const pbes& p, const data::variable_list& parameters, bool print_minimal = false, std::ostream* out = 0)
{
  detail::pbes_system::solve<true>(p, parameters, print_minimal, out);
}

inline
void solve(const std::string& pbes_filename, const data::variable_list& parameters, bool print_minimal = false, std::ostream* out = 0)
{
  detail::pbes_system::solve<false>(pbes_filename, parameters, print_minimal, out);
}

inline
void solve_data(const std::string& pbes_filename, const data::variable_list& parameters, bool print_minimal = false, std::ostream* out = 0)
{
  detail::pbes_system::solve<true>(pbes_filename, parameters, print_minimal, out);
}

