class interactive_solver : public Base
{
  protected:
    /// \brief The data parameters of the PBES being solved.
    const data::variable_list& m_parameters;

    /// \brief A flag that indicates whether to print minimal solutions only, or all solutions as well.
    bool m_print_minimal;

  public:
    interactive_solver(const pbes& p, const data::variable_list& parameters, bool print_minimal)
      : Base(p), m_parameters(parameters), m_print_minimal(print_minimal)
    {}

    /// \brief Returns true if the current solution is minimal. This means that every variable occurs exactly once in it.
    bool is_solution_minimal() const
    {
      return Derived::is_solution_minimal();
    }
};

} // namespace pbes_system

} // namespace mcrl2

