/// \file parser.h
/// \brief This is a simple wrapper for the Bison class, which allows it to
/// be used as singleton.

#ifndef MCRL2_DATA_PARSER_H
#define MCRL2_DATA_PARSER_H

#include <string>
#include "mcrl2/data/typecheck.h"
#include "parser.hh"

namespace mcrl2
{

namespace data
{

class parser : public parser_bisonflex_base
{
  private:
    /// The type checker object, if any
    type_checker* m_typechecker;

    /// Indicates whether the last parse has been successful
    bool m_result;

  protected:
    // virtual void process_expression(const data::data_expression& x) = 0;

  public:
    parser(type_checker* typechecker = nullptr, const std::string& text = "")
      : parser_bisonflex_base(), m_typechecker(typechecker), m_result(true)
    {
      set_text(text);
    }

    ~parser() {}

    void error(const std::string &error_message, const yy::location& location)
    {
      parser_bisonflex_base::error(error_message);
    }

    //virtual void setLexerInput(std::istream* input);
    virtual void reset();

  public:
    bool parse()
    {
      reset();
      return m_result;
    }

    const data_expression& result() const
    {
      assert(!error_messages().empty());
      //return error_messages().back()->expr;
      return dynamic_cast<const syntax_tree_node*>(syntax_tree().top())->term();
    }

    /// \brief Returns whether the last parsing operation was successful.
    bool is_well_typed() const
    {
      return m_typechecker == nullptr || m_typechecker->is_well_typed(result());
    }

  protected:
    virtual void process_expression(const data::data_expression& x) = 0;
}; // class parser

} // namespace data

} // namespace mcrl2

