/// \file parse.cpp
/// \brief Test parsing of data expressions.

#define BOOST_TEST_MODULE parse
#include <boost/test/included/unit_test.hpp>
#include "mcrl2/data/parse.h"

using namespace mcrl2;

BOOST_AUTO_TEST_CASE(test_parse)
{
  using data::sort_expression;
  using data::sort_list;

  sort_list sigma("b: Bool;\n c: [Bool];\n");
  const sort_expression& b = sigma["b"];
  std::string text1 = "f(d)";
  data::data_expression x = data::parse_data_expression("f(d)", sigma);
  BOOST_CHECK(!x.is_true());

  sort_list delta;
  try {
    const data::variable d("d", b);
    std::string text2 = "b";
    x = data::parse_data_expression(text2, sigma);
  } catch (mcrl2::runtime_error& e) {
    BOOST_CHECK(std::string(e.what()) == "Error parsing data expression:\n   b\n^\nExpected sort after \"b\".\n");
  }
