BOOST_AUTO_TEST_CASE(test_basic)
{
  using data::parse_data_type;
  using data::basic_sort;

  basic_sort s = parse_data_type("Nat");
  BOOST_CHECK(!s.is_structured());
  BOOST_CHECK(s == basic_sort("Nat"));
}

BOOST_AUTO_TEST_CASE(test_list)
{
  using data::parse_data_type;
  using data::basic_sort;
  using data::structured_sort;

  structured_sort s = parse_data_type("List[Nat]");
  BOOST_CHECK(s.is_structured());
  BOOST_CHECK(std::distance(s.domain().begin(), s.domain().end()) == 1);
  BOOST_CHECK(*s.domain().begin() == basic_sort("Nat"));
