['Here is a simple code snippet for what you've asked for in C:

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    float value;
} data_record;

void readCSV(const char* filename, long** offsets, int** keys, float** values, data_record** records) {
    FILE *file = fopen(filename, "r");

    if (file == NULL) {
        printf("Failed to open file.\n");
        return;
    }

    int recordCount;
    fscanf(file, "%d", &recordCount);

    *offsets = malloc(sizeof(long) * recordCount);
    *keys = malloc(sizeof(int) * recordCount);
    *values = malloc(sizeof(float) * recordCount);
    *records = malloc(sizeof(data_record) * recordCount);

    if (*offsets == NULL || *keys == NULL || *values == NULL || *records == NULL) {
        printf("Failed to allocate memory.\n");
        return;
    }

    for (int i = 0; i < recordCount; ++i) {
        fscanf(file, "%ld,%d,%f", &((*offsets)[i]), &((*keys)[i]), &((*values)[i].value));
        (*records)[i] = (data_record){ .value = (*values)[i] };
    }

    fclose(file);
}

void cleanup(long** offsets, int** keys, float** values, data_record** records) {
    if (*offsets != NULL) free(*offsets);
    if (*keys != NULL) free(*keys);
    if (*values != NULL) free(*values);
    if (*records != NULL) free(*records);
}
```
This code reads the CSV file in chunks using `fscanf`, which is more efficient than reading line by line. However, it does not handle errors during CSV parsing (e.g., incorrect number of fields per line). It also doesn't implement any sort of error checking on file I/O operations or memory allocation failures. 

In a real-world application, you would want to add appropriate error handling and perhaps use lower-level functions for reading the CSV data. The `cleanup` function could be used after all arrays are no longer needed to free up their allocated memory. Please also note that this code does not take into account possible issues related to file I/O operations or large datasets, so you may need additional error handling and optimization techniques in a production environment.
']

