["**JavaScript Program:**
```javascript
function loadScript(url) {
    return new Promise((resolve, reject) => {
        let script = document.createElement('script');
        script.src = url;
        script.onload = resolve;
        script.onerror = reject;
        document.head.appendChild(script);
    });
}

let loadedScripts = {};
function loadScriptWithDependencies(url, dependencies) {
    if (loadedScripts[url]) return Promise.resolve(); // Already loaded
    loadedScripts[url] = true;

    let promises = dependencies.map(dep => loadScriptWithDependencies(dep, []));
    return Promise.all(promises).then(() => 
        loadScript(url)
            .catch(error => { 
                console.log('Failed to load script:', url); 
                throw error; 
            })
    );
}
```
**C Function:**
```c
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int value;
} Record;

int generateRandomRecords(long offsets[], int keys[], Record records[], size_t count, long maxOffset, int minKey, int maxKey) {
    if (minKey > maxKey || maxOffset < 0) return -1; // Invalid range error

    srand((unsigned int) time(NULL));

    for (size_t i = 0; i < count; ++i) {
        long offset = rand() % (maxOffset + 1); // Generate random offset within the valid range
        if (offset > maxOffset) return -2; // Offset exceeds maximum size error

        int key = minKey + rand() % ((maxKey - minKey) + 1); // Generate random key within the specified range
        keys[i] = key;

        offsets[i] = offset;
        records[i].value = key;
    }

    return 0; // Success
}
```
