};

void allocate_and_initialize_records(int numRecords, std::vector<record> &records){
    if (numRecords < 1 || numRecords > 1000) {
        throw std::out_of_range("Number of records should be between 1 and 1000.");
    }

    try{
        records.reserve(numRecords);

        for (int i = 0; i < numRecords; ++i) {
            int key = RandomNumberGenerator::RandomGenerator::generator();

            // ensure unique keys
            for(auto& r : records){
                while(r.key == key){
                    key = RandomNumberGenerator::RandomGenerator::generator();
                }
            }

            record newRecord;
            newRecord.key = key;
            records.push_back(newRecord);
        }
