['Here is an example of how you might implement this in C. It uses libyaml to parse YAML and handles memory allocation and deallocation properly using malloc and free. For the sake of brevity, I've omitted error checking that would be necessary for a production-level implementation:

```c
#include <stdlib.h>
#include <time.h>
#include <yaml.h>

typedef struct {
  uint32_t RX_UE_INFORMATION;
  uint16_t RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct {
  bool CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
  RX_UE_INFORMATION_TAG RX_UE_INFORMATION_tag;
  CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

void populate_structures(NFAPI_CRC_INDICATION_PDU_T **pdu, int n) {
  for (int i = 0; i < n; ++i) {
    pdu[i]->RX_UE_INFORMATION_tag.RX_UE_INFORMATION = rand(); // Set RX_UE_INFORMATION to a random value
    pdu[i]->RX_UE_INFORMATION_tag.RNTI = rand(); // Set RNTI to a random value
    pdu[i]->CRC_INDICATION_REL8_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to true or false
  }
}

NFAPI_CRC_INDICATION_PDU_T **create_structures(const char *config_file) {
  FILE *file = fopen(config_file, "r");
  yaml_parser_t parser;
  yaml_event_t event;
  int n = 0;

  if (!yaml_parser_initialize(&parser)) return NULL; // Failed to initialize parser

  yaml_parser_set_input_file(&parser, file);

  do {
    if (!yaml_parser_parse(&parser, &event)) break; // Parsing failed

    switch (event.type) {
      case YAML_SCALAR_EVENT:
        n = atoi((char*) event.data.scalar.value); // Parse number of structures from scalar value
        break;
      default:
        break;
    }

    yaml_event_delete(&event);
  } while (1);

  NFAPI_CRC_INDICATION_PDU_T **pdu = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T*)); // Allocate array of pointers to structures

  for (int i = 0; i < n; ++i) {
    pdu[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T)); // Allocate each structure in the array
  }

  populate_structures(pdu, n);

  yaml_parser_delete(&parser);
  fclose(file);

  return pdu;
}

void free_structures(NFAPI_CRC_INDICATION_PDU_T **pdu, int n) {
  for (int i = 0; i < n; ++i) {
    free(pdu[i]); // Free each structure in the array
  }

  free(pdu); // Free array of pointers to structures
}
```
Please note that this is a very basic example. In reality, you would need to add error checking and handle edge cases such as when YAML parsing fails or when memory allocation fails. Also, you might want to use a different method for reading the configuration from a file than just opening and closing it each time the function is called. This could be optimized by reading the configuration once at program startup and storing it in global variables.
