#include <stdlib.h>
#include <string.h>

typedef struct item {
    int value;
    char *string;
} item;

typedef struct log_record {
    int timestamp;
    int level;
    char *message;
} log_record;

void init_logging_system(int num_items, int num_strings, int num_records, 
                         const char **predefined_messages, 
                         item **pItems, char ***pStrings, log_record **pRecords) {

    *pItems = malloc(num_items * sizeof(item));
    if (*pItems == NULL) exit(-1); // handle malloc fail

    *pStrings = malloc(num_strings * sizeof(char*));
    if (*pStrings == NULL) exit(-1);  // handle malloc fail

    for (int i = 0; i < num_strings; ++i) {
        int length = strlen(predefined_messages[i]);
        (*pStrings)[i] = malloc(length + 1);
        if ((*pStrings)[i] == NULL) exit(-1); // handle malloc fail

        strncpy((*pStrings)[i], predefined_messages[i], length+1); 
    }

    *pRecords = malloc(num_records * sizeof(log_record));
    if (*pRecords == NULL) exit(-1); // handle malloc fail
}
```
