UEContextList* createList(size_t initialSize) {
    UEContextList *list = malloc(sizeof(UEContextList));
    list->contexts = calloc(initialSize, sizeof(UEContext));
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void addToList(UEContextList *list, UEContext context) {
    pthread_mutex_lock(&list->lock);
    list->contexts = realloc(list->contexts, (list->count + 1) * sizeof(UEContext));
    list->contexts[list->count] = context;
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

void deleteFromList(UEContextList *list, int ueId) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->contexts[i].ueId == ueId) {
            // delete the context
            free(list->contexts[i].measurementReport);

            for (size_t j = i; j < list->count - 1; ++j) {
                list->contexts[j] = list->contexts[j + 1];
            }

            list->count--;
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

