int* read_integer_list() {
    int capacity = 10;  // Initial capacity of the list.
    int size = 0;      // Number of elements in the list.

    int *list = malloc(capacity * sizeof(int));

    if (list == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory.\n");
        exit(EXIT_FAILURE);
    }

    while (scanf("%d", &list[size]) == 1) {
        ++size;

        if (size == capacity) {  // If list is full, double its size.
            int newCapacity = capacity * 2;

            // Reallocate memory for the list.
            int* tempList = realloc(list, newCapacity * sizeof(int));

            if (tempList == NULL) {
                fprintf(stderr, "Error: Failed to allocate memory.\n");
                exit(EXIT_FAILURE);
            } else {
                list = tempList;
                capacity = newCapacity;
            }
        }
    }

    // Trim the excess allocated memory.
    int* trimmedList = realloc(list, size * sizeof(int));

    if (trimmedList == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory.\n");
        exit(EXIT_FAILURE);
    } else {
        list = trimmedList;
        capacity = size;
    }

    return list;
}

int findMaxValueAndIndex(int* list, int n) {
    if (n == 0) {
        fprintf(stderr, "Error: List is empty.\n");
        exit(EXIT_FAILURE);
    }

    int maxValue = list[0];
    int maxIndex = 0;

    for (int i = 1; i < n; ++i) {
        if (list[i] > maxValue) {
            maxValue = list[i];
            maxIndex = i;
        }
    }

    return maxIndex;  // Return the index of the maximum value.
}
